   E8 - CONFERENCIA
   ===================================================================== */
SELECT TABELA='KZN_HIST_PEDRAVISAOCONSOLIDADA', LINHAS=COUNT(*) FROM CI.KZN_HIST_PEDRAVISAOCONSOLIDADA WHERE ID_KAIZEN BETWEEN 7281 AND 8280
UNION ALL SELECT 'KZN_HIST_MEMBROS_EQUIPE',     COUNT(*) FROM CI.KZN_HIST_MEMBROS_EQUIPE      WHERE ID_KAIZEN BETWEEN 7281 AND 8280
UNION ALL SELECT 'KZN_HIST_RESULTADO_KAIZEN',   COUNT(*) FROM CI.KZN_HIST_RESULTADO_KAIZEN    WHERE ID_KAIZEN BETWEEN 7281 AND 8280
UNION ALL SELECT 'KZN_HIST_KAIZEN_HIERARQUIA',  COUNT(*) FROM CI.KZN_HIST_KAIZEN_HIERARQUIA   WHERE ID_KAIZEN BETWEEN 7281 AND 8280
UNION ALL SELECT 'KZN_HIST_KAIZEN_DESPERDICIO', COUNT(*) FROM CI.KZN_HIST_KAIZEN_DESPERDICIO  WHERE ID_KAIZEN BETWEEN 7281 AND 8280;
