INSERT INTO #PVC VALUES (7592, 81013108, 81013108, N'Hose Storage ', NULL, N'Others/Outros', N'hose never had a proper storage location ', N'organization ', 0, N'01 - Imagens/01 - Antes/7592.jpeg', N'hose never had proper storage location ', N'01 - Imagens/02 - Depois/7592.jpeg', N'hose storage location created ', NULL, N'n/a', N'n/a', 2, 3, N'Tempo menor para o planejamento
INSERT INTO #PVC VALUES (7593, 550575, 550575, N'FABRICAÇÃO DE SUPORTE HORIZONTAL EXCÊNTRICO', NULL, N'No Replication/Sem replicação', N'Devido ausência da Coroa instalada no excêntrico o suporte existente que é vertical não atende, pois fica condição insegura de transporte.', N'TRANSPORTE SEGURO', 10081, N'01 - Imagens/01 - Antes/7593.jpeg', N'Rotor sem a coroa instalada, assim não sendo possível travamento no suporte  vertical com projeto anterior.', N'01 - Imagens/02 - Depois/7593.jpeg', N'Foi solicitado a elaboração de um novo projeto na condição atual do Excêntrico sem a coroa e na horizontal.', NULL, N'Sim, com a elaboração novo projeto foi possível realizar transporte do componente na Horizontal.', N'Adequação componente, para transporte seguro', 0, NULL, N'Sustentação da padronização ao longo do tempo
INSERT INTO #PVC VALUES (7594, 81034722, 81034722, N'Quadro de FMDS e avisos da Área de manutenção do 320', NULL, N'Others/Outros', N'Não tínhamos um quadro de avisos e de checklists das ferramentas usadas na área de manutenção do 320.', N'Organização e padronização ', 10140, N'01 - Imagens/01 - Antes/7594.jpeg', N'Na área de ,manutenção do 320 não tínhamos um quadro de FMDS e nem um local para  colocar avisos, documentos e checklists', N'01 - Imagens/02 - Depois/7594.jpeg', N'Foi criado quadros de FMDS, avisos de férias e outros, Checklists de ferramentas e instalados no container da manutenção transporte localizado no estacionamento do 320.', NULL, N'sim, foi resolvido porque agora no local de trabalho as informações e documentos necessários para realizar as atividades. ', N'Toda área de trabalho deve ser organizada.', 0, NULL, N'Technicians will save time and effort by using the quick reference guide posted', '2026-01-20T00:00:00.000', '2026-01-22T17:35:51.000', 81034722, NULL, 1);
INSERT INTO #PVC VALUES (7595, 81035388, 81035388, N'Melhorar a visibilidade do operador', NULL, N'No Replication/Sem replicação', N'O operador tinha maior dificuldade de visualizar a frente da máquina, em função do posicionamento da tela LINC´S à frente do posto de operação.', N'Melhorar o campo de visão do operador em relação à frente da máquina', 10257, N'01 - Imagens/01 - Antes/7595.jpeg', N'Antes, o operador tinha dificuldade de visibilidade na frente da máquina devido ao posicionamento da tela do Linc´s.', N'01 - Imagens/02 - Depois/7595.jpeg', N'Após o reposicionamento da tela Linc´s, a visibilidade do operador foi melhorada.', NULL, N'Sim, foi resolvido o problema de visibilidade do operador ', N'Trabalhar com mais segurança ', 8, 1, N'Execução que era de aproximadamente 2 dias pode ser feito em menos de 20 minutos. ', '2026-01-21T00:00:00.000', '2026-01-22T18:36:32.000', 81035388, NULL, 3);
INSERT INTO #PVC VALUES (7596, 81034443, 81034443, N'Fumódromo: Implementação de Área fumante Segura e Organizada. ', NULL, N'Others/Outros', N'Fumantes estavam espalhados pelo local de trabalho, aumentando o risco de incêndio e criando um ambiente desorganizado, afetando a saúde e segurança dos colaboradores.', N'Reduzir os riscos de incêndio e melhorar a organização dos fumantes, promovendo um ambiente de trabalho mais seguro e saudável.', 10140, N'01 - Imagens/01 - Antes/7596.jpeg', N'Fumantes estavam espalhados pelo local de trabalho, aumentando o risco de incêndio e criando um ambiente desorganizado, afetando a saúde e segurança dos colaboradores.', N'01 - Imagens/02 - Depois/7596.jpeg', N'- Adicionado um recipiente para descarte de bitucas de cigarro.
INSERT INTO #PVC VALUES (7597, 81039085, 81039085, N'PROTEÇÃO BP-2020SA-33', NULL, N'Projects/Projetos', N'Bomba de polpa BP-2020SA-33 está instalada com uma proteção fechada e de difícil acesso, o que compromete a ventilação do acionamento e leva ao aumento da temperatura. 
INSERT INTO #PVC VALUES (7598, 81014703, 81014703, N'Cartão de TAGS para Preenchimento do Sistema Nautilus', NULL, N'Others/Outros', N'Toda vez que uma atividade é realizada, é necessário preencher o sistema Nautilus com as TAGs dos equipamentos atendidos.
INSERT INTO #PVC VALUES (7599, 81035621, 543422, N'Etiqueta de informação', NULL, N'Others/Outros', N'Falta de informação visível na seletora de subir e descer a escada retrátil.', N'Padronização visual', 10324, N'01 - Imagens/01 - Antes/7599.jpeg', N'Falta de informação visível na seletora de subir e descer a escada retrátil.', N'01 - Imagens/02 - Depois/7599.jpeg', N'Etiquetado informações para facilitar o acionamento correto da seletora de acionamento da escada retrátil.', NULL, N'Sim, o problema foi resolvido com a implementação do etiquetado na seletora da escada retrátil, garantindo o acionamento correto e reduzindo o risco de erro operacional. ', N'Melhoria na padronização visual', 0, NULL, NULL, '2026-01-22T00:00:00.000', '2026-01-23T01:34:35.000', 81035621, NULL, 3);
INSERT INTO #PVC VALUES (7600, 81045244, 81045244, N'Weight Storage Area', NULL, N'No Replication/Sem replicação', N'Required a designated storage area for new 211 weights. Weights needed to be out of the weather and free from contamination.', N'Create a 5s area for weights', 10271, N'01 - Imagens/01 - Antes/7600.jpeg', N'Area needed for storing new weights for 211 weigh scale.', N'01 - Imagens/02 - Depois/7600.jpeg', N'Created 5s area in the old lime laydown for weights so the weights are out of the elements and not getting contaminated. ', NULL, N'Yes problem solved', N'5s area established', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (7601, 547290, 547290, N'Acesso seguro ', NULL, N'No Replication/Sem replicação', N'Durante as atividades de descarregamento de insumos na área próxima ao silo de bolas e ao galpão da cal, foi identificado um ponto de acesso sem portão ou barreira física. Essa abertura permitia a circulação de pessoas durante o processo de descarregamento, criando uma condição insegura devido à movimentação de caminhões e equipamentos', N'Isolar a área ', 10054, N'01 - Imagens/01 - Antes/7601.jpeg', N'Durante as atividades de descarregamento de insumos na área próxima ao silo de bolas e ao galpão da cal, foi identificado um ponto de acesso sem portão ou barreira física. Essa abertura permitia a circulação de pessoas durante o processo de descarregamento, criando uma condição insegura devido à movimentação de caminhões e equipamentos', N'01 - Imagens/02 - Depois/7601.jpeg', N'Foi instalado um portão para limitar o acesso de pessoas durante a movimentação de cargas, garantindo a segregação da área e reduzindo o risco de acidentes por atropelamento.
INSERT INTO #PVC VALUES (7602, 81044397, 81044397, N'Melhorar a organização, padronização e eficiência do processo de limpeza por meio da criação/otimização de um suporte adequado para placas de limpeza, garantindo fácil acesso, melhor conservação e uso correto.', NULL, N'No Replication/Sem replicação', N'As placas de limpeza não possuíam um local padronizado para armazenamento, ficando apoiadas de forma inadequada ou espalhadas pelo setor. Essa situação gerava desorganização, dificuldade de acesso, aumento do tempo de procura, risco de danos às placas e falta de conformidade com os princípios de 5S e segurança.', N'Reduzir em 100% o armazenamento inadequado das placas,Garantir 100% de conformidade com os padrões de organização e 5S', 10106, N'01 - Imagens/01 - Antes/7602.jpeg', N'As placas de limpeza não possuíam um local padronizado para armazenamento, ficando apoiadas de forma inadequada ou espalhadas pelo setor. Essa situação gerava desorganização, dificuldade de acesso, aumento do tempo de procura, risco de danos às placas e falta de conformidade com os princípios de 5S e segurança.', N'01 - Imagens/02 - Depois/7602.jpeg', N'Desenvolver suporte para placas de limpeza, Definir local padrão,mplantar o suporte', NULL, N'As placas de limpeza não possuíam local padronizado para armazenamento, gerando desorganização, dificuldade de acesso, aumento do tempo de procura, risco de danos e não conformidade com os princípios de 5S.', N'A padronização é essencial para manter a organização e evitar retrabalho.', 0, NULL, N'Definição de metas de MTBF e MTTR mais confiáveis, padronizadas e tecnicamente justificáveis, com maior previsibilidade no planejamento da manutenção e pleno alinhamento aos indicadores orçamentários de DF e UF.', '2026-01-20T00:00:00.000', '2026-01-23T09:41:50.000', 81044397, NULL, 3);
INSERT INTO #PVC VALUES (7603, 81038842, 81038842, N'Aplicação do lubrificador Automático', NULL, N'Others/Outros', N'apresentando risco de lubrificação insuficiente, maior desgaste dos componentes mecânicos e necessidade de intervenções manuais frequentes, aumentando o risco de falhas e paradas não programadas', N'Auxiliar na lubrificação ', 10300, N'01 - Imagens/01 - Antes/7603.jpeg', N'O motor operava sem lubrificação automática adequada no ponto crítico, apresentando risco de lubrificação insuficiente, maior desgaste dos componentes mecânicos e necessidade de intervenções manuais frequentes, aumentando o risco de falhas e paradas não programadas.', N'01 - Imagens/02 - Depois/7603.jpeg', N'Foi realizada a instalação/aplicação do lubrificador automático no motor, garantindo fornecimento contínuo e controlado de lubrificante no ponto correto. A melhoria assegura lubrificação eficiente, redução do desgaste dos componentes, aumento da vida útil do equipamento, maior confiabilidade operacional e melhoria nas condições de segurança e manutenção.', NULL, N'Sim, não ouve mais aquecimento nem aumento de atrito por falta de lubrificante ', N'Que podemos modernizar os nosso equipamento e ter mais ganho na produção.', 0, NULL, N'A implementação do intertravamento por baixa pressão na sucção aumenta diretamente a produtividade do sistema de bombeamento ao evitar falhas prematuras e paradas não programadas do conjunto motor‑bomba', '2026-01-23T00:00:00.000', '2026-01-23T10:34:10.000', 81038842, NULL, 3);
INSERT INTO #PVC VALUES (7604, 539450, 539450, N'Lista de tarefa - Calibrar e equalizar suspensão 785', NULL, N'Others/Outros', N'Demora na criação dos passos de elaboração para a
