INSERT INTO #PVC VALUES (7723, 550508, 541883, N'Painel de acompanhamento de reforma', NULL, N'Others/Outros', N'Foi constatada a inexistência de acompanhamento técnico e operacional da reforma em execução, gerando risco de falhas, retrabalho e desvios de planejamento.”', N'otimizar o fluxo operacional', 10081, N'01 - Imagens/01 - Antes/7723.jpeg', N'Foi constatada a inexistência de acompanhamento técnico e operacional da reforma em execução, gerando risco de falhas, retrabalho e desvios de planejamento.”', N'01 - Imagens/02 - Depois/7723.jpeg', N' “Gestão à vista da reforma implantada, garantindo transparência, acompanhamento e controle das etapas executadas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Poblema de informaçao resolvido', N'A implantação da gestão à vista é essencial para garantir acompanhamento contínuo das reformas, evitando falhas, retrabalho e perda de alinhamento entre as equipes.”', 0, NULL, N'Seal water supplied to all pumps with no leaks present', '2026-01-27T00:00:00.000', '2026-01-28T16:31:49.000', 550508, NULL, 3);
INSERT INTO #PVC VALUES (7724, 472995, 472995, N'ELIMINANDO AVARIAS NA CORREIA', NULL, N'Refining/Refino', N'VARIAS OBSTRUÇÃO NO CHUTE DE ALIMENTAÇÃO DA CORREIA 2101TC02 COM VARIOS TRANSBORDO DE MATERIAL NO RETORNO DA CORREIA E ENTRE OS TAMBORES CAUSANDO AVARIAS SEVERAS NA CORREIA TRANSPORTADORA.', N'REDUZIR 60% DAS AVARIAS, FUROS, CORTES ETC.', 10362, N'01 - Imagens/01 - Antes/7724.jpeg', N'VARIAS OBSTRUÇÃO NO CHUTE DE ALIMENTAÇÃO DA CORREIA 2101TC02 COM VARIOS TRANSBORDO DE MATERIAL NO RETORNO DA CORREIA E ENTRE OS TAMBORES CAUSANDO AVARIAS SEVERAS NA CORREIA TRANSPORTADORA.', N'01 - Imagens/02 - Depois/7724.jpeg', N'CORREÇÃO E INTALAÇÃO DOS REVERTIMENTOS, INSTALAÇÃO DE 2 LIMPADORES DE CORREIA, INSTALAÇÃO DA TAMPA DIANTEIRA NO CHUTE DE ALIMENTAÇÃO DA CORREIA 2101TC02.', NULL, N'SIM PROBREMA RESOLVIDO', N'REVERTIMENTOS ADEQUADOS', 50000, 1, N'FOI REALIZADO A MUDANÇA DO LOCAL DE ABASTECIMENTO DE ELC, ASSIM TIRANDO O EMPREGADO DOS RISCOS DE QUEDA, ERGONOMICO E QUEIMADURAS. O LOCAL DE ABASTECIMENTO FOI TRANSFERIDO PARA A PARTE INFERIOR DA MÁQUINA. ', '2026-01-26T00:00:00.000', '2026-01-28T17:03:59.000', 472995, NULL, 1);
