INSERT INTO #PVC VALUES (7726, 81047846, 81047846, N'CONTROLE DE SUBSTITUIÇÃO DE BATERIAS EC-13', NULL, N'Others/Outros', N'ATIVOS DA FROTA DE ESCAVADEIRA HIDRAULICAS DE GRANDE PORTE SE ENCONTRAVAM SEM NENHUM CONTROLE DE SUBSTITUIÇÃO DE BATERIAS.', N'OBTER UM CONTROLE DE SUBSTITUIÇÃO DE BATERIAS DA FROTA DE ESCAVADEIRAS HIDRAULICAS PC 5500-6D', 10324, N'01 - Imagens/01 - Antes/7726.jpeg', N'BATERIAS DO ATIVO EC-13 SE ENCONTRAVAM SEM NENHUM HISTORICO/CONTROLE DE SUBSTITUIÇÃO DAS MESMAS, IMPOSSIBILITANDO A VERIFICAÇÃO DA QUANTIDADE DE HORAS DE SUA VIDA UTIL EM OPERAÇÃO', N'01 - Imagens/02 - Depois/7726.jpeg', N'APLICADO UMA PASTA FIXADA NA SALA ELETRICA DO EQUIPAMENTO COM UM CONTROLE DE SUBSTITUIÇÃO DE BATERIAS DE ATIVO EC-13 MELHORANDO A VISUALIZAÇÃO DO HISTORICO E O CONTROLE DE SUBSTITUIÇÃO DE BATERIAS.', NULL, N'sim', N'controle de substituição de baterias', 0, NULL, N'N/A', '2026-01-22T00:00:00.000', '2026-01-28T21:54:46.000', 81047846, NULL, 3);
INSERT INTO #PVC VALUES (7727, 460346, 1009279, N'Chute Replacement', NULL, N'Refining/Refino', N'Chute for the press was causing the solids to empty outside the bin.', N'Have all the solids go into the bin', 0, N'01 - Imagens/01 - Antes/7727.jpeg', N'Chute for the press was causing the solids to empty outside the bin requiring the technician to shovel them up after emptying the press.  ', N'01 - Imagens/02 - Depois/7727.jpeg', N'Chute replaced and repostioned to ensure solids remained inside the bin.', NULL, N'YES', N'Replace when necessary', 0, NULL, N'IDENTIFICAÇÃO DE FREQUÊNCIA DE FALHA PARA DEFEITO ELÉTRICO.', '2026-01-28T00:00:00.000', '2026-01-29T00:37:47.000', 460346, NULL, 1);
INSERT INTO #PVC VALUES (7728, 81054991, 81017050, N'Identificação de calços', NULL, N'Others/Outros', N'Foi confeccionado placas de sinalização dos suportes dos calços dos equipamentos na areia do U&M320', N'identificar/ organizar', 0, N'01 - Imagens/01 - Antes/7728.jpeg', N'Não tinha identificação para o suporte dos calços e os mesmos ficavam desorganizado e feita a solicitação para gerar placas de identificação dos mesmos', N'01 - Imagens/02 - Depois/7728.jpeg', N'Após a realização das placas os calços passou a ser organizado de forma mais eficiente e visível.', NULL, N'O problema da desorganização dos calços foi resolvido com sucesso', N'organização', 0, NULL, N'Goal accomplished', '2026-01-28T00:00:00.000', '2026-01-29T04:07:19.000', 81054991, NULL, 1);
INSERT INTO #PVC VALUES (7729, 81053608, 81053608, N' lavagem do box ', NULL, N'Open Pit/Poço aberto', N'Oficina centralizada sem agua encanada com pressão para lavar oficina, sendo necessário o auxilio de um caminhão pipa que nem sempre tem disponibilidade', N'realizar a limpeza do box e lavar perifericos', 0, N'01 - Imagens/01 - Antes/7729.jpeg', N'Oficina centralizada sem agua encanada com pressão para lavar oficina, sendo necessário o auxilio de um caminhão pipa que nem sempre tem disponibilidade', N'01 - Imagens/02 - Depois/7729.jpeg', N'Hoje temos uma bomba d''água que secciona do totebim possibilitando a lavar oficina e periféricos ', NULL, N'Sim, pois temos o recuso que atende nossas necessidades e demandas', N'criatividade para procurar soluções para área visando segurança e agilidade', 0, NULL, N'Melhora na percepção de identidade da área, informação mais acessível para acompanhamento do próprio Time.', '2026-01-28T00:00:00.000', '2026-01-29T04:30:26.000', 81053608, NULL, 3);
INSERT INTO #PVC VALUES (7730, 81054991, 81017050, N'Organização 5S', NULL, N'Projects/Projetos', N'os armários e mesas não possuíam identificação ', N'organizar e padronizar', 0, N'01 - Imagens/01 - Antes/7730.jpeg', N'armário se encontrava sem identificação, causando desorganização do mesmo. ', N'01 - Imagens/02 - Depois/7730.jpeg', N'agora com identificação do armário as chaves foram organizada de forma mais eficiente e visível evitando ficarem espalhadas', NULL, N'sim', N'5s', 0, NULL, N'SIM', '2026-01-28T00:00:00.000', '2026-01-29T04:38:40.000', 81054991, NULL, 1);
INSERT INTO #PVC VALUES (7731, 460346, 81023780, N'Backwash Solids Storage', NULL, N'Refining/Refino', N'Storage is required for our backwash press solids in cobalt SX', N'Make storage', 0, N'01 - Imagens/01 - Antes/7731.jpeg', N'Recently our backwash filter press in Co is producing more solids and this required us to modify how we empty it and create solids storage.  The picture is of the tote without the label', N'01 - Imagens/02 - Depois/7731.jpeg', N'We made an area to store the clean pack for solids and labelled it as such, as shown in the attached photos', NULL, N'Yes', N'Change management ', 0, NULL, N'Segurança operacional', '2026-01-28T00:00:00.000', '2026-01-29T04:49:03.000', 460346, NULL, 1);
INSERT INTO #PVC VALUES (7732, 81054991, 81017050, N'5S', NULL, N'Projects/Projetos', N'ausência de identificação das mesas', N'5S organização', 0, N'01 - Imagens/01 - Antes/7732.jpeg', N'as mesas se encontravam sem identificação ou fora do padrão', N'01 - Imagens/02 - Depois/7732.jpeg', N'agora com a identificação as mesas ficaram mais organizadas', NULL, N'sim', N'5S', 0, NULL, N'SIM', '2026-01-28T00:00:00.000', '2026-01-29T04:51:35.000', 81054991, NULL, 1);
INSERT INTO #PVC VALUES (7733, 460346, 1014901, N'H2S line signage', NULL, N'Refining/Refino', N'H2S lines in Cd run above the Nitrogen bank', N'Add signage to alert of H2S in lines above', 0, N'01 - Imagens/01 - Antes/7733.jpeg', N'H2S lines run over the Nitrogen bank and storage area.  ', N'01 - Imagens/02 - Depois/7733.jpeg', N'Signage add to ensure people moving the nitrogen bank know to be careful when adding and removing cylinders', NULL, N'YES', N'More information is better', 0, NULL, N'Após a implantação, as equipes de manutenção e operação relataram maior confiança na realização das atividades, além de uma percepção clara de redução de riscos associados à baixa visibilidade. A solução também contribuiu para maior conformidade com padrões de segurança e boas práticas industriais, elevando o nível de controle operacional no setor.', '2026-01-28T00:00:00.000', '2026-01-29T05:04:58.000', 460346, NULL, 1);
INSERT INTO #PVC VALUES (7734, 81039718, 81039718, N'Mill Lube Program PM Optimization - Phase 1', NULL, N'Underground/Subterrâneo', N'The current PMs that are scheduled for Mill Lube Techs are not efficient and schedule loading was sub-optimal.', N'To optimize Mill Lube Tech planned routes.', 10096, N'01 - Imagens/01 - Antes/7734.jpeg', N'- Many lube routes were not defined with tasks or procedures.
INSERT INTO #PVC VALUES (7735, 1008463, 460565, N'Charger Cord Supplement', NULL, N'Refining/Refino', N'Charging cords did not come with the new chargers, and the price on them were expensive', N'More cost effective alternative', 10112, N'01 - Imagens/01 - Antes/7735.jpeg', N'Charging cords did not come with the new chargers, and the price on them were expensive', N'01 - Imagens/02 - Depois/7735.jpeg', N'Sourced a much cheaper alternative and chargers were able to be used', NULL, N'Yes.  Chargers were able to be used', N'None', 150, 3, N'less down time and production loss', '2026-01-27T00:00:00.000', '2026-01-29T08:10:07.000', 1008463, NULL, 1);
INSERT INTO #PVC VALUES (7736, 1008463, 460565, N'New seal water header labeling', NULL, N'No Replication/Sem replicação', N'Major process water leak in Cu Ew.', N'No process water leak in the building', 10112, N'01 - Imagens/01 - Antes/7736.jpeg', N'Major process water leak in Cu Ew', N'01 - Imagens/02 - Depois/7736.jpeg', N'A new process water header was installed, which bypassed the bad section of the line.  Labeling was put on the header indicating what each take off on the header was supplying', NULL, N'There are no longer any process water leaks in the building', N'None', 0, NULL, N'cuidado com um todo ', '2026-01-27T00:00:00.000', '2026-01-29T08:19:03.000', 1008463, NULL, 1);
INSERT INTO #PVC VALUES (7737, 553135, 81016943, N'MELHORIA NO ABASTECIMENTO DE ELC - CA''s', NULL, N'Others/Outros', N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'REDUZIR A EXPOSIÇÃO DO EMPREGADO AO RISCO DE QUEIMADURAS, QUEDAS, RISCO ERGONOMICO', 10139, N'01 - Imagens/01 - Antes/7737.jpeg', N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'01 - Imagens/02 - Depois/7737.jpeg', N'FOI REALIZADO A MUDANÇA DO LOCAL DE ABASTECIMENTO DE ELC, ASSIM TIRANDO O EMPREGADO DOS RISCOS DE QUEDA, ERGONOMICO E QUEIMADURAS. O LOCAL DE ABASTECIMENTO FOI TRANSFERIDO PARA A PARTE INFERIOR DA MÁQUINA. ', NULL, N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'OBSSEÇÃO POR SEGURANÇA ', 0, NULL, N'OTIMIZAÇÃO DO TEMPO DE CHECAGEM DA FALHA  NA TELA ', '2026-01-26T00:00:00.000', '2026-01-29T09:30:16.000', 553135, NULL, 1);
INSERT INTO #PVC VALUES (7738, 81011242, 81047743, N'Máquina Água Pura ', NULL, N'Others/Outros', N'A equipe realizava a limpeza de fachadas utilizando extensores, mangueiras e limpador multiuso, o que demandava maior tempo de execução e aumentava a exposição ao risco de fadiga física, devido ao esforço repetitivo e à postura prolongada durante a atividade.', N'A "Água Pura" é um equipamento voltado para a limpeza de vidros e superfícies não porosas, utilizando água 100% purificada. O sistema opera por meio de extensores que permitem alcançar áreas de até 16 metros de altura, garantindo uma limpeza eficiente, segura e sem a necessidade de produtos químicos.', 10017, N'01 - Imagens/01 - Antes/7738.jpeg', N'A equipe realizava a limpeza de fachadas utilizando extensores, mangueiras e limpador multiuso, o que demandava maior tempo de execução e aumentava a exposição ao risco de fadiga física, devido ao esforço repetitivo e à postura prolongada durante a atividade.', N'01 - Imagens/02 - Depois/7738.jpeg', N'Foi implantado o equipamento Água Pura para a limpeza de vidros e superfícies não porosas, utilizando água 100% purificada e um sistema de extensores com alcance de até 16 metros de altura. A solução proporciona uma redução de até 75% no tempo de limpeza, elimina o uso de produtos químicos, não deixa marcas nos vidros e opera com baixa pressão. Com isso, garante mais segurança, agilidade, qualidade no serviço e menor esforço físico para as colaboradoras.', NULL, N'A solução implantada atendeu plenamente à meta inicial de modernizar o processo de limpeza de fachadas e vidros. A substituição dos métodos manuais (extensores, mangueiras e limpador multiuso) pela Máquina Água Pura solucionou os principais problemas identificados:
INSERT INTO #PVC VALUES (7739, 81002390, 81002390, N'Reutilização de Garrafas com Alças Ergonômicas Reforçadas', NULL, N'Others/Outros', N'As garrafas térmicas utilizadas na área apresentavam recorrência de quebra das alças originais devido ao tempo de uso, exposição ao sol e ressecamento do material. Com as alças danificadas ou ausentes, as garrafas cheias eram carregadas segurando-as pelo corpo, o que deslocava o peso para frente, gerando desconforto ergonômico, risco de lesão e aumentando a probabilidade de queda da garrafa.', N'Redução do risco de fadiga muscular e desconforto ao colaborador, redução do risco de acidentes por queda de garrafas devido à falta de alças, redução de custos com aquisição de novas garrafas', 10361, N'01 - Imagens/01 - Antes/7739.jpeg', N'As garrafas térmicas utilizadas na área apresentavam recorrência de quebra das alças originais devido ao tempo de uso, exposição ao sol e ressecamento do material. Com as alças danificadas ou ausentes, as garrafas cheias eram carregadas segurando-as pelo corpo, o que deslocava o peso para frente, gerando desconforto ergonômico, risco de lesão e aumentando a probabilidade de queda da garrafa.', N'01 - Imagens/02 - Depois/7739.jpeg', N'Para reaproveitar as garrafas ainda funcionais e eliminar a condição insegura, foram implementadas novas alças confeccionadas com corda resistente, revestidas com mangueira de borracha para maior conforto e firmeza no transporte. Essa solução prolonga a vida útil das garrafas, evita o descarte desnecessário e proporciona melhor ergonomia e segurança aos colaboradores durante o manuseio.', NULL, N'Sim', N'Reaproveitamento', 0, NULL, N'Garantir comunicação mais rápida, clara e padronizada da programação de desmonte, reduzindo erros e o tempo de atualização da placa.', '2026-01-28T00:00:00.000', '2026-01-29T09:52:07.000', 81002390, NULL, 3);
INSERT INTO #PVC VALUES (7740, 501925, 501925, N'CÁLCULO PARA FREQUÊNCIA DE DEFEITO ELÉTRICO DYNAMOX', NULL, N'Others/Outros', N'ANTES ERA REALIZADO O CADASTRO DA FREQUÊNCIA DE DEFEITO ELÉTRICO COM O VALOR DE 120HZ, O QUE ERA INEFICIENTE PARA ANÁLISE DE MOTORES COM ROTAÇÃO VARIÁVEL. A FREQUÊNCIA VARIA MUITO DO VALOR DE 120HZ.', N'IDENTIFICAR A FREQUÊNCIA DE DEFEITO ELÉTRICO EM MOTORES DE ROTAÇÃO VARIÁVEL', 10178, N'01 - Imagens/01 - Antes/7740.jpeg', N'Para diagnóstco de defeitos elétricos era considerada a frequência de  120HZ, porém os equipamentos da flotação possuem rotação variável, sendo necessário calcular manualmente as frequências de falha em função da RPM no instante da coleta.
INSERT INTO #PVC VALUES (7741, 81017062, 300658, N'New throat bar covers', NULL, N'Underground/Subterrâneo', N'Existing throat bar covers are difficult to install and prone to corrosion decreasing maintenance productivity', N'Maintenance Productivity Improvement', 10238, N'01 - Imagens/01 - Antes/7741.jpeg', N'Old covers prone to corrosion making it difficult to install and remove decreasing maintenance productivity', N'01 - Imagens/02 - Depois/7741.jpeg', N'New covers use tapered wedges to lock instead of threads, preventing corrosion', NULL, N'Goal accomplished', N'Good work team', 0, NULL, N'Redução de tempo para iniciar a atividade e tempo de exposição de deslocamento dentro da mina. ', '2026-01-27T00:00:00.000', '2026-01-29T11:41:11.000', 81017062, NULL, 1);
INSERT INTO #PVC VALUES (7742, 81007480, 544568, N'Relatório Integrado de CAPEX e OPEX', NULL, N'Projects/Projetos', N'Relatórios de CAPEX e OPEX eram gerados em bases distintas, com padrões diferentes, o usuário acessava 2 plataformas para acompanhar. A atualização consumia tempo e tinha risco de inconsistências.', N'Integrar os relatórios de CAPEX e OPEX em uma única plataforma padronizada', 0, N'01 - Imagens/01 - Antes/7742.jpeg', N'Os usuários acompanhavam os gastos de OPEX pelo BI e recebiam CAPEX por e mail com imagens e anexos do excel. Os formatos distintos geravam desconforto visual e dificultavam o acesso às informações.', N'01 - Imagens/02 - Depois/7742.jpeg', N'CAPEX e OPEX passaram a ser consolidados em uma plataforma única e padronizada, eliminando a consolidação manual, reduzindo tempo de atualização e aumentando a confiabilidade e agilidade para o usuário.', N'https://app.powerbi.com/groups/me/apps/324ad6c5-57f4-4a3b-8805-0d2b8ab29ff3/reports/e33f4391-66ca-4d2a-913d-1148490d7c75/35fc33daed0d716d76cd?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim, foi resolvido. CAPEX e OPEX estão no BI com atualização diária; o usuário navega facilmente nas duas visões, sem risco de erro humano na atualização, e o report por e‑mail segue layout padronizado.', N'Visões e plataforma padronizados otimizam tempo para análise e decisão. Automatizar a atualização melhora a rotina. O mesmo padrão e layout permite uma leitura mais agradável.', 0, NULL, N'Reutilização de recursos que seriam descartados para confecção de uma tampa, evitando a compra de uma tampa no valor de ', '2025-10-31T00:00:00.000', '2026-01-29T12:48:31.000', 81007480, NULL, 1);
INSERT INTO #PVC VALUES (7743, 81047115, 81018181, N'KIT BLINDAGEM', NULL, N'Others/Outros', N'ANTES O EQUIPAMENTO APRESENTAVA ALTO RISCO DE CONTAMINAÇÃO OCASIONANDO A TROCA DO LUBRIFICANTE ANTES DO RECOMENDADO.', N'REDUÇÃO DE CONTAMINAÇÃO', 10362, N'01 - Imagens/01 - Antes/7743.jpeg', N'ANTES O EQUIPAMENTO APRESENTAVA ALTO RISCO DE CONTAMINAÇÃO OCASIONANDO A TROCA DO LUBRIFICANTE ANTES DO RECOMENDADO.', N'01 - Imagens/02 - Depois/7743.jpeg', N'REALIZADOA APLICAÇÃO DE UM KIT BLINDAGEM NO  CARTE DA BA AFIM DE ELIMINAR  POSSIVEIS FOCOS DE CONTAMINAÇÃO E APLICADO NO EQUALIZADOR DE PRESSÃO E UM DOZADOR DE OLEO.', NULL, N'SIM', N'SETIMENTO DE DONO', 0, NULL, N'sim, pessoas alertadas sobre movimentação.', '2026-01-26T00:00:00.000', '2026-01-29T14:39:50.000', 81047115, NULL, 3);
INSERT INTO #PVC VALUES (7744, 81045979, 81045979, N'Instalação de extensor hidráulico', NULL, N'Concentration/Concentração', N'Durante a atividade de lubrificação do transportador,
INSERT INTO #PVC VALUES (7745, 81047115, 81040288, N'suporte para mangueiras', NULL, N'Others/Outros', N'AMBIENTE DEZORGANIZADO E MANGUEIRAS ESPALHADAS  ', N'organização do ambiente', 10362, N'01 - Imagens/01 - Antes/7745.jpeg', N'AMBIENTE DEZORGANIZADO E MANGUEIRAS ESPALHADAS  ', N'01 - Imagens/02 - Depois/7745.jpeg', N'FABRICADO SUPORTE PARA ORGANIZAÇÃO DAS MANGUEIRAS E MELHORIAS ASCPECTO VISUAL DO AMBIENTE', NULL, N'SIM', N'MELHORIA CONTINUA', 0, NULL, N'A aquisição de um suporte comercial demandaria um tempo elevado para verificação, compra e entrega, o que atrasaria na instalação do painel.', '2026-01-28T00:00:00.000', '2026-01-29T14:53:36.000', 81047115, NULL, 3);
INSERT INTO #PVC VALUES (7746, 499302, 538357, N'Kaizen - Iluminação Inteligente', NULL, N'Others/Outros', N'A baixa iluminação em áreas da indústria durante a execução de atividades de limpeza, inspeção e manutenção representa um risco significativo para a integridade física dos trabalhadores e para a continuidade operacional. Esse problema ocorre principalmente em locais confinados, galerias, áreas subterrâneas, plantas industriais com iluminação insuficiente ou durante intervenções noturnas e emergenciais, onde a iluminação fixa não é adequada.
INSERT INTO #PVC VALUES (7747, 81005006, 81005006, N'acesso do portão do CTM', NULL, N'No Replication/Sem replicação', N'acesso não apropriado para passagem da paleteira  elétrica devido desgastes e grades de ferros .
INSERT INTO #PVC VALUES (7748, 81055953, 81055953, N'Belt Filter ', NULL, N'Others/Outros', N'Belt filter cloth alignment system not working. operations called to replace it for start up after DFR.', N'Get belt filter back online safely', 0, N'01 - Imagens/01 - Antes/7748.jpeg', N'Operations called with a YEM request that Belt filter 3 could not come back online due to alignment system not working and needed to be replaced.', N'01 - Imagens/02 - Depois/7748.jpeg', N'Before ordering parts to replace system, myself and instrumentation technician went to inspect and troubleshoot system. we found that there was concentrate build up inside the  shifter that had hardened causing it to seize. after we removed the concentrate, the shifter worked perfectly.', NULL, N'yes ', N'Inspect before repair', 1500, 3, N'Atendimento aos padrões de ergonomia,Eliminação do improviso na montagem do bebedouro,Maior durabilidade e facilidade de limpeza.', '2026-01-18T00:00:00.000', '2026-01-29T15:30:19.000', 81055953, NULL, 1);
INSERT INTO #PVC VALUES (7749, 81037003, 516988, N'GUARDA CORPO ', NULL, N'Others/Outros', N'falta de guarda corpo ', N'eliminar risco eminente ', 10031, N'01 - Imagens/01 - Antes/7749.jpeg', N'falta de guarda corpo, estava sendo usada barreira fisica de tubo roll, risco eminente ', N'01 - Imagens/02 - Depois/7749.jpeg', N'Foi realizado a instalação de guarda corpo, de acordo com o padrão e normalizado a condição ', NULL, N'Sim, foi resolvido de acordo com o esperado ', N'valorizar segurança ', 0, NULL, N'Foi criado um processo estruturado (POP/IT), que:
