INSERT INTO #PVC VALUES (7926, 1008564, 1009524, N'Longer screws on table', NULL, N'Refining/Refino', N'Longer screws on table on the Maintenance Crane for laying the Anodes on when doing cell maintenance.', N'Better to hold down the top of the table.', 0, N'01 - Imagens/01 - Antes/7926.jpeg', N'Screws were too short', N'01 - Imagens/02 - Depois/7926.jpeg', N'Longer screws', NULL, N'Yes', N'Needed longer screws', 0, NULL, N'eliminado o risco ergonômico, facilitando o trabalho com empilhadeira. ', '2026-02-02T00:00:00.000', '2026-02-03T17:06:11.000', 1008564, NULL, 1);
INSERT INTO #PVC VALUES (7927, 1008564, 1010298, N'Bigger Zip Ties to hold Anodes', NULL, N'Refining/Refino', N'Zip Ties were too small to hold Anodes', N'Holding Anodes', 0, N'01 - Imagens/01 - Antes/7927.jpeg', N'Zip Ties were too small to hold Anodes', N'01 - Imagens/02 - Depois/7927.jpeg', N'Bigger Zip Ties to hold Anodes', NULL, N'Yes', N'Needed bigger Zip Ties', 0, NULL, N'Melhoria e agilidade para transportar a maquina', '2026-02-02T00:00:00.000', '2026-02-03T17:15:29.000', 1008564, NULL, 1);
INSERT INTO #PVC VALUES (7928, 81035706, 81035706, N'Implantação de suporte para capacetes na sala administrativa (Organização e 5S)', NULL, N'Others/Outros', N'Não havia um local padronizado para armazenar os capacetes na sala administrativa, gerando desorganização e dificultando o acesso rápido ao EPI.”', N'Implementar um suporte dedicado para capacetes, visando:  Padronizar o local de armazenamento Melhorar a organização (5S) do ambiente Reduzir tempo de procura/arrumação Preservar os capacetes e evitar danos/sujeira', 10139, N'01 - Imagens/01 - Antes/7928.jpeg', N'Capacetes sem local fixo definido.
INSERT INTO #PVC VALUES (7929, 81046149, 81040359, N'Acesso Principal ', NULL, N'Others/Outros', N'Acesso piso inferior da rebritagem  sem escada de acesso , com risco  de queda de nível diferente ao circulação  de pessoas na área operacional   nos caminhos seguro.
INSERT INTO #PVC VALUES (7930, 81035621, 81047868, N'Padronização e adequação de ferramenta ', NULL, N'Open Pit/Poço aberto', N'Durante a execução da atividade era utilizada uma slide Sledge, o que ocasionava mau posicionamento do colaborador, gerando risco ergonômico e de segurança. A ferramenta utilizada não era adequada para a atividade, podendo contribuir para acidentes e execução insegura do trabalho.', N'Reduzir esforço excessivo operacional, garantindo uso de ferramenta de bronze padronizada, adequada e segura.', 10324, N'01 - Imagens/01 - Antes/7930.jpeg', N'Antes da implementação do Kaizen, era utilizada uma slide Sledge para a execução da atividade. Devido às características da ferramenta, o colaborador acabava ficando mal posicionado ergonomicamente, adotando posturas inadequadas durante a execução do trabalho. Essa condição aumentava o risco de acidentes, fadiga física e exposição a situações inseguras.', N'01 - Imagens/02 - Depois/7930.jpeg', N'Foi desenvolvida e implementada uma ferramenta de bronze com comprimento de 1000 mm, proporcionando melhor alcance e permitindo que o colaborador execute a atividade em posição correta e segura. A solução trouxe melhoria ergonômica, redução do risco de acidentes, padronização do processo e maior segurança operacional.', NULL, N'Sim.
INSERT INTO #PVC VALUES (7931, 81035621, 81037517, N'Padronização e adequação de ferramenta ', NULL, N'Open Pit/Poço aberto', N'Durante a execução da atividade era utilizada uma 
INSERT INTO #PVC VALUES (7932, 81046149, 81046149, N'Guarda vida ', NULL, N'Others/Outros', N'Guarda corpo danificado, com risco eminente  na área operacional próximo caminho seguro.
INSERT INTO #PVC VALUES (7933, 81022762, 545518, N'Suporte para calços de equipamento de Pneus ', NULL, N'Others/Outros', N'falta de local para adequado para colocar os calços', N'Melhorar o nosso ambiente de trabalho ', 10144, N'01 - Imagens/01 - Antes/7933.jpeg', N'Calços ficavam espalhados pelo chão, sem devido a falta de espaço adequado para acomodar a quantidade que existe na área.', N'01 - Imagens/02 - Depois/7933.jpeg', N'Foi confeccionado um suporte onde todos os calços ficam guardados adequadamente e não ficam mais espalhados pelo chão.', NULL, N'Sim, agora os calços ficam no local correto.', N'organização', 0, NULL, NULL, '2026-01-24T00:00:00.000', '2026-02-04T09:26:16.000', 81022762, NULL, 1);
INSERT INTO #PVC VALUES (7934, 81022762, 543499, N'Matriz de bloqueio padronizada e atualizada dos equipamentos ', NULL, N'Others/Outros', N'falta de padronização', N'Padronizar e atualizar a matriz de bloqueio, garantindo maior segurança operacional, redução de falhas no processo e melhoria na eficiência das manutenções.', 10144, N'01 - Imagens/01 - Antes/7934.jpeg', N'Antes a matriz era inelegível, sendo bem antiga e não atendia todos os equipamentos 
INSERT INTO #PVC VALUES (7935, 81051666, 701391, N'Redução de Riscos Operacionais por Meio da Ampliação da Rampa de Acesso', NULL, N'Others/Outros', N'A rampa de acesso atual apresenta limitações operacionais que impactam diretamente a segurança. A largura insuficiente permite a passagem de apenas um veículo por vez, e, por se tratar de uma subida, a visibilidade de quem está subindo ou descendo é reduzida. Essa condição resulta em situações recorrentes em que dois veículos acessam a rampa simultaneamente sem conseguir visualizar um ao outro, obrigando que um deles dê ré para retornar ao ponto seguro, uma manobra de risco, especialmente em via inclinada. 
INSERT INTO #PVC VALUES (7936, 27185, 27185, N'VISUALIZAÇÃO DE TELEMETRIA  90 DIAS', NULL, N'Others/Outros', N'A pré-visualização da telemetria na plataforma Dynamox, estava  para 7 dias em cada ponto,  sendo necessário sempre alterar para 90 dias para ter visão melhor das tendência,  isso leva um tempo de atualização e com isso aumento do tempo de análise ao longo do dia.', N'OTIMIZAR O TEMPO DE ANÁLISE DE VIBRAÇÃO', 10178, N'01 - Imagens/01 - Antes/7936.jpeg', N'A pré-visualização da telemetria na plataforma Dynamox, estava  para 7 dias em cada ponto,  sendo necessário sempre alterar para 90 dias para ter visão melhor das tendência,  isso leva um tempo de atualização e com isso aumento do tempo de análise ao longo do dia.', N'01 - Imagens/02 - Depois/7936.jpeg', N'Solicitado junto a fornecedora, a padronização em massa para 90 dias de todos os pontos, visando otimizar a pré-visualização das tendências.', NULL, N'Tivemos ganho de tempo pois cada mudança no aumento de dias na telemetria é uma atualização que o computador faz, esse processo pode demorar mais de acordo com a latência da internet.', N'Customizar o sistema conforme a necessidade do ativol', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (7937, 81022762, 543499, N'Suporte de organização para uniforme limpos ', NULL, N'Others/Outros', N'Falta de padronização', N'Organizar e padronizar o armazenamento dos uniformes limpos, garantindo melhor controle, facilidade de acesso e melhoria na higiene e na rotina operacional.', 10144, N'01 - Imagens/01 - Antes/7937.jpeg', N'Ficava armazenado apenas no vestiário masculino, difícil acesso 
INSERT INTO #PVC VALUES (7938, 744615, 81050374, N'Menos esforça mais corte', NULL, N'Others/Outros', N'Antes para todos os tipos de serviço com oxicorte a equipe precisava movimentar o cunjunto com dois cilindros de 53Kg e 69Kg respectivamente, necessitando de caminhão Munk para o translado.', N'Reduzir o esforçar na realização de pequenos serviços', 10294, N'01 - Imagens/01 - Antes/7938.jpeg', N'Conjunto oxicorte disponivel era apenas o de oxigenio com 53Kg e Acetileno com 69Kg. O que dificultava o translado para atividade, pois precisava mobilizar o caminhão Muck, ou até mesmo o Guindaste dependendo do local da atividde, inclusive para pequenos serviços.', N'01 - Imagens/02 - Depois/7938.jpeg', N'Foi feito o carrinho para transporte do conjunto PPU de menor porte. O cilindro de oxigênio (1m³/7L) pesa aprox. 10,5kg a 12kg vazio. O cilindro de acetileno (1kg) pesa entre 11kg e 15kg. Facilitando o translado e a realização de pequenos serviços.', NULL, N'A Meta inicial era apenas reduzir o esforço, mas conseguimos também otimizar a a utilização de MO e equipamentos auxiliares', N'Sempre conseguimos melhorar a condição de trabalho', 0, NULL, NULL, '2026-01-15T00:00:00.000', '2026-02-04T11:18:39.000', 744615, NULL, 1);
INSERT INTO #PVC VALUES (7939, 81022762, 548039, N'Suporte de FPS 16 M', NULL, N'Others/Outros', N'Falta de suporte adequado', N'Segurança, agilidade, custo , organização.', 10144, N'01 - Imagens/01 - Antes/7939.jpeg', N'Local desorganizado, falta de padronização e gerando riscos.
INSERT INTO #PVC VALUES (7940, 81022762, 81017975, N'Suporte para transportar e armazenar a máquina de solda MiG ', NULL, N'Others/Outros', N'Falta de suporte para transportar a maquina de solda', N'Agilidade e segurança na locomoção da máquina de solda.', 10144, N'01 - Imagens/01 - Antes/7940.jpeg', N'Sem um local adequado para transporte com Riscos de queda e danificar a ferramenta. 
INSERT INTO #PVC VALUES (7941, 800303, 800303, N'Temporary Process Water Header Copper Electrowining', NULL, N'Refining/Refino', N'Process water lines in building 227 - Copper Electrowinning are failing at multiple locations.  Lines cannot be further clamped and water running to floor steadily.  Can''t run new line without demolishing the old line without engineering.  Setting up this bypass allows us to decommission the existing line and run a new one while skipping the costly engineering phase (replacement in kind) and using the existing isometrics', N'Reduce risk of total loss on failing process water line and reduce spillage/waste-water to Weak Liquor Neutralization', 0, N'01 - Imagens/01 - Antes/7941.jpeg', N'Water leaking down on steam line, multiple leak clamps on pipe', N'01 - Imagens/02 - Depois/7941.jpeg', N'Bypass header installed around the main leaking 4" pipe with take-offs and shut-off valves for all the pump seal-water runs. Now old pipe can be removed and replaced without impact to production or additional engineering.', NULL, N'Yes - problem solved temporarily, allowing maintenance to construct new line', N'Save Engineering costs by running bypasses', 10000, 3, N'Ganho no tempo de execução e produtividade', '2026-01-30T00:00:00.000', '2026-02-04T11:46:01.000', 800303, NULL, 1);
INSERT INTO #PVC VALUES (7942, 503120, 503120, N'Melhoria do tempo resposta de Emergência com Geolocalização em Tempo Real', NULL, N'Others/Outros', N'Foi identificado um problema na limitação da visualização em tempo real da localização dos colaboradores, o que dificultava a resposta rápida e precisa de atendimento, especialmente quando acionado o botão de emergência do rádio. Impactando diretamente o tempo de resposta, a tomada de decisão e a eficácia das ações de emergência. A necessidade do projeto foi evidenciada por análises de ocorrências, simulados e avaliações do desempenho das respostas a emergências, que demonstraram a necessidade de melhoria.  ', N'Reduzir o tempo de resposta às emergências por meio da implantação e uso eficaz de sistemas de geolocalização em tempo real, garantindo maior agilidade, precisão e segurança no atendimento a incidentes.', 10322, N'01 - Imagens/01 - Antes/7942.jpeg', N'A resposta a emergências em Salobo era realizada de forma limitada, baseada exclusivamente em comunicação verbal. Esse modelo dificultava a identificação imediata do local exato do evento, resultando em atrasos na delegação das equipes e na mobilização dos recursos adequados. Essa dependência de informações verbais e/ou escritas era o principal fator de dificuldade na coordenação das equipes em campo, impactando diretamente a agilidade e a eficácia da resposta às emergências.', N'01 - Imagens/02 - Depois/7942.jpeg', N'A solução implementada consiste no projeto de monitoramento dos dados georreferenciados dos rádios em tempo real durante os acionamentos. Com isso, a resposta às emergências deixa de depender exclusivamente de comunicação verbal ou escrita, passando a contar com informações precisas e imediatas sobre a localização do evento. O uso da geolocalização em tempo real cria um fluxo único e estruturado de resposta, garantindo que todas as ocorrências sigam o mesmo processo desde o acionamento de de emergência até o deslocamento das equipes.', NULL, N'Identificação do imediata e precisa do local do acionamento que anteriormente em alguns acionamentos eram confusos ou incertos. ', N'Otimização do processo com recursos tecnológicos ', 0, NULL, N'N/A', '2026-02-02T00:00:00.000', '2026-02-04T11:54:59.000', 503120, NULL, 1);
INSERT INTO #PVC VALUES (7943, 1008455, 1008455, N'H2S Tonner Grouping', NULL, N'Refining/Refino', N'All shifts didn''t know what H2S tonners were to be shipped during the next tonner offload', N'Create markable list for outgoing tonners', 0, N'01 - Imagens/01 - Antes/7943.jpeg', N'Prior to shipping the H2S tonners all four shifts didn''t know which 12 tonners out of the 24 that are in the room are to be loaded into the "empty" seacan. There was no checklist to say which ones go.', N'01 - Imagens/02 - Depois/7943.jpeg', N'Checklist created to show what tonners are full/empty and what ones are ready to go for the next offload', NULL, N'Yes', N'H2S tonners are more organized and easier to see when we have to contact the H2S driver', 0, NULL, N'better level control ', '2026-02-03T00:00:00.000', '2026-02-04T14:02:38.000', 1008455, NULL, 1);
INSERT INTO #PVC VALUES (7944, 81048606, 81048606, N'REPOSIÇÃO DO SENSOR FIM DE CURSO. ', NULL, N'Projects/Projetos', N'Quebra com alta frequência ', N'Melhoria continua ', 10139, N'01 - Imagens/01 - Antes/7944.jpeg', N'O equipamento deu entrada na oficina com falha no sensor de fim de cursa do batente da lança, foi identificado que o local que o sensor estava instalado era inapropriado o que ocasionava a quebra do mesmo. ', N'01 - Imagens/02 - Depois/7944.jpeg', N'Foi realizado o reposicionamento do sensor e do batente, eliminando o componente da linha de fogo e mitigando o risco de quebras e avarias. ', NULL, N'A alteração do local do sensor garantiu maior vida útil para o mesmo.  ', N'Melhoria continua ', 0, NULL, N'Padronização do processo de troca de filtros,Melhoria da confiabilidade operacional do posto pesado, Maior controle da qualidade do combustível e otimização do custo de manutenção', '2026-01-30T00:00:00.000', '2026-02-04T14:47:00.000', 81048606, NULL, 1);
INSERT INTO #PVC VALUES (7945, 124132, 124132, N'Cleaned Building #4 for safety, quality, productivity', NULL, N'Refining/Refino', N'Building #4 is extremely dusty and dirty, and can pose safety hazards as well as lower productivity and quality of work.', N'organize, improve safety, productivity, quality', 10238, N'01 - Imagens/01 - Antes/7945.jpeg', N'The entrance area in building #4 was very dirty and dusty. This poses safety hazards, can reduce productivity and quality of work. It really needed to be cleaned up. ', N'01 - Imagens/02 - Depois/7945.jpeg', N'The entrance area was cleaned and organized. Expectations of increase in quality of work and productivity and improvement in safety', NULL, N'yes, area is now organized and clean which can easily show hazards and variations in standards (lower quality or productivity)', N'Area needs regular cleaning', 0, NULL, N'Agilidade no uso das ferramentas. se encontra em um so lugar.', '2026-01-15T00:00:00.000', '2026-02-04T14:54:21.000', 124132, NULL, 1);
INSERT INTO #PVC VALUES (7946, 1010774, 1010774, N'Four THK Operation To Clean LRWT Feed Line', NULL, N'Others/Outros', N'LRWT Feed line restricted limiting flow of wash solution and causing a reduction in recovery.
INSERT INTO #PVC VALUES (7947, 81007807, 81007807, N'Lista de tarefa - Substituir báscula', NULL, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (7948, 607145, 607145, N'preserving PPE inventory', NULL, N'Refining/Refino', N'using B suits for training and drills is costly and restoring inventory is problematic due to lead times on delivery', N'save $ on training/drill suits', 10114, N'01 - Imagens/01 - Antes/7948.jpeg', N'we almost ran out of gas emergency response suits due to low inventory and long lead times on delivery.  additionally, the suits are a 1 and done application so not very cost effective to continue using in this manner', N'01 - Imagens/02 - Depois/7948.jpeg', N'implemented the use of tyvec protective wear for all non-gas emergency response exercises, ie., drills or training', NULL, N'problem solved and allows for better inventory management', N'this change will lessen the burden on supply chain and inventory management ', 5000, 3, NULL, '2026-02-03T00:00:00.000', '2026-02-04T15:55:37.000', 607145, NULL, 1);
INSERT INTO #PVC VALUES (7949, 81007807, 81007807, N'Lista tarefa - Substituir suspensão', NULL, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (7950, 539450, 539450, N'Lista de tarefas - substituir  cubo de hélice 785', NULL, N'Others/Outros', N'Demora na criação dos passos de elaboração para a
INSERT INTO #PVC VALUES (7951, 81031846, 81031846, N'Light Vehicle Rentals-Loss of Use Charges', NULL, N'Others/Outros', N'Vendor invoicing for $99.99 per day for Loss of Use (period of time vehicle was under repair and unable to be used by vendor for future rental elsewhere). This was equating to ~$1500 per vehicle upon return. Detected upon review of damage claims invoices and Terms and Conditions of agreement.', N'Eliminate Loss of Use Charge', 10311, N'01 - Imagens/01 - Antes/7951.jpeg', N'Vendor invoicing for $99.99 per day for Loss of Use (period of time vehicle was under repair and unable to be used by vendor for future rental elsewhere). This was equating to ~$1500 per vehicle upon return. ', N'01 - Imagens/02 - Depois/7951.jpeg', N'Reviewed T&Cs. Provided vendor language from T&Cs that identified Loss of Use charges were not valid. Vendor replied it was previously charged to Vale & was never an issue. Eventually vendor agreed to waive Loss of Use charges on damage claims/invoices equating to ~$1400 per vehicle upon return. Immediate savings of $8,119.18 & anticipating an additional ~$20,000 in savings when remaining rentals are returned.', NULL, N'Yes. Goal was to eliminate Loss of Use charges. Vendor agreed to waive charges.', N'Challenge status quo if you think something is incorrect.', 28000, 3, N'Isolamento eficaz para eliminação da interação', '2026-01-22T00:00:00.000', '2026-02-04T20:07:35.000', 81031846, NULL, 1);
INSERT INTO #PVC VALUES (7952, 81046149, 81046149, N'Ver com pés ', NULL, N'Open Pit/Poço aberto', N'Risco de queda de mesmo nível, ao transita próximo
INSERT INTO #PVC VALUES (7953, 81006571, 81016951, N'PLATAFORMA DE MANUTENÇÃO NA 2251BP01', NULL, N'Others/Outros', N'ANTES ERA NECESSARIO MONTAGEM DE ANDAIME PARA ATIVIDADE NA BOMBA, ALEM DE TER VARIOS PONTOS AO SEU REDOR DE PISO DESNIVELADO', N'ELIMINAÇÃO DE ANDAIMES E REDUÇÃO DE EXPOSIÇÃO DE PESSOAS', 10044, N'01 - Imagens/01 - Antes/7953.jpeg', N'Antes, era necessário montar andaime para a atividade na bomba, além de haver vários pontos de piso desnivelado ao redor, o que acumulava material e demandava tempo para limpeza e montagem do andaime. Isso expunha as pessoas a riscos durante a limpeza, montagem de andaime e manutenção.', N'01 - Imagens/02 - Depois/7953.jpeg', N'Com a implantação da plataforma, priorizamos a segurança da equipe: eliminamos o risco de queda, reduzimos o tempo de exposição a áreas de risco e minimizamos a necessidade de trabalhos em altura, tornando o ambiente mais seguro para todos. ', NULL, N'Problema resolvido porque não precisamos montar andaime e não precisamos de limpeza ao redor da bomba', N'Eliminar riscos são possiveis', 0, NULL, N'PROTEÇÃO COMPLETA DO LOCAL DE ABASTECIMENTO.', '2026-01-15T00:00:00.000', '2026-02-04T22:45:53.000', 81006571, NULL, 3);
INSERT INTO #PVC VALUES (7954, 81006571, 81016951, N'PLATAFORMA DE MANUTENÇÃO NA 2251BP01', NULL, N'Others/Outros', N'RISCOS DE ANDAIMES E RISCO DE EXPOSIÇÃO DE PESSOAS', N'ELIMINAÇÃO DE ANDAIMES E REDUÇÃO DE EXPOSIÇÃO DE PESSOASELIMINAÇÃO DE ANDAIMES E REDUÇÃO DE EXPOSIÇÃO DE PESSOAS', 10044, N'01 - Imagens/01 - Antes/7954.jpeg', N'Antes, era necessário montar andaime para a atividade na bomba, além de haver vários pontos de piso desnivelado ao redor, o que acumulava material e demandava tempo para limpeza e montagem do andaime. Isso expunha as pessoas a riscos durante a limpeza, montagem de andaime e manutençaõ', N'01 - Imagens/02 - Depois/7954.jpeg', N'Com a implantação da plataforma, priorizamos a segurança da equipe: eliminamos o risco de queda, reduzimos o tempo de exposição a áreas de risco e minimizamos a necessidade de trabalhos em altura, tornando o ambiente mais seguro para todos. 
INSERT INTO #PVC VALUES (7955, 1001007, 1001007, N'Chain across access hatch for raw water well', NULL, N'Refining/Refino', N'There was chain marking the boundary of the access hatch, but it wasn''t colored', N'To clearly mark the boundary for the access hatch for the well', 0, N'01 - Imagens/01 - Antes/7955.jpeg', N'The well for the raw water pumps in 272 (Pumphouse) had a clear boundary marked off,  but the chain was the wrong color.', N'01 - Imagens/02 - Depois/7955.jpeg', N'We took the chain, and painted it over instead of throwing it away because it is a high quality chain.  When it dried, we brough it back and put it in place, resolving the issue.', NULL, N'Yes, correct boundary chain in use.', N'Use proper color chain to isolate boundaries', 50, 3, N'Melhor performance dos ativos ', '2026-02-04T00:00:00.000', '2026-02-05T06:41:55.000', 1001007, NULL, 1);
INSERT INTO #PVC VALUES (7956, 81013118, 81013118, N'notification change on revert pit hi ', NULL, N'Refining/Refino', N'HI limit for this tank was originally an INFO alarm, which provided no audible notification  ', N'better alert for tank going high', 0, N'01 - Imagens/01 - Antes/7956.jpeg', N'Revert pit HI alarm was an INFO alarm which provided no audible notification. was a hazard as the tank could overflow without any notification.   ', N'01 - Imagens/02 - Depois/7956.jpeg', N'Got DCS team to change the HI to a WARNING at 85 so the CRT would be notified.  ', NULL, N'yes ', N'n/a ', 0, NULL, N'agilidade e organização dos galpão ', '2026-02-04T00:00:00.000', '2026-02-05T08:46:20.000', 81013118, NULL, 1);
INSERT INTO #PVC VALUES (7957, 211441, 211441, N'Padronização do Critério de Troca de Filtros no Posto Pesado', NULL, N'No Replication/Sem replicação', N'Inexistência de critério técnico padronizado para a troca dos filtros do posto pesado, resultando em substituições realizadas sem base em condição operacional real (diferencial de pressão – ΔP), ocorrendo ora de forma tardia (filtros saturados), ora de forma prematura (trocas desnecessárias).', N'Padronizar o critério de troca dos filtros do posto pesado, adotando diferencial de pressão (ΔP) como parâmetro técnico para a tomada de decisão operacional.', 10015, N'01 - Imagens/01 - Antes/7957.jpeg', N'Antes da solução, a troca dos filtros do posto pesado ocorria sem critério técnico definido, baseada em tempo ou percepção operacional, sem relação com a real condição dos filtros.', N'01 - Imagens/02 - Depois/7957.jpeg', N'Após a aplicação da solução, a troca dos filtros do posto pesado passou a seguir critério técnico padronizado por diferencial de pressão (ΔP), garantindo maior confiabilidade operacional e controle da qualidade do combustível.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'O problema da falta de critério para troca de filtros do posto pesado foi solucionado a partir da definição, formalização e implantação de um critério técnico objetivo, baseado no diferencial de pressão (ΔP) dos elementos filtrantes.', N'A ausência de critérios técnicos objetivos leva a decisões operacionais baseadas em percepção, aumentando riscos de falha, desvios de qualidade e custos desnecessários; a padronização com base em parâmetros mensuráveis (como ΔP) é essencial para garantir confiabilidade e qualidade do processo.', 0, NULL, NULL, '2026-02-04T00:00:00.000', '2026-02-05T09:02:09.000', 211441, NULL, 1);
INSERT INTO #PVC VALUES (7958, 486351, 486351, N'Painel de Ferramenta', NULL, N'Others/Outros', N'Muitos suportes de componentes na area. tomando espaço na oficina.', N'Melhoria de Condiçao de area', 10140, N'01 - Imagens/01 - Antes/7958.jpeg', N'Varios ferramentas em dispositivos diferentes.', N'01 - Imagens/02 - Depois/7958.jpeg', N'Foi contruido um painel para adequar todas as ferramentas de uso diario na manutençao em apenas um local. ', NULL, N'SIM', N'NA ADEQUAÇAO DE FERRAMENTA TEMOS COMO AGILIDADE NO PROCESSO E SEGURANÇA NA AREA.', 0, NULL, N'diminuição da temperatura ', '2026-02-04T00:00:00.000', '2026-02-05T09:36:05.000', 486351, NULL, 1);
INSERT INTO #PVC VALUES (7959, 81030963, 81051342, N'Padronização e Otimização do Acondicionamento de Papelão', NULL, N'Others/Outros', N'Antes da melhoria, o processo era desorganizado, com Big Bags espalhados e muito contato do material com o solo. Isso gerava retrabalho, dificultava o 5S, aumentava o manuseio e prejudicava a maturidade da rota Kamishibai.', N'Até 30/09/2026, reduzir o lead time do acondicionamento de papelão do recebimento até a prensagem em 30%, eliminando o contato do material com o solo (0 ocorrências), com simplificação de etapas (de X para X–n, ≥ –40%) e redução de manuseios (toques) por unidade em –50%, elevando a conformidade 5S para ≥ 90% e a maturidade da Rota Kamishibai para nível ≥ 4.', 10079, N'01 - Imagens/01 - Antes/7959.jpeg', N'Antes da melhoria, o processo era desorganizado, com Big Bags espalhados e muito contato do material com o solo. Isso gerava retrabalho, dificultava o 5S, aumentava o manuseio e prejudicava a maturidade da rota Kamishibai. ', N'01 - Imagens/02 - Depois/7959.jpeg', N'Após a transformação, o fluxo ficou mais limpo e organizado, com menos contato com o solo, menos manuseio e um caminho direto até a prensa, aumentando a eficiência.', NULL, N'meta inicial buscava organizar o processo, reduzir manuseio e eliminar o contato do papelão com o solo. Antes da melhoria, o cenário era de desorganização, Big Bags espalhados e alto retrabalho, o que afetava diretamente o 5S e a maturidade do Kamishibai. Após a transformação, a meta foi alcançada: o fluxo ficou mais limpo e organizado, com redução expressiva do contato com o solo, diminuição das etapas e do manuseio, além de um fluxo direto até a prensa, gerando mais eficiência operacional.', N'Padrão é essencial para manter o resultado', 0, NULL, N'Maior confiabilidade do ativo;
INSERT INTO #PVC VALUES (7960, 550925, 550925, N'Identificação do peso dos recipientes para testes de desenvolvimento', NULL, N'Others/Outros', N'Ao realizar testes de desenvolvimento em bancada, onde muitas vezes se precisa pesar a amostra não tínhamos  identificação dos pesos dos recipientes tendo que ter retrabalho quando era esquecido de pesar o recipiente tendo que tirar a amostra do recipiente para poder tarar o mesmo.', N'Facilitar o manuseio de amostras na hora da pesagem', 10235, N'01 - Imagens/01 - Antes/7960.jpeg', N'Ao realizar testes de desenvolvimento em bancada, onde muitas vezes se precisa pesar a amostra, não tínhamos  os valores dos pesos dos recipientes tendo que muitas vezes ter retrabalho quando era esquecido de pesar o recipiente tirando a amostra para poder pesar o mesmo e ver o peso retornando a amostra novamente.', N'01 - Imagens/02 - Depois/7960.jpeg', N'Identificado os recipientes que são utilizados nos testes facilitando a pesagem do material evitando erros no processo e consequentemente mais confiabilidade na entrega dos resultados dos testes.', NULL, N'O problema foi resolvido com a identificação dos recipientes que são utilizados nos testes.', N' Identificação', 0, NULL, N'QUALIDADE DO EQUIPAMENTO NA OPERAÇÃO', '2026-02-04T00:00:00.000', '2026-02-05T11:14:12.000', 550925, NULL, 3);
INSERT INTO #PVC VALUES (7961, 472940, 472940, N'Implantação de plataforma ', NULL, N'No Replication/Sem replicação', N'Risco de queda de altura, devido à execução da atividade em locais improvisados ou sem apoio adequado. Postura inadequada e esforço excessivo, podendo causar lesões musculares, lombalgias e fadiga precoce. Acesso inseguro ao equipamento, com necessidade de subir em estruturas não projetadas.
INSERT INTO #PVC VALUES (7962, 81006571, 81046951, N'PLATAFORMA TUB RECALQUE TRECHO 17 2251BP02', NULL, N'Others/Outros', N'Atividade com trabalho em altura, porque colocavamos pessoas em trbalho em altura', N'ELIMINAÇÃO DE ANDAIMES', 10044, N'01 - Imagens/01 - Antes/7962.jpeg', N'Antes era necessario a montagem de ponto de andaime para trocar trecho de recalque da 2251BP02, além de expor as pessoas durante a montagem de andaime e atividade de manutenção, também tinhamos perca de tempo com equipamento parado e perca de produtividade', N'01 - Imagens/02 - Depois/7962.jpeg', N'Foi realizado a eliminação de mais um ponto de andaime na tubulação de recalque da 2251BP02, eliminando o risco de acidentes em trabalhos altura com uso de plataforma fixa, garantindo maior segurança de quem irá executar as atividades de manutenção e de quem montava os pontos de andaime, além de dar mais produtividade nas atividades', NULL, N'Nossa meta de eliminar andaimes foi alcançada', N'ELIMINAR ANDAIMES É PRECISO E NECESSARIO', 0, NULL, N'REDUÇÃO DE PARADAS DO EQUIPAMENTO', '2026-01-21T00:00:00.000', '2026-02-05T13:26:55.000', 81006571, NULL, 3);
INSERT INTO #PVC VALUES (7963, 81034398, 81016922, N'Proteção dos acumuladores ', NULL, N'Others/Outros', N'Os acumuladores estavam sem proteção ', N'Garantir a proteção dos acumuladores ', 10139, N'01 - Imagens/01 - Antes/7963.jpeg', N'Os acumuladores estavam sem proteção, o que poderia ocasionar danos aos mesmos, podendo danificar sendo necessário realizar a substituição dos mesmos ', N'01 - Imagens/02 - Depois/7963.jpeg', N'Foi fabricado uma proteção e instalado no equipamento, assim garantindo a funcionalidade dos mesmos.', NULL, N'Sim, com a fabricação da proteção, os acumuladores ficaram livre de danos ', N'Garantir a funcionalidade de todos os componentes dos equipamentos ', 0, NULL, N'less waste from contamination', '2026-01-23T00:00:00.000', '2026-02-05T13:31:38.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (7964, 81006571, 81012464, N'BARREIRA FISICA EM FRENTE AO SAG', NULL, N'Others/Outros', N'Antes, não tinhamos sistema de isolamento homem maquina durantes troca de revestimento do moinho SAG', N'ELIMINAR ISOLAMENTOS INADEQUADOS', 10044, N'01 - Imagens/01 - Antes/7964.jpeg', N'Antes, a falta de isolamentos eficazes durante a troca de revestimentos no SAG comprometia gravemente a segurança, permitindo a interação insegura entre homem e máquina. Isso aumentava drasticamente o risco de incidentes críticos relacionados ao RAC 03, colocando em perigo a integridade física da equipe.', N'01 - Imagens/02 - Depois/7964.jpeg', N'Agora, com a fabricação propia e implementação de barreiras físicas, garantimos a segregação segura entre homem e máquina durante a troca de revestimentos no SAG. Isso reduz drasticamente o risco de incidentes RAC 03, protegendo a vida e a segurança da equipe. ', NULL, N'A meta inicial de eliminar interação HOMEM/MAQUINA foi alcançada', N'Trabalho em equipe sempre terá melhores resultados', 0, NULL, N'ORGANIZAÇÃO DA AREA', '2026-01-27T00:00:00.000', '2026-02-05T13:42:42.000', 81006571, NULL, 3);
INSERT INTO #PVC VALUES (7965, 81046197, 81046197, N'Base de içamento de carga', NULL, N'Projects/Projetos', N'Unidade não veio com pontos de pega para inça , mediante isso projetamos uma base e pontos garantindo mais segurança para o processo', N'Mais segurança durante atividade de içamento ', 10362, N'01 - Imagens/01 - Antes/7965.jpeg', N'Unidade móvel veio sem pontos de içamento .', N'01 - Imagens/02 - Depois/7965.jpeg', N'Agora com mais confiabilidade os pontos de içamentos estão tornando as atividades mais seguras', NULL, N'SIM', N'Visar melhorias tornando equipamentos mais seguros', 0, NULL, N'Cost savings and health and safety', '2026-02-02T00:00:00.000', '2026-02-05T13:50:21.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (7966, 81034398, 81016922, N'CORRENTE DE PROTECÃO ', NULL, N'Others/Outros', N'AS TAMPAS DOS LOCAIS DE ABASTECIMENTO DE NIVIES NAS MOTONIVELADORAS SÃO APENAS ENCAIXADOS', N'GARANTIR QUE AS TAMAPS DE ABASTECIMETO NÃO CAIAM', 10139, N'01 - Imagens/01 - Antes/7966.jpeg', N'AS TAMPAS DOS LOCAIS DE ABASTECIMENTO DE NIVIES NAS MOTONIVELADORAS SÃO APENAS ENCAIXADOS, CASO NÃO SEJA FIXADA CORRETAMENTE PODE CAIR, O QUE PODE LEVAR CONTAMINAÇÃO AO SISTEMA DA MÁQUINA', N'01 - Imagens/02 - Depois/7966.jpeg', N'FOI INSTALADO UMA CORRENTE DE FIXAÇÃO DA TAMPA DE ABASTECIMENTO E FIXADA NO EQUIPAMENTO, ASSIM EVITANDO QUE A MESMA VENHA A CAIR', NULL, N'SIM, COM A INSTALAÇÃO DA CORRENTE A TAMPA ESTA BEM FIXADA , O QUE EVITA O RISCO DE QUEDA', N'MELHORIA DO PROCESSO ', 0, NULL, N'MELHORA NA UTILIZAÇÃO DA MAQUINA E MAIS SEGURANÇA AOS COLABORADORES.', '2026-01-29T00:00:00.000', '2026-02-05T14:03:19.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (7967, 81046197, 81046197, N'Recuperação interna componentes hidráulicos', NULL, N'Others/Outros', N'Bombas retiradas por baixa performance estavam separadas para reparo externo ocasionando demora no retorno  ', N'Sobressalentes hidráulicos disponíveis ', 10362, N'01 - Imagens/01 - Antes/7967.jpeg', N'Bombas aguardando reforma externa no laboratório de hidráulica ( 2551FL01 e 02 ) Bombas de alta pressão .', N'01 - Imagens/02 - Depois/7967.jpeg', N'Aberto as bombas realizado recuperação dos componentes internos e trocada as vedações , testada e a mesma operou validando a recuperação. ', NULL, N'SIM 
INSERT INTO #PVC VALUES (7968, 81046197, 81046197, N'Filtro de sucção ', NULL, N'Others/Outros', N'Unidade não tinha filtro de sucção e foi instalado o filtro para impedir entrada de contaminantes e desgaste da bomba', N'Aumentar Vida útil do equipamento ', 10362, N'01 - Imagens/01 - Antes/7968.jpeg', N'Linha de sucção passando direto pra bomba sem proteção de contaminantes .', N'01 - Imagens/02 - Depois/7968.jpeg', N'Instalado mangueira e filtros para eliminar desgaste dos componentes hidráulicos ', NULL, N'Sim', N'Aumentando a vida útil dos ativos ', 0, NULL, NULL, '2026-01-13T00:00:00.000', '2026-02-05T14:41:51.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (7969, 81018181, 81018181, N'Bomba para sucção de óleo ', NULL, N'Others/Outros', N'antes não existia bomba de sucção para drenagem do óleo contaminado, dessa forma era necessária programar um caminhão para fazer a coleta do óleo na área, ocasionando acumulo de material e desorganização na área. ', N'agilidade no processo de coleta de óleo ', 10362, N'01 - Imagens/01 - Antes/7969.jpeg', N'antes não existia bomba de sucção para drenagem do óleo contaminado, dessa forma era necessária programar um caminhão para fazer a coleta do óleo na área, ocasionando acumulo de material e desorganização na área. ', N'01 - Imagens/02 - Depois/7969.jpeg', N'Foi instalado uma bomba fixa no local e dedicada para coleta de óleo contaminado, agilizando as rotinas de lubrificação e otimizando tempo e facilitando a organização do galpão ', NULL, N'sim', N'melhoria continua ', 0, NULL, NULL, '2026-02-03T00:00:00.000', '2026-02-05T14:43:15.000', 81018181, NULL, 1);
INSERT INTO #PVC VALUES (7970, 200795, 608539, N'In house Built Type C MCC', NULL, N'Underground/Subterrâneo', N'We had been purchasing MCC''s from a supplier for years.  The lead time and cost were outrageous.  After doing some research and working with Vale Engineering it was determined that we could build our own MCC''s in house.  Results show we can build them in less time and for approximately $45,000 less per unit.  We require roughly 6 units per year, our annual savings are $270,000.', N'Cost reduction', 10238, N'01 - Imagens/01 - Antes/7970.jpeg', N'We had been purchasing MCC''s from a supplier for years.  The lead time and cost were becoming outrageous.  ', N'01 - Imagens/02 - Depois/7970.jpeg', N'After doing some research and working with Vale Engineering it was determined that we could build our own MCC''s in house.  Results show we can build them in less time and for approximately $45,000 less per unit.  We require roughly 6 units per year, our annual savings are $270,000.', NULL, N'Yes.  We are saving money and reducing lead time.', N'Look for other potential insourcing opportunities.', 270000, 3, N'Melhor visibilidade no monitoramento do ativo, além da redução de atalhos.', '2025-12-31T00:00:00.000', '2026-02-05T14:59:18.000', 200795, NULL, 1);
INSERT INTO #PVC VALUES (7971, 81018181, 81046944, N'ponto de suspiro', NULL, N'Others/Outros', N'antes o equipamento não contava com ponto de suspiro, ocasionando o aquecimento do redutor', N'diminuir a temperatura do redutor ', 10362, N'01 - Imagens/01 - Antes/7971.jpeg', N'antes o equipamento não contava com ponto de suspiro, ocasionando o aquecimento do redutor', N'01 - Imagens/02 - Depois/7971.jpeg', N'Diminuição da temperatura do equipamento e longevidade da vida útil do equipamento .', NULL, N'Diminuição da temperatura do equipamento e longevidade da vida útil do equipamento .', N'melhoria continua ', 0, NULL, N'Resultado obtido.', '2026-02-02T00:00:00.000', '2026-02-05T15:05:27.000', 81018181, NULL, 1);
INSERT INTO #PVC VALUES (7972, 81018181, 81034532, N'KIT BLIDAGEM ', NULL, N'Others/Outros', N'Os equipamentos não possuíam sistema de troca de respiro, o que impedia a correta retirada de umidade e a entrada controlada de ar.
INSERT INTO #PVC VALUES (7973, 81013885, 81013885, N'SUPORTE SECADOR', NULL, N'No Replication/Sem replicação', N'ANTES EQUIPAMENTO NAO TINHA UMA BASE ADEQUADA, DEIXANDO O EQUIPAMENTO EM CONDIÇÕES DE DESGASTE.', N'CONFIABILIDADE DO EQUIPAMENTO', 10362, N'01 - Imagens/01 - Antes/7973.jpeg', N'ANTES EQUIPAMENTO NAO TINHA UMA BASE ADEQUADA, DEIXANDO O EQUIPAMENTO EM CONDIÇÕES DE DESGASTE.', N'01 - Imagens/02 - Depois/7973.jpeg', N'DEPOIS FOI FABRICADO UMA BASE METALICA E FEITO A INSTALAÇÃO DO EQUIPAMENTO NO LOCAL, TENDO O GANHO DE CONFIABILIDADE E PRODUÇAO DO MESMO.', NULL, N'SIM, COM A INTALAÇAO DA BASE O EQUIPAMENTO TEM O GANHO DE CONFIABILADE OPERACIOANAL.', N'QUALIDADE NO EQUIPAMENTO', 0, NULL, N'Problema identificado:
INSERT INTO #PVC VALUES (7974, 81046197, 81046197, N'RECUPERAÇÃO PNEUMÁTICA ', NULL, N'Others/Outros', N'BOMBAS PARA DESCARTE DEVIDO NÃO ESTÁ FUNCIONANDO', N'RECUPERAÇÃO DE SOBRESSALENTES ', 10362, N'01 - Imagens/01 - Antes/7974.jpeg', N'BOMBAS PARA DESCARTE POR NÃO FUNCIONAMENTO ', N'01 - Imagens/02 - Depois/7974.jpeg', N'BOMBA MONTADA E TESTADA A MESMA OPERANDO DE FORMA QUE ATENDE AS DEMANDAS NAS ÁREAS', NULL, N'SIM', N'REFORMA INTERNA', 0, NULL, N'Objetivos da ação:
INSERT INTO #PVC VALUES (7975, 496092, 496092, N'ALINHAMNETO DA CORREIA', NULL, N'No Replication/Sem replicação', N'DESALINHAMENTO CONSTATE DA CORREIA,  IMPACTANDO NA PARADA DO EQUIPAMENTO DEVIDO A CORREIA FACIAR NA ESTRUTURA METALICA.', N'MELHORAR ALINHAMENTO DA CORREIA, PARA NAO PEGAR NA ESTRUTURA', 10280, N'01 - Imagens/01 - Antes/7975.jpeg', N'DESALINHAMENTO CONSTATE DA CORREIA,  IMPACTANDO NA PARADA DO EQUIPAMENTO DEVIDO A CORREIA FACIAR NA ESTRUTURA METALICA, COM ISSO HAVIA NESCESSIDADE DA EQUIPE MANUTENÇÃO SER ACIONADA PARA REALIZAR O ALINHAMENTO DA CORREIA.
INSERT INTO #PVC VALUES (7976, 200463, 200463, N'PCR -Lab Oven sample management', NULL, N'Others/Outros', N'Use new oven for AgCl and LOI', N'Products in cleaner environment', 10019, N'01 - Imagens/01 - Antes/7976.jpeg', N'Possible contamination from process samples for high purity samples.', N'01 - Imagens/02 - Depois/7976.jpeg', N'cleaner oven with less contamination.', NULL, N'Yes', N'None', 0, NULL, N'Melhor forma de acondicionar folhas de papel com informações importante relacionado a saúde e segurança.', '2026-02-04T00:00:00.000', '2026-02-05T16:12:42.000', 200463, NULL, 1);
INSERT INTO #PVC VALUES (7977, 81040073, 547828, N'CAÇAMBA DE SUCATA', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE NÃO TINHA UMA CAÇAMBA ADEQUADA PARA DESCARTE DE SUCATAS DE FERRO NA AREA DE FABRICAÇÃO.', N'ORGANIZAÇÃO DA AREA', 10044, N'01 - Imagens/01 - Antes/7977.jpeg', N'ANTERIORMENTE NÃO TINHA UMA CAÇAMBA ADEQUADA PARA DESCARTE DE SUCATAS DE FERRO NA AREA DE FABRICAÇÃO. SENDO REALIZADO DESCARTE EM LOCAL INADEQUADO.', N'01 - Imagens/02 - Depois/7977.jpeg', N'FOI FABRICADO UMA CAÇAMBA PARA DESCARTE EM LOCAL ADEQUADO DE INSUMOS E SUCATAS.', NULL, N'SIM, POIS O DESCARTE ESTA SENDO REALIZADO NO LOCAL CORRETO, E FACILIDADE PARA DESCARTE DAS SUCATAS.', N'DESCARTE DE MATERIAL NO LOCAL ADEQUADO É MAIS SEGURO', 0, NULL, N'Melhoria de segurança, redução de tempo, redução de custo, aumento de produção e melhoria de processo.', '2026-01-29T00:00:00.000', '2026-02-05T16:13:41.000', 81040073, NULL, 3);
INSERT INTO #PVC VALUES (7978, 1010730, 1010730, N'Boot Brush Replacement', NULL, N'Refining/Refino', N'Boot brushes are required at entrances in 221, 222, and 226 CPL buildings to prevent contamination of walkways outside and in the annex. Currently, the conifiguration creates mess around the boot brush itself. Additionally, sourcing replacement parts and new boot brushes has become excessively expensive due to suppliers being located in the US.', N'Find an alternative boot brush that can be sourced locally and creates less of a mess at entry ways ', 0, N'01 - Imagens/01 - Antes/7978.jpeg', N'Original set up of boot brush from several years ago. Only cleans bottom of boots and has potential to spray user. Dirt gathers in bottom of grating and needs to be washed down after a handful of uses on heavily soiled boots. Bristles have to be replaced quite often.
INSERT INTO #PVC VALUES (7979, 81040073, 81046945, N'PROTEÇÃO ESMERIL', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE NÃO HAVIA PROTEÇÃO NO ESMERIL PODENDO OCASIONAR EM UM ACIEDENTE DEVIDO A FALTA DE PROTEÇÃO.', N'REDUZIR ESPOSIÇÃO HOMEM/ MAQUINAS', 10044, N'01 - Imagens/01 - Antes/7979.jpeg', N'ANTERIORMENTE NÃO HAVIA PROTEÇÃO NO ESMERIL PODENDO OCASIONAR EM UM ACIEDENTE DEVIDO A FALTA DE PROTEÇÃO.', N'01 - Imagens/02 - Depois/7979.jpeg', N'FOI FABRICADO PROTEÇÃO PARA AMBOS LADOS DO ESMERIL BI-PARTIDOS PARA QUE NO USO DE UM LADO O OUTRO LADO ESTEJA FECHADO. EVITANDO RISCO DE CONTATO COM A MAQUINA.', NULL, N'SIM. FOI REDUZIDO EM 80% DO RISCO DE ACIDENTE NA REALIZAÇÃO DO USO DA MAQUINA.', N'NÃO UTILIZAR EQUIPAMENTOS SEM PROTEÇÃO ', 0, NULL, N'Grande ganho de tempo na obtenção da informação correta e assertiva uma média de 2 horas pra 10 minutos.', '2026-01-27T00:00:00.000', '2026-02-05T16:33:58.000', 81040073, NULL, 3);
INSERT INTO #PVC VALUES (7980, 81057538, 81057538, N'IDENTIFICAÇÃO DE BATERIAS E CARREGADOR', NULL, N'Others/Outros', N'ESTAVA DESORGANIZADOS, DIFICULTANDO A IDENTICAÇÃO DE QUAL BATERIAS ESTAVA CARREGADAS', N'MANTER O CONTROLE DAS BATERIAS CARREGADAS E DESCARREGADAS', 10235, N'01 - Imagens/01 - Antes/7980.jpeg', N'ESTAVA DESORGANIZADOS, DIFICULTANDO A IDENTICAÇÃO DE QUAL BATERIAS ESTAVA CARREGADAS', N'01 - Imagens/02 - Depois/7980.jpeg', N'COM A MELHORIA NA IDENTIFICAÇAO, CONSEGUIMOS CONTROLAR QUAIS BATERIAS PRECISAVA RECARREGAR', NULL, N'SIM', N'ORGANIZAÇÃO', 0, NULL, N'O kit de emergência ambiental permite uma intervenção eficiente e segura até a chegada de suporte especializado.', '2026-02-04T00:00:00.000', '2026-02-05T18:52:55.000', 81057538, NULL, 3);
INSERT INTO #PVC VALUES (7981, 81004462, 81004462, N'Revisão da Estratégia Troca Tela de Retorno Tanque Hidráulico PC5500', NULL, N'No Replication/Sem replicação', N'Elevado custo de manutenção preventiva, com a troca do filtro tela, sendo que não temos registros de ocorrências de obstrução ou sujeira acumulada nas telas do tanque', N'Otimização de custo e DF', 10015, N'01 - Imagens/01 - Antes/7981.jpeg', N'Tempo elevado de manutenção para troca do filtro tela do tanque hidráulico da PC5500 e elevado custo de manutenção preventiva, com a troca do filtro tela, sendo que não temos registros de ocorrências de obstrução ou sujeira acumulada nas telas do tanque.
INSERT INTO #PVC VALUES (7982, 81004462, 81004462, N'Revisão Atividades Sistemáticas X Condicionais dos Planos Prev. 797F', NULL, N'No Replication/Sem replicação', N'Elevado custo e tempo de manutenção da frota de caminhão 797F', N'Otimização de Custo e melhoria de processo', 10015, N'01 - Imagens/01 - Antes/7982.jpeg', N'Tempos elevados de parada de manutenção preventiva mecânica, impactando na DF da frota ao longo do ano;
INSERT INTO #PVC VALUES (7983, 430793, 430793, N'Adição de corrente na tela principal do sistema de controle', NULL, N'No Replication/Sem replicação', N'Não haviam valores de corrente das SFR’s na tela principal e era necessário abertura de faceplates para visualização', N'Redução de tempo, ganho melhor visibilidade para monitoramento na tela principal', 10013, N'01 - Imagens/01 - Antes/7983.jpeg', N'Não haviam valores de corrente das SFR’s na tela principal e era necessário abertura de faceplates para visualização. 
INSERT INTO #PVC VALUES (7984, 524302, 524302, N'Suporte de teste da bomba sulzer', NULL, N'Crusher/Britadeira', N'Não era possível testar a bomba após a conclusão de reforma, se houvesse qualquer anormalidade só seria possível diagnosticar após a instalação da bomba.', N'Desenvolver algo que permitisse fixar a bomba para realizar o teste.', 10249, N'01 - Imagens/01 - Antes/7984.jpeg', N'Não era possível testar a bomba', N'01 - Imagens/02 - Depois/7984.jpeg', N'Feito dispositivo para posicionar a bomba no torno e realizar o teste com segurança e qualidade.', NULL, N'Problema foi resolvido, pois agora conseguimos testar as bombas sulzer. ', N'Que é possível testar a bomba.', 0, NULL, N'We are now using an electronic logbook which is more visual and able to find items/errors more swiftly ', '2026-01-15T00:00:00.000', '2026-02-06T04:26:35.000', 524302, NULL, 3);
