INSERT INTO #PVC VALUES (8070, 81022580, 81022580, N'TUBO DE SPRAY PARA LIMPEZA DA CALHA DE DESCARGA DA TR_2305SA_04', NULL, N'Others/Outros', N'CONSTANTES OBSTRUÇÕES NA CALHA DE DESCARGA DO CHUTE DA TR_2305SA_04, SENDO NECESSÁRIO A ATUAÇÃO DO OPERADOR PARA RERALIZAR A DESOBSTRUÇÃO DE FORMA MANUAL, COM MANGUEIRAS DE ÁGUA SE EXPONDO A RISCO DE PROJEÇÃO DE MATERIAL.', N'GARANTIR A LIMPEZA DA  CALHA DE DESCARGA PARA EVITAR OBSTRUÇÃO', 10244, N'01 - Imagens/01 - Antes/8070.jpeg', N'CONSTANTES OBSTRUÇÕES NA CALHA DE DESCARGA DO CHUTE DA TR_2305SA_04, SENDO NECESSÁRIO A ATUAÇÃO DO OPERADOR PARA RERALIZAR A DESOBSTRUÇÃO DE FORMA MANUAL, COM MANGUEIRAS DE ÁGUA SE EXPONDO A RISCO DE PROJEÇÃO DE MATERIAL.', N'01 - Imagens/02 - Depois/8070.jpeg', N'FOI REALIZADO A FABRICAÇÃO E INSTALAÇÃO DE UM TUBO DE SPRAY COM BICOS DE ALTA PRESSÃO, VÁLVULA DE CONTROLE MANUAL PARA RERALIZAR DE FORMA AUTOMÁTICA A LIMPEZA ', NULL, N'SIM, FOI REALIZADO TESTES, ONDE NÃO EXISTE MAIS A NECESSIDADE DO OPERADOR SE EXPOR AO RISCO DE LIMPEZA OPERACIONAL, ESSA LIMPEZA ACONTECE DE FORMA AUTOMÁTICA.', N'FOI REALIZADO TESTES, ONDE NÃO EXISTE MAIS A NECESSIDADE DO OPERADOR SE EXPOR AO RISCO DE LIMPEZA OPERACIONAL, ESSA LIMPEZA ACONTECE DE FORMA AUTOMÁTICA.', 0, NULL, N'Saúde e Segurança, Produtividade/Performance, Produção, Tempo.', '2026-02-06T00:00:00.000', '2026-02-11T04:50:55.000', 81022580, NULL, 3);
INSERT INTO #PVC VALUES (8071, 540541, 540541, N'KANBAN DE TELAS DA PENEIRA', NULL, N'Others/Outros', N'DEMORA NA ENTREGA DE MATERIAL PELO ARMAZEM PARA AS PREVENTIVAS DA PENEIRA', N'OTIMIZAR O PROCESSO DE MANUTENÇÃO', 10178, N'01 - Imagens/01 - Antes/8071.jpeg', N'Atraso na entrega de materiais pelo armazém para as manutenções preventivas da peneira, ocasionando situações em que os itens chegavam após o prazo previsto para execução.', N'01 - Imagens/02 - Depois/8071.jpeg', N'A adoção do Kanban assegura disponibilidade imediata dos materiais ao lado das peneiras, eliminando atrasos e garantindo a execução completa das preventivas.', NULL, N'Sim, o problema foi resolvido.
INSERT INTO #PVC VALUES (8072, 81044914, 81044914, N'Acompanhamento de gestão de custos de materiais ', NULL, N'Others/Outros', N'Materiais é o custo mais expressivos da GG de manutenção de usina (representando 36% do nosso custo total em 2025), no passado, os aprovisionadores (responsáveis por programarem grande parte desses materiais), não tinham conhecimento do orçamento anual ou mensal das gerências ou centros de custo no qual atuavam, e quando não há norte, não há gestão.', N'Trazer cnhecimento do orçamento para os aprovisionadores', 10178, N'01 - Imagens/01 - Antes/8072.jpeg', N'Os aprovisionadores não têm visão do orçamento, atendendo às necessidades sinalizadas pelas áreas com o senso de urgência da área, sem visualizar o orçado ou aderência, pois não têm acesso a informação de maneira detalhada.', N'01 - Imagens/02 - Depois/8072.jpeg', N'Com a criação da ferramenta de acompanhamento, os aprovisionadores podem acompanhar o que foi orçado para o CC do qual eles são responsáveis e verificar a aderência diariamente.', NULL, N'Com certeza, esse projeto irá trazer savings significativos à GG Man. Usina, uma vez que custos serão evitados através da priorização dos custos e gasto consciente nas áreas. Esse projeto pode ser replicado a outras áreas', N'Controle de custos e trazer as visualizações personalizadas ás áreas é a melhor forma de atendimento', 300000, 1, N'MELHOR E MAIS SEGURO AS MOVIMENTAÇÕES NAS ÁREAS', '2026-02-10T00:00:00.000', '2026-02-11T10:33:22.000', 81044914, NULL, 1);
INSERT INTO #PVC VALUES (8073, 518700, 518700, N'TESTE', NULL, N'Others/Outros', N'TESTE', N'TESTE', 10033, N'01 - Imagens/01 - Antes/8073.jpeg', N'TESTE', N'01 - Imagens/02 - Depois/8073.jpeg', N'TESTE', NULL, N'TESTE', N'TESTE', 0, NULL, NULL, '2026-02-10T00:00:00.000', '2026-02-11T11:31:15.000', 518700, NULL, 1);
INSERT INTO #PVC VALUES (8074, 1010227, 1010227, N'Slide Gate Valve Handwheel Stock Removal', NULL, N'No Replication/Sem replicação', N'This item was stocked in the warehouse for a system that is no longer in use.', N'Reduce inventory that is no longer required', 0, N'01 - Imagens/01 - Antes/8074.jpeg', N'A spare handwheel for a slide gate valve that is no longer in use in the plant was stored in the warehouse.', N'01 - Imagens/02 - Depois/8074.jpeg', N'Item is identified as not required and will be removed from inventory and no longer managed.', NULL, N'The removal of this item will reduce inventory value by $2300 and management costs will be reduced.', N'Spare parts inventory should be continuously monitored to ensure parts are still relevent.', 2300, 3, N'MENOS CONTAMINANTES NAS COLETAS E ANÁLISES DE ÓLEO APÓS INTERVENÇÃO', '2026-02-10T00:00:00.000', '2026-02-11T11:37:26.000', 1010227, NULL, 1);
INSERT INTO #PVC VALUES (8075, 81059060, 518638, N'PROTEÇÃO DA GRADE FRONTAL DA CABINE NA ESCAVADEIRA 350', NULL, N'Projects/Projetos', N'A grade permitia a passagem de pedras ou blocos de até 120 mm. Esse material poderia atingir o vidro de proteção, gerando risco elevado de danos significativos, incluindo a possibilidade de perfuração do vidro e consequente exposição do operador ao impacto.', N'Melhoria na proteção da grade frontal da cabine.', 10139, N'01 - Imagens/01 - Antes/8075.jpeg', N'A grade permitia a passagem de pedras ou blocos de até 120 mm. Esse material poderia atingir o vidro de proteção, gerando risco elevado de danos significativos, incluindo a possibilidade de perfuração do vidro e consequente exposição do operador ao impacto.', N'01 - Imagens/02 - Depois/8075.jpeg', N'Com a instalação de uma grade de piso posicionada à frente da grade principal, a granulometria passível de atravessar o conjunto foi reduzida para aproximadamente 50 mm. Uma pedra com essa dimensão não possui energia ou volume suficientes para transpassar o vidro laminado, eliminando o risco de impacto direto na cabine e aumentando significativamente a segurança do operador.', NULL, N'Com a instalação de uma grade de piso posicionada à frente da grade principal, a granulometria passível de atravessar o conjunto foi reduzida para aproximadamente 50 mm. Uma pedra com essa dimensão não possui energia ou volume suficientes para transpassar o vidro laminado, eliminando o risco de impacto direto na cabine e aumentando significativamente a segurança do operador.', N'Com a instalação de uma grade de piso posicionada à frente da grade principal, a granulometria passível de atravessar o conjunto foi reduzida para aproximadamente 50 mm. Uma pedra com essa dimensão não possui energia ou volume suficientes para transpassar o vidro laminado, eliminando o risco de impacto direto na cabine e aumentando significativamente a segurança do operador.', 4, 1, N'BOMBA NOVA INSTALADA , FEITA CONFORME MEDIDAS E PROJETO SOLICITADO', '2026-02-10T00:00:00.000', '2026-02-11T14:47:03.000', 81059060, NULL, 1);
INSERT INTO #PVC VALUES (8076, 81018293, 81018293, N'Oxygen Cylinder Storage Improvement', NULL, N'Others/Outros', N'Previously, only a few spare oxygen cylinders could be stored at the Assay Lab Leco room. There is only space for one spare at a time, and each time it is replaced, the Warehouse personnel make frequent trips for just one cylinder. More storage locations for cylinders would require less frequent deliveries, and more places for empty cylinders and spares. ', N'To increase oxygen cylinder storage capacity at Assay Lab', 10311, N'01 - Imagens/01 - Antes/8076.jpeg', N'Previously at the Assay Lab, only a few spare oxygen cylinders could be stored in the Leco room. There is only space for one spare at a time, and each time it is replaced, the Warehouse personnel make a delivery trip by truck for just one cylinder. More storage locations for cylinders would require less frequent deliveries, and more places for empty cylinders and spares. ', N'01 - Imagens/02 - Depois/8076.jpeg', N'Entered a work notification to install a three-cylinder bracket on a wall in the Auto Prep Room that is at least 5 feet from the nearest electrical disconnect. As the sample cart would continue to be stored in this area, also installed a floor stop to ensure the cart does not roll into a stored cylinder. Floor stop is painted yellow, so it is visually noticeable to avoid tripping hazard. Risks are reduced by limiting the number delivery visits and cylinder handling. Efficiency improved by requiring fewer work time for deliveries.', NULL, N'Yes, this new set up will help reduce risks and improve efficiency. ', N'The change will improve efficiency by lab staff and Warehouse staff ', 0, NULL, N'ELIMINADO CONDIÇÃO DE RISCOS OPERACIONAIS .', '2026-02-10T00:00:00.000', '2026-02-11T15:03:38.000', 81018293, NULL, 1);
INSERT INTO #PVC VALUES (8077, 1015684, 1015684, N'Repulp strainer basket screen removal', NULL, N'Refining/Refino', N'the new basket strainers on the repulp pump duplex strainers had a mesh screen on them that was restricting the amount of flow the pump could get. ', N'Increase pump flow', 0, N'01 - Imagens/01 - Antes/8077.jpeg', N'the new basket strainers on the repulp pump duplex strainers had a mesh screen on them that was restricting the amount of flow the pump could get. ', N'01 - Imagens/02 - Depois/8077.jpeg', N'Removed screen from inside of basket allowing proper amount of flow to pass through while still stopping large obstructions.', NULL, N'Yes, pump now operates at desired flow rate.', N'Ensure the materials are appropriate for the application', 0, NULL, N'sim', '2026-02-10T00:00:00.000', '2026-02-11T16:48:30.000', 1015684, NULL, 1);
INSERT INTO #PVC VALUES (8078, 81055953, 81055953, N'Frozen equipment ', NULL, N'Others/Outros', N'Flowmeter valves on groundwater system freezing during cold weather ', N'keep equipment functioning', 0, N'01 - Imagens/01 - Antes/8078.jpeg', N'Valves on groundwater supply freezing during cold weather at nighttime and milder temperatures during the day.', N'01 - Imagens/02 - Depois/8078.jpeg', N'had scaffolders erect a hoarding to keep snow and rain from valves. also had site services stage a frost fighter to maintain higher temps to keep valves from freezing. Also had jersey barriers and straps to keep hoarding from moving in high winds.', NULL, N'Yes
INSERT INTO #PVC VALUES (8079, 81037003, 479348, N'PROTEÇÃO DA BASE HIFRAULICA ', NULL, N'Others/Outros', N'A base do hidráulico estava sem proteção podendo ocasionar tropeções e batidas contra ', N'SEGURANÇA ', 10031, N'01 - Imagens/01 - Antes/8079.jpeg', N'a base encontrava-se sem proteção nas laterais, podendo ocasionar batida contra, lesões e tropeços.', N'01 - Imagens/02 - Depois/8079.jpeg', N'Foi realizado a fabricação de uma proteção para a base hidráulica, eliminando os riscos.', NULL, N'equipamentos que podem causar batida contra não deve ficar sem Rac 07', N'segurança em primeiro lugar ', 0, NULL, N'Redução de furos na correia devido passagem de material para o tambor de tensionamento', '2026-02-03T00:00:00.000', '2026-02-12T11:17:11.000', 81037003, NULL, 2);
INSERT INTO #PVC VALUES (8080, 81016155, 479348, N'TUBULAÇÃO DO RADIADOR ', NULL, N'Others/Outros', N'ÁGUA ESTAVA INDO COM MUITAS IMPUREZAS PARA O RADIADOR DO MOINHO ', N'LIMPEZA DA ÁGUA ', 10031, N'01 - Imagens/01 - Antes/8080.jpeg', N'NÃO HAVIA FILTRO NA LINHA DE ÁGUA DO RADIADOR DO MO-2014-02, VINDO A CAUSAR SUPER AQUECIMENTO NO MOINHO E PARADA DO MESMO ', N'01 - Imagens/02 - Depois/8080.jpeg', N'Foi montado uma nova tubulação juntamente com o filtro para que a água chegue limpa até o radiador, assim evitando aquecimento e parada do mesmo ', NULL, N'Sim', N'Qualidade', 0, NULL, N'- Eliminação de até 60 horas de baixa produtividade por campanha
INSERT INTO #PVC VALUES (8081, 1009261, 1009261, N'Mandrel Transfer area sign', NULL, N'Refining/Refino', N'Hole in Safety Fencing with no signage for intended purpose', N'Display area designation', 0, N'01 - Imagens/01 - Antes/8081.jpeg', N'Sharp edges on no signage for gap in safety fencing on north side of System 100', N'01 - Imagens/02 - Depois/8081.jpeg', N'Sharp edges removed and signage in place ', NULL, N'yes', N'signage to better understand area use', 0, NULL, N'Redução de custos em evitar necessidade de aquisição do braço do link no período de acompanhamento da melhoria.', '2026-02-04T00:00:00.000', '2026-02-12T12:19:19.000', 1009261, NULL, 1);
INSERT INTO #PVC VALUES (8082, 124132, 124132, N'End of shift line up with FMDS', NULL, N'Refining/Refino', N'We were missing some important communication between the Nickel Processing Supervisors and the shipping coordinator.', N'Better communication', 10255, N'01 - Imagens/01 - Antes/8082.jpeg', N'Before we had a verbal hand over communication with the 2 Nickel Processing Supervisors. We did not have a meeting with our shipping coordinator. ', N'01 - Imagens/02 - Depois/8082.jpeg', N'Now we are having an end of shift FMDS online teams meeting with both Nickel Processing Supervisors and our shipping coordinator. This is helping us greatly ensuring that we do not miss any important communications between us. We review the FMDS file as well as the daily line up. We talk about marketing request so that we understand what is needed to pack and what is needed to ship to our customers.', NULL, N'We were having issues missing out on important information between the supervisors and our shipping coordinator.', N'Better communication', 0, NULL, N'Eliminação do risco de queda, aumento da segurança operacional, melhoria da ergonomia e do conforto operacional.', '2026-02-09T00:00:00.000', '2026-02-12T12:51:36.000', 124132, NULL, 1);
INSERT INTO #PVC VALUES (8083, 81047909, 483171, N'Na manutenção do CA 317 foi identificado esforço físico excessivo ao manusear tubo de exaustão de 81 kg no 797, usando a escada do caminhão, gerando riscos ergonômicos, às mãos e queda de materiais.', NULL, N'Others/Outros', N'Na manutenção do CA 317 foi identificado esforço físico excessivo ao manusear tubo de exaustão de 81 kg no 797, usando a escada do caminhão, gerando riscos ergonômicos, às mãos e queda de materiais.', N'Eliminar o esforço físico excessivo e reduzir os riscos ergonômicos, mecânicos e de queda de materiais na remoção e instalação do tubo de exaustão do caminhão 797, garantindo a execução segura e padronizada da atividade de manutenção preventiva.', 10145, N'01 - Imagens/01 - Antes/8083.jpeg', N'Na manutenção preventiva do CA 317 foi identificado que a remoção e instalação do tubo de exaustão do 797 (81 kg) era feita usando a escada do caminhão, gerando esforço físico excessivo e risco à equipe.', N'01 - Imagens/02 - Depois/8083.jpeg', N'SESMT e Manutenção criaram cesto acoplado à empilhadeira para instalar o tubo de exaustão com precisão, eliminando esforço físico e riscos. A solução padronizou o processo, reduziu 80% do esforço e elevou 50% a produtividade.', NULL, N'A meta foi atendida: o esforço físico e os riscos foram eliminados. O problema foi resolvido com o uso do cesto acoplado à empilhadeira, tornando a atividade segura e padronizada. Outros resultados obtidos: ganhos em Produtividade/Performance, Produção e Tempo. ', N'Soluções construídas em parceria (SESMT + Manutenção) potencializam segurança, produtividade e padronização.', 0, NULL, NULL, '2026-01-29T00:00:00.000', '2026-02-12T13:08:41.000', 81047909, NULL, 3);
INSERT INTO #PVC VALUES (8084, 81046197, 81046197, N'BANCADA DE TESTE VIRTUAL', NULL, N'Projects/Projetos', N'PARA AVALIAR POSSSIVEIS FALHAS EM UM SISTEMA NÃO TINHAMOS O RECURSO DE MONTAR DIAGRAMAR HIDRAULICOS E REALIZAR TESTES PARA VERIFICAR POSSÍVEIS FALHAS . ', N'DIAGNÓSTICO TÉCNICO', 10362, N'01 - Imagens/01 - Antes/8084.jpeg', N'ANTES AS ANÁLISES ERA FEITAS PENAS PELOS DESENHOS TECNICOS , PARA AVALIAR POSSÍVEIS FALHAS HIDRÁULICAS . 
INSERT INTO #PVC VALUES (8085, 81046197, 81046197, N'SUPORTE DE NITROGÊNIO', NULL, N'Others/Outros', N'DIFICULDADE DURANTE CALIBRAÇÃO DE ACUMULADOR MOVIMENTAR OS CILINDROS DE NITROGÊNIO', N'SEGURANÇA', 10362, N'01 - Imagens/01 - Antes/8085.jpeg', N'DIFICULDADE NA MOVIMENTAÇÃO DOS CILINDROS DE NITROGÊNIO DURANTE CALIBRAÇÃO DOS ACUMULADORES .', N'01 - Imagens/02 - Depois/8085.jpeg', N'FABRICADO CARRINHO COM RODAS PARA FACILITAR MOVIMENTAÇÃO DO MESMO NAS ÁREAS', NULL, N'SIM', N'MELHORAR ATIVIDADES DE ROTINA', 0, NULL, N'Estabilidade total do agitador magnético, sem qualquer balanço ou instabilidade durante a operação.', '2026-02-09T00:00:00.000', '2026-02-12T13:24:03.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (8086, 81044397, 81044397, N'Projeto de Suporte Ergonômico para Notebook', NULL, N'No Replication/Sem replicação', N'Atualmente, muitos usuários utilizam o notebook diretamente sobre mesas sem ajuste de altura, o que causa má postura, desconforto e possíveis problemas ergonômicos. Além disso, os suportes disponíveis no mercado possuem custo elevado, dificultando o acesso para todos. Diante disso, surge a necessidade de desenvolver uma solução de baixo custo, resistente e ergonômica, utilizando cano PVC como alternativa viável e sustentável.', N'Desenvolver um suporte de notebook em cano PVC que seja ergonômico, resistente e de baixo custo, visando melhorar a postura do usuário e aumentar a durabilidade do equipamento.', 10106, N'01 - Imagens/01 - Antes/8086.jpeg', N'Atualmente, o uso prolongado de notebooks diretamente sobre mesas ou superfícies inadequadas tem causado desconforto físico, como dores no pescoço, ombros e costas, devido à falta de ergonomia.', N'01 - Imagens/02 - Depois/8086.jpeg', N'Para resolver o problema de ergonomia, conforto e custo elevado dos suportes comerciais, foi desenvolvido um suporte de notebook utilizando cano PVC, seguindo os princípios do Kaizen de melhoria contínua.', NULL, N'sim', N'Soluções simples podem gerar grandes melhorias', 10, 1, N'melhora visuasl', '2026-02-11T00:00:00.000', '2026-02-12T13:32:28.000', 81044397, NULL, 3);
INSERT INTO #PVC VALUES (8087, 81046197, 81046197, N'ORGANIZAÇÃO DA ÁREA', NULL, N'Others/Outros', N'CONTENÇÃO ONDE ARMAZENAVA TAMBORES DE ÓLEO , PORÉM APRESENTAVA MUITOS CONTAMINANTES . ', N'REMOVER PONTOS DE CONTAMINAÇÃO', 10362, N'01 - Imagens/01 - Antes/8087.jpeg', N'CAIXA DE SUPORTE PARA ARMAZENAR TAMBOR DE ÓLEO PARA ABASTECER UNIDADE HIDRÁULICA DO SISTEMA DE ÁLIVIO , PORÉM ENTRAVA MUITOS CONTAMINANTES DURANTE LIMPEZA DA ÁREA COM JATEAMENTO DE ÁGUA. ', N'01 - Imagens/02 - Depois/8087.jpeg', N'REMOVIDO , E AMBIENTE LIMPO COM MAIS SEGURANÇA ELIMINANDO CONDIÇÃO DE CONTAMINANTES NO SISTEMA HIDRÁULICO , REALIZADO ABASTECIMENTO APENAS COM TAMBOR LACRADO ENVIADO ATÉ A ÁREA.', NULL, N'SIM', N'ELIMINAR PONTOS DE CONTAMINAÇÃO', 0, NULL, N'confiabilidade operacional do equipamento', '2026-02-11T00:00:00.000', '2026-02-12T13:34:02.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (8088, 81046197, 81046197, N'BOMBA DE ELEVAÇÃO', NULL, N'Projects/Projetos', N'BOMBA DE ELEVAÇÃO DO ESPESSADOR APRESENTAVA GRANDES VAZAMENTOS , ONDE ALÉM DE CONTAMINAÇÃO  HAVIA PERCA DE PRESSÃO E DISPERDICIO DE ÓLEO', N'ELIMINAR FALHA SISTEMA HIDRÁULICO', 10362, N'01 - Imagens/01 - Antes/8088.jpeg', N'BOMBA COM VAZAMENTOS DURANTE OPERAÇÃO , A MESMA NÃO ERA MAIS FORNECIDA NO MERCADO , COM TROCA DE VEDAÇÃO PELA ALTA PRESSÃO A MESMA NÃO DURAVA E APRESENTAVA VAZAMENTO.', N'01 - Imagens/02 - Depois/8088.jpeg', N'ELABORADO PROJETO E DESENHO TECNICO DA BOMBA , SOLICITADO FABRICAÇÃO E INSTALADA , A  MESMA TESTADA E APRESENTOU ALTA PRESSÃO DE FORMA OPERACIONAL CONFORME SOLICITADO E DESCRITO EM PROJETO E LEVANTAMENTO EM CAMPO', NULL, N'SIM', N'LEVANTAMENTO DE PEÇAS E PROJETOS', 0, NULL, N'Maior agilidade e facilidade para filtrar no SAP os planos de troca de componentes das frotas de equipamentos de mina.', '2026-02-11T00:00:00.000', '2026-02-12T13:47:16.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (8089, 81046197, 81046197, N'JANELA DE VIZITA', NULL, N'Others/Outros', N'DEVIDO GRADE PARA INSPEÇÃO AO REALIZAR LIMPEZA DA ÁREA ERA PROJETADO MATERIAL PARA DENTRO DA UNIDADE HIDRÁULICA , ACUMULANDO MUITO MATERIAL.', N'REDUÇÃO DE CONTAMINAÇÃO', 10362, N'01 - Imagens/01 - Antes/8089.jpeg', N'DEVIDO INSTALAÇÃO DE GRADE PARA FACILITAR INSPEÇÃO , A MESMA PERMITIA ENTRADA DE CONTAMINAÇÃO COMO MATERIAS E ÁGUA , OCASIONANDO ACUMULO DE MATERIAL NA PARTE INTERNA DA UNIDADE DO SISTEMA DE ALIVIO ', N'01 - Imagens/02 - Depois/8089.jpeg', N'REMOVIDO TELA E INSTALADO ACRÍLICO , PERMANECENDO PONTO DE INSPEÇÃO PORÉM SEM PERMIÇÃO DE ENTRADA DE CONTAMINANTES .', NULL, N'SIM', N'ELIMINAR RISCOS OPERACIONAIS', 0, NULL, N'Meta superada', '2026-02-09T00:00:00.000', '2026-02-12T13:56:03.000', 81046197, NULL, 1);
INSERT INTO #PVC VALUES (8090, 81047050, 81047050, N'PORTA TRAPO E RESIDUOS CONTAMINDO', NULL, N'Others/Outros', N'Antes ao realizar um manutenção preventiva nas unidades dos compressores detectei  a necessidade de um  coletor de resíduos contaminados e um porta trapos, os mesmo foi  fabricado e instalado.', N'ORGANIZAÇÃO DE LIMPENZA', 10362, N'01 - Imagens/01 - Antes/8090.jpeg', N'Antes ao realizar um manutenção preventiva nas unidades dos compressores detectei  a necessidade de um  coletor de resíduos contaminados e um porta trapos, os mesmo foi  fabricado e instalado.', N'01 - Imagens/02 - Depois/8090.jpeg', N'Agora podemos realizar atividades de manutenção preventivas sem a necessidade de leva trapos para limpeza com a fabricação do suporte, e ao realizar apos a atividades coletor resíduos no seu devido lugar', NULL, N'sim', N'Lições como padronização do 5s é essencial', 0, NULL, N'Maior segurança: o extintor passou a estar em posição adequada, livre de riscos de colisão com equipamentos móveis e de acidentes envolvendo pessoas.
INSERT INTO #PVC VALUES (8091, 81018181, 81018181, N'kit blinagem ', NULL, N'Others/Outros', N'Antes da intervenção, o equipamento apresentava degradação prematura do lubrificante, ocorrendo antes do período recomendado pelo fabricante. Foram identificados vazamentos constantes nos retentores de entrada e saída do eixo, causados pela pressão interna elevada no reservatório.
INSERT INTO #PVC VALUES (8092, 81049566, 81049566, N'Sem furos', NULL, N'Crusher/Britadeira', N'Correia com furos recorrente por passagem de material entre os tambores de tensionamento', N'nao ter furos na correia ', 10362, N'01 - Imagens/01 - Antes/8092.jpeg', N'Correia com furo Realizado pela passagem de material entre os tambores.', N'01 - Imagens/02 - Depois/8092.jpeg', N'Instalado limpador em v entre os tambores 4 e 5 da 2101tc02 para evitar passagem de material para o tambor de tensionamento,', NULL, N'Redução no período de furos na correia de 80% .', N'Melhoria no desempenho', 0, NULL, N' Redução de potenciais custos com afastamentos, acidentes de trabalho e intervenções corretivas emergenciais.
INSERT INTO #PVC VALUES (8093, 336479, 336479, N'80 é Produtividade', NULL, N'Crusher/Britadeira', N'Os rebritadores operam em campanhas médias de 380 horas, sendo necessária a troca de revestimento ao final desse período.
INSERT INTO #PVC VALUES (8094, 81047211, 81047211, N'Mudança do aço estrutural do braço do link da PC5500-6D', NULL, N'No Replication/Sem replicação', N'O braço do link das escavadeiras PC5500-6D, possui grande histórico de surgimento de trincas e em boa parte dos casos, mesmo após o reparo, à reincidência de trincas e consequente fratura total, demandando a substituição do item. No total, já foram substituídos 17 peças na frota, com custo unitário de 340.456,69. Dentre as principais causas destacam-se; sobrecarga, impacto e fragilidade do material. ', N'Reduzir as ocorrências de trincas e substituição do braço do link das escavadeiras PC5500-6D.', 10015, N'01 - Imagens/01 - Antes/8094.jpeg', N'O braço do link das escavadeiras PC5500-6D, possui grande histórico de surgimento de trincas e em boa parte dos casos, mesmo após o reparo, à reincidência de trincas e consequente fratura total, demandando a substituição do item.', N'01 - Imagens/02 - Depois/8094.jpeg', N'Com base na análise das características do aço estrutural original (S690Q) foi desenvolvido um novo projeto para o braço do link, utilizando um aço estrutural com maior qualidade das propriedades mecânica (Strenx 700). Dentre as principais propriedades, destacam-se;
INSERT INTO #PVC VALUES (8095, 81047909, 81024241, N'Mitigação de riscos de queda em acessos a parte superior de Perfuratrizes modelo PIT VIPER 351.', NULL, N'Others/Outros', N'Inspeções nas perfuratrizes PIT VIPER 351 identificaram risco de queda na transposição entre níveis, pois ao subir a escada o trabalhador ultrapassa o guarda‑corpo, ficando fora da zona de proteção.', N'Eliminar o risco de queda na transposição entre níveis da PIT VIPER 351, garantindo método de acesso seguro que mantenha o trabalhador sempre dentro da zona de proteção do guarda‑corpo.', 10145, N'01 - Imagens/01 - Antes/8095.jpeg', N'A transposição entre níveis na PIT VIPER 351 é feita pela escada fixa; ao ascender, o trabalhador ultrapassa o guarda‑corpo e permanece fora da zona de proteção, caracterizando risco de queda.', N'01 - Imagens/02 - Depois/8095.jpeg', N'SESMT e supervisão de manutenção, com apoio da engenharia, instalaram extensão no guarda‑corpo das PIT VIPER 351, mitigando o risco de queda na transposição de nível e aumentando a segurança na área superior.', NULL, N'A meta de eliminar o risco de queda foi atendida: a extensão do guarda‑corpo mantém o trabalhador protegido durante a transposição entre níveis, resolvendo o problema identificado nas PIT VIPER 351.
INSERT INTO #PVC VALUES (8096, 472995, 472995, N'Escada de acesso ao piso do 2251AL01 AL de bolas.', NULL, N'Crusher/Britadeira', N'Problema Identificado a escada não era segura para acesso ao piso do 2251AL01. Os colaboradores enfrentam dificuldades frequentes durante atividades de manutenção que realizavam por meio de uma escada fixa rígida, no local existia a necessidade constante de trajeto da máquina Bobcat para realizar a limpeza de materiais no túnel, mas não havia espaço suficiente para máquina passar entre a escada e a parede, vindo a causar danos a escada deixando imprópria para uso.', N'Confeccionar e instalar uma escada flexível e extensiva ', 10362, N'01 - Imagens/01 - Antes/8096.jpeg', N'Problema Identificado a escada não era segura para acesso ao piso do 2251AL01. Os colaboradores enfrentam dificuldades frequentes durante atividades de manutenção que realizavam por meio de uma escada fixa rígida, no local existia a necessidade constante de trajeto da máquina Bobcat para realizar a limpeza de materiais no túnel, mas não havia espaço suficiente para máquina passar entre a escada e a parede, vindo a causar danos a escada deixando imprópria para uso.', N'01 - Imagens/02 - Depois/8096.jpeg', N'Foi fabricado e montado uma escada flexível e extensiva facilitando acesso prático ao piso do 2251AL01, redução de tempo de preparação, já que o andaime não precisa mais ser montado/desmontado. Maior agilidade nas intervenções de inspeção, limpeza e manutenção. Criado acesso com espaço ideal para máquina Bobcat  passar para realizar trabalho de limpeza no interior do túnel.', NULL, N'sim, Problema solucionado e resolvido.', N'Melhoria de acesso.', 10, 1, N'Alerta precoce quando o ruído excede os limites de tolerância, antes que o problema vire incidente ou adoecimento.
INSERT INTO #PVC VALUES (8097, 498359, 494628, N'PROTEÇÃO DO COMPRATIMENTO DE CARGA', NULL, N'Others/Outros', N'Desgaste prematuro, e escorregadio.', N'MELHORAR DURABILIDADE', 10044, N'01 - Imagens/01 - Antes/8097.jpeg', N'Desgaste prematuro, e escorregadio.', N'01 - Imagens/02 - Depois/8097.jpeg', N'Eliminou desgaste prematuro, escorregadio, risco de queda e prolongou a durabilidade do compartimento da carga.', NULL, N'meta atingida com sucesso', N'melhorar ambiente de trabalho', 0, NULL, N'Agilidade na informação para tomada de decisão de estrátegia', '2026-02-12T00:00:00.000', '2026-02-12T15:58:30.000', 498359, NULL, 3);
INSERT INTO #PVC VALUES (8098, 516619, 516619, N'Melhoria no Agitador Magnético', NULL, N'No Replication/Sem replicação', N'Os pés de apoio do agitador magnético estavam frouxos e sem os parafusos, deixando-os bambos e reduzindo a firmeza do equipamento', N'Garantir que o agitador magnético permaneça firme, evitando que os pés de apoio fiquem bambos e comprometem a estabilidade do equipamento.', 10366, N'01 - Imagens/01 - Antes/8098.jpeg', N'Os pés de apoio do agitador magnético estavam frouxos e sem os parafusos de fixação, deixando-os instáveis. Essa condição reduzia a firmeza do equipamento e comprometia sua estabilidade durante a operação.', N'01 - Imagens/02 - Depois/8098.jpeg', N'Foram instalados novos pés de apoio no agitador magnético, utilizando material reciclável (tampas de garrafa pet) como base, eliminando a instabilidade e garantindo maior firmeza ao equipamento durante a operação.', NULL, N'A instabilidade foi eliminado o equipamento voltou a operar com firmeza.', N'Um agitador bambo pode causar derramamentos, danos aos frascos e até acidentes operacionais.', 0, NULL, N'Saúde e Segurança, Produtividade/Performance, Produção, Tempo.', '2026-02-11T00:00:00.000', '2026-02-12T16:03:42.000', 516619, NULL, 1);
INSERT INTO #PVC VALUES (8099, 81018181, 81046944, N'kit blindagem', NULL, N'Open Pit/Poço aberto', N'Antes da intervenção, o equipamento apresentava degradação prematura do lubrificante, ocorrendo antes do período recomendado pelo fabricante. Foram identificados vazamentos constantes nos retentores de entrada e saída do eixo, causados pela pressão interna elevada no reservatório.O sistema não possuía visor de nível nem dosador de óleo, o que dificultava o monitoramento adequado do volume e do consumo do lubrificante. Com a ausência desses componentes, quando o nível do óleo baixava não era possível identificar a condição real do reservatório, aumentando o risco de:Falha catastrófica do equipamento por falta de lubrificante;Paradas não programadas para completar o nível;Sobreaquecimento dos componentes internos;Desgaste acelerado de mancais e outras partes móveis.Em resumo, a condição anterior colocava o equipamento em risco de quebra e impactava diretamente a confiabilidade operacional.
INSERT INTO #PVC VALUES (8100, 81018181, 81040288, N'kit blindagem', NULL, N'Others/Outros', N'Antes da intervenção, o equipamento apresentava degradação prematura do lubrificante, ocorrendo antes do período recomendado pelo fabricante. Foram identificados vazamentos constantes nos retentores de entrada e saída do eixo, causados pela pressão interna elevada no reservatório.O sistema não possuía visor de nível nem dosador de óleo, o que dificultava o monitoramento adequado do volume e do consumo do lubrificante. Com a ausência desses componentes, quando o nível do óleo baixava não era possível identificar a condição real do reservatório, aumentando o risco de:Falha catastrófica do equipamento por falta de lubrificante;Paradas não programadas para completar o nível;Sobreaquecimento dos componentes internos;Desgaste acelerado de mancais e outras partes móveis.Em resumo, a condição anterior colocava o equipamento em risco de quebra e impactava diretamente a confiabilidade operacional.
INSERT INTO #PVC VALUES (8101, 564666, 564666, N'Padronização do tipo de atividade SAP:  EQR - Troca de Componentes', NULL, N'Others/Outros', N'Padronização do Tipo de Atividade de manutenção, no sistema SAP, dos  planos de troca de componentes das frotas de equipamentos de mina. Alteração do tipo de atividade de manutenção de SVC - Serviço de Manutenção Preventiva para EQR - Troca de Componentes. A criação desse novo tipo de atividade, EQR, foi divulgada pela Engenharia de Processos Vale Ferrosos.', N'Padronização do tipo de atividade de todos os planos de troca de componentes.', 10081, N'01 - Imagens/01 - Antes/8101.jpeg', N'Os planos de troca de componentes eram classificados no campo tipo de atividade, sistema SAP, como SVC - Serviço de Manutenção Preventiva.', N'01 - Imagens/02 - Depois/8101.jpeg', N'Os 269 planos de troca de componentes ativos foram reclassificados no campo tipo de atividade, sistema SAP, como EQR - Troca de Componentes. Isso facilita a pesquisa dos planos de substituição de componentes no SAP, diferenciando esses planos dos demais.', NULL, N'Maior agilidade e facilidade para filtrar no SAP os planos de troca de componentes das frotas de equipamentos de mina.', N'Maior agilidade e facilidade para filtrar no SAP os planos de troca de componentes das frotas de equipamentos de mina.', 0, NULL, N'COM A INSTALAÇAO DO SUPORTE ENROLADOR DE MANGUEIRAS MUDOU O ASPECTO FISICO DA AREA PARA ORGANIZADO E SEGURO ', '2026-02-02T00:00:00.000', '2026-02-12T16:33:05.000', 564666, NULL, 3);
INSERT INTO #PVC VALUES (8102, 488127, 81009651, N'Torneira da Pia do PSI 300i ', NULL, N'Others/Outros', N'Essa condição compromete a segurança, a padronização do processo e a confiabilidade das amostragens.', N'Melhorar as condições de amostragem no ponto do PSI 300i.', 10054, N'01 - Imagens/01 - Antes/8102.jpeg', N'Antes da instalação da torneira, ocorria perda de amostra durante o peneiramento do material coletado no PSI, O que impactava nos resultados das análises. ', N'01 - Imagens/02 - Depois/8102.jpeg', N'Depois da instalação da torneira, não houve mais perda de amostra durante o peneiramento do material coletado no PSI, garantindo maior confiabilidade nos resultados das análises.
INSERT INTO #PVC VALUES (8103, 127670, 127670, N'Relocação de Extintor', NULL, N'Others/Outros', N'O extintor de incêndio encontra-se instalado em local inadequado, na parede divisória entre as baias de FeNi. A posição atual expõe o equipamento ao risco de colisão, podendo ocasionar acidentes e comprometer sua funcionalidade em situações de emergência.', N'Relocação de extintor', 10171, N'01 - Imagens/01 - Antes/8103.jpeg', N'O extintor de incêndio encontra-se instalado em local inadequado, na parede divisória entre as baias de FeNi. A posição atual expõe o equipamento ao risco de colisão, podendo ocasionar acidentes e comprometer sua funcionalidade em situações de emergência.', N'01 - Imagens/02 - Depois/8103.jpeg', N'Foi solicitado à equipe de emergência a autorização para a relocação do extintor, tendo sido obtido o devido “De Acordo”. Após a liberação, o equipamento foi transferido para a parede lateral da baia, permanecendo em posição segura, fora do raio de operação dos equipamentos móveis e da circulação de pessoas.', NULL, N'Maior segurança: o extintor passou a estar em posição adequada, livre de riscos de colisão com equipamentos móveis e de acidentes envolvendo pessoas.
INSERT INTO #PVC VALUES (8104, 300837, 300837, N'TopVu Oretracking Tags', NULL, N'Underground/Subterrâneo', N'Rock is being added to Creighton''s hoist diluting our overall metal grade for the mine. This was observed by geology because we are not able to reconcile the volume of ore to the source. ', N'Identify when rock is being added into the Creighton Muck Circuit to capture possible dilution to the ore hoist.', 10203, N'01 - Imagens/01 - Antes/8104.jpeg', N'No visibility when rock enters the muck circuit. ', N'01 - Imagens/02 - Depois/8104.jpeg', N'Geology places RFID tags into piles of rock underground labelling the workplace. These tags are detected if they pass through readers in the muck circuit or on surface. Once detection occurs, emails are sent to the appropriate people to react and have conversations when rock is detected in the system. The RFID tags are also used to delineate when the mine hoisting switches from rock to ore. This enables savings (~$15-45k/month) from contractors not having to move the mine''s "transition piles". ', NULL, N'Yes, we see when rock enters the muck circuit and hoisting system, but the system needs to be expanded for more precision on when and where. ', N'The system needs to be expanded for more precise information on when the rock enters the ore systems. ', 500000, 3, N'acesso aos laudos de potabilidade da água conforme a legislação brasileira.', '2026-01-09T00:00:00.000', '2026-02-13T09:49:58.000', 300837, NULL, 1);
INSERT INTO #PVC VALUES (8105, 548018, 502688, N'Proteção do Olhal de Fixação da Correia da TR-2009-06', NULL, N'Others/Outros', N' Durante inspeção na área da TR-2009-06, foi identificado que o olhal de fixação da correia encontrava-se exposto, sem qualquer tipo de proteção física.', N' Eliminar o risco de acidentes por queda ao mesmo nível, através da instalação de proteção adequada no olhal de fixação da correia da TR-2009-06, garantindo maior segurança operacional.', 10031, N'01 - Imagens/01 - Antes/8105.jpeg', N'Durante inspeção na área da TR-2009-06, foi identificado que o olhal de fixação da correia encontrava-se exposto, sem qualquer tipo de proteção física.', N'01 - Imagens/02 - Depois/8105.jpeg', N'Após a instalação da proteção no olhal de fixação, o risco de tropeço e queda ao mesmo nível foi eliminado, tornando a área mais segura para circulação e atividades operacionais.', NULL, N'SIM.
INSERT INTO #PVC VALUES (8106, 81047909, 482553, N'Melhora do método executivo para remover  o anel trava dos caminhões fora de estrada.', NULL, N'Others/Outros', N'Os anéis‑trava das rodas dos caminhões fora de estrada estavam sendo removidos manualmente e arremessados ao solo, gerando risco de projeção e possíveis lesões.', N'Eliminar o comportamento inseguro na remoção do anel‑trava, garantindo um método seguro, padronizado e seguido por todos, reduzindo a zero o risco de projeção da peça e protegendo os trabalhadores.', 10145, N'01 - Imagens/01 - Antes/8106.jpeg', N'Na inspeção Ver com os Pés, identificou‑se que o anel‑trava das rodas dos caminhões era removido manualmente e arremessado ao solo, gerando risco de projeção e possíveis danos aos trabalhadores.', N'01 - Imagens/02 - Depois/8106.jpeg', N'SESMT e Manutenção de Pneus desenvolveram dispositivo para remover anéis‑trava dos caminhões, garantindo fixação segura e eliminando risco de projeção, aumentando a segurança.', NULL, N'Sim. O problema foi resolvido com o dispositivo de engenharia, que garante fixação segura do anel‑trava e elimina o risco de projeção, padronizando o método e tornando a atividade segura.
INSERT INTO #PVC VALUES (8107, 81033139, 81033139, N'Ficha de movimentação de Blindagem', NULL, N'Others/Outros', N'Falta de informação confiável sobre a condição das blindagens impedia o planejamento adequado e resultava em ausência de estratégia para movimentações, gerando decisões reativas e perda de controle do desgaste dos componentes.
INSERT INTO #PVC VALUES (8108, 81047909, 81024241, N'Lubrificação e complementação de níveis hidráulicos de caminhões fora de estrada.', NULL, N'Others/Outros', N'Problema: empregado acessa a parte superior do caminhão com pistola e mangueira, sem manter três pontos de apoio. Impacto: risco de queda. Detecção: observado em campo durante a atividade.', N'Eliminar risco de queda, adequar meios de acesso, padronizar o método.', 10145, N'01 - Imagens/01 - Antes/8108.jpeg', N'Em atividades de lubrificação, o empregado acessava a parte superior do caminhão com pistola e mangueira, sem manter três pontos de apoio, descumprindo a NR 35 e gerando risco de queda.', N'01 - Imagens/02 - Depois/8108.jpeg', N'Após avaliações, instalou‑se no 797F um ponto de engate inferior para lubrificação, eliminando o acesso por escada, reduzindo risco de queda e aumentando a agilidade. Expansão aos demais modelos.', NULL, N'Sim. O problema foi resolvido com o ponto de engate inferior, que eliminou o acesso pela escada, reduziu o risco de queda e tornou a lubrificação mais segura.', N'Análise conjunta gera melhores resultados; acesso seguro deve ser priorizado; ajustar o ponto de operação evita exposição ao risco.', 0, NULL, N'Como melhoria, foi instalada uma mangueira para o enchimento das garrafas térmicas, proporcionando maior ergonomia e reduzindo o esforço físico dos colaboradores.”
INSERT INTO #PVC VALUES (8109, 513657, 52836, N'Silênciômetro', NULL, N'Concentration/Concentração', N'Atualmente, não existe monitoramento regular dos níveis de ruído nos prédios administrativos, dificultando a identificação de fontes de barulho que afetam a concentração, a produtividade e o bem-estar dos colaboradores. Sem dados confiáveis, não é possível definir padrões ou propor melhorias. Por isso, é necessário implementar medições contínuas com silenciômetro para reduzir ruídos e aprimorar o ambiente de trabalho.', N'Identificar, reduzir e controlar desperdícios e riscos relacionados ao ruído no processo.', 10189, N'01 - Imagens/01 - Antes/8109.jpeg', N'Além disso, nas salas administrativas também foi identificada a presença de ruído, o que acaba, de certa forma, atrapalhando as rotinas administrativas, especialmente atividades que exigem foco e reuniões.', N'01 - Imagens/02 - Depois/8109.jpeg', N'Com o uso do silenciômetro, tornou-se possível monitorar os níveis de ruído nos prédios administrativos ao longo do dia. As medições identificaram picos em horários de maior circulação e também ruídos provenientes de pessoas, que afetavam o foco e as reuniões. Além disso, o equipamento passou a auxiliar no controle do ambiente, sinalizando sempre que os limites de ruído eram ultrapassados, permitindo ações rápidas para restabelecer condições adequadas de trabalho.', NULL, N'Muitos trabalhadores não percebem que estão expostos a níveis perigosos de ruído ou que certas atividades exigem atenção especial.
INSERT INTO #PVC VALUES (8110, 81033139, 81033139, N'Forms de contagem de pneus meia vida', NULL, N'No Replication/Sem replicação', N'Falta de automatização do relátorio
INSERT INTO #PVC VALUES (8111, 81047909, 495588, N': Instalação de passarelas e guarda corpo nas subestações Skid.', NULL, N'Others/Outros', N'Subestações modelo Skid não possuem passarelas e proteção contra queda, colocando o empregado em risco de queda com diferença de nível sempre que fosse necessário o acesso à subestação.', N'Eliminar o risco de queda por diferença de níveis durante o acesso e execução de atividades nas subestações móveis modelo Skid.', 10145, N'01 - Imagens/01 - Antes/8111.jpeg', N'Para a execução das atividades de operação e manutenção em subestações Skid, as mesmas não possuem passarela e guarda-corpo, gerando risco de queda com diferença de nível.', N'01 - Imagens/02 - Depois/8111.jpeg', N'Foi feita a aquisição de passarelas com guarda-corpo e instalação das passarelas nas subestações que não possuem passarelas e guarda-corpo.', NULL, N'Foi feita a aquisição de passarelas com guarda-corpo e instalação das passarelas nas subestações que não possuem passarelas e guarda-corpo.', N'Devido ao erro do projeto foi feita a aquisição dos novos equipamentos (Subestações) contendo todos esses itens de proteções.', 0, NULL, N'no time wasted trying to unfreeze line', '2026-01-31T00:00:00.000', '2026-02-13T15:33:20.000', 81047909, NULL, 3);
INSERT INTO #PVC VALUES (8112, 1009274, 1009274, N'Manifold Crack Detection', NULL, N'Others/Outros', N'during troubleshooting, it was near impossible to see hairline cracks in HP Wash components', N'clearly understand if manifold has failed', 0, N'01 - Imagens/01 - Antes/8112.jpeg', N'very hard to see if the component had failed', N'01 - Imagens/02 - Depois/8112.jpeg', N'using penetrating dye, we''re able to see the defects.', NULL, N'solved', N'works well', 0, NULL, N'Rastreabilidade total do que está sendo comprado
INSERT INTO #PVC VALUES (8113, 1009274, 1009274, N'robot path improvement', NULL, N'Others/Outros', N'during injection of mandrels from ETD-005 to ECC-020, the mandrel would swing and allow contact with another mandrel while being placed.', N'eliminate contact collision', 0, N'01 - Imagens/01 - Antes/8113.jpeg', N'mandrel would swing and hit previously dropped mandrel. This would put it off notch and eventually fall from the next transfer device', N'01 - Imagens/02 - Depois/8113.jpeg', N'improved robot path to eliminate swing. No more contact', NULL, N'problem solved', N'works well', 0, NULL, N'A nova solução eliminou a necessidade de apoiar o saco no chão, reduziu o risco de lesões, padronizou o processo e melhorou a ergonomia e a fluidez da atividade durante a descarga de cobre.
INSERT INTO #PVC VALUES (8114, 81038902, 81038902, N'ENROLADOR DE MANGUEIRA ', NULL, N'Others/Outros', N'MANGUEIRA EXPOSTA NA AREA GERANDO RISCO DE ACIDENTE  DE QUEDA DE PESSOAS  DE MESMO NIVEL DEVIDO TROPEÇOS DEVIDO AS MANGUEIRAS ESPALHADAS NO ACESSO DE PESSOAS ', N'MUDAR ASPECTO FISICO E ORGANIZACIONAL DA AREA ', 10031, N'01 - Imagens/01 - Antes/8114.jpeg', N'MANGIUEIRAS EXPOSTAS NA AREA JOGADAS PELO ACESSO DE PESSOAS CAUSANDO RISCO DE ACIDENDE COMO TROPEÇOS E QUEDA DO MESMO NIVEL  LOCAL AL-2301SA-2 TUNEL SALOBO-3', N'01 - Imagens/02 - Depois/8114.jpeg', N'FOI FABRICADO E INSTALADO NA AREA UM ENROLADOR DE MANGUEIRAS PARA  DEIXAR AS MESMAS ENROLADAS ENROLADAS DE FORMA SEGURA E ORGANIZADA', NULL, N'SIM RESOLVIDO FOI FABRICADO E INTALADO UM ENROLADOR DE MANGUEIRAS ', N'FAZER DA NOSSA AREA UM LOCAL ORGANIZADO E SEGURO', 0, NULL, N'Clarity in making adjustments', '2026-01-26T00:00:00.000', '2026-02-13T21:04:24.000', 81038902, NULL, 2);
INSERT INTO #PVC VALUES (8115, 81038902, 81038902, N'TROLER REMOVEDOR DE CAPOTA ', NULL, N'Others/Outros', N'PARA DAR MANUTEÇAO NO CHUTE DE DESCARGA DO AL-2301SA-04 NAO TINHA COMO ACESSAR O CHUTE PORQUE NAO TINHA COMO REMOVDER A CAPOTA DO CHUTE ', N'REMOVER CAPOTA ', 10031, N'01 - Imagens/01 - Antes/8115.jpeg', N'NAO TINHA COMO REMOVER A CAPOTA DO CHUTE PARA PODERMOS ACESSAR PARA DAR MANUTEÇAO NAO TINHA COMO IÇAR ', N'01 - Imagens/02 - Depois/8115.jpeg', N'FOI INTALADO OLHAIS NA CAPOTA E MONTADO UM CARRO TROLER NA VIGA SUPEROR  ESISTENTE  E MONTADO UMA TALHA DE CORRETE ASSIM COSEGUIMOS REMOVER A CAPOTA ', NULL, N'FOI MONTADO OLHAIS NA CAPOTA E MONTADO UM CARRO TROLER MANUAL DE CORRENTE NO MESMO MONTAMOS A TALHA ASSIM COSEGUIMOS REMOVER A CAPOTA ', N'MELHORAR NOSSA CONDIÇAO DE TRABALHO NA AREA ', 0, NULL, N'Melhorado o diagnóstico no sistema devido ter duas referências de pressão independentes entre si, facilitando o diagnóstico, já que o manômetro funciona sem eletrônica sem alimentação e sem sinal, caso as pressões estejam muito divergentes entre si, o problema será direcionado ao transdutor de pressão.', '2026-01-20T00:00:00.000', '2026-02-13T21:42:30.000', 81038902, NULL, 1);
INSERT INTO #PVC VALUES (8116, 609342, 609342, N'Storeroom heater lock', NULL, N'No Replication/Sem replicação', N'Heater was turned off and safety shower system was nearing freezing temperatures.', N'To prevent safety shower pumps/lines from freezing', 10114, N'01 - Imagens/01 - Antes/8116.jpeg', N'The storeroom heater was unknowingly turned off during the cold weather. This room also houses the safety shower pumps and with the heater being unknowingly being turned off the safety shower lines and pumps wher less then 10 degrees away from the freezing point.', N'01 - Imagens/02 - Depois/8116.jpeg', N'The thermostat was placed under lock and key. If access to the thermostat is required, it is now required to get the key from the supervisor so the heater will not be left in the off position. ', NULL, N'The heater can only be accessed with supervisor knowledge so the heater will not be forgotten to be turned back on.', N'To be mindful of heaters importance during winter months', 0, NULL, NULL, '2026-02-03T00:00:00.000', '2026-02-14T00:01:08.000', 609342, NULL, 1);
INSERT INTO #PVC VALUES (8117, 520046, 520046, N'QR code para acesso ao laudos da qualidade da água potável. ', NULL, N'Others/Outros', N'Restrição de acesso a informação cabível a todos, gerando especulações e falta de informação técnica. ', N'Facilitar e garantir o acesso a informação certa.', 10139, N'01 - Imagens/01 - Antes/8117.jpeg', N'Acesso aos laudos do monitoramento da qualidade da água potável dos bebedouros da oficina era restrita para apenas a equipe de saneamento e auditorias internas e externas.
INSERT INTO #PVC VALUES (8118, 520046, 520046, N'Instalação de indicador (medidor) de nível caminhão pipas. ', NULL, N'Others/Outros', N'Tanque sem visor de nível, aplicado visor de nível de forma de fácil visualização.', N'Garantir controle preciso do volume de água transportado, aumentando a confiabilidade operacional, a segurança e a rastreabilidade das atividades realizadas com caminhões pipa.', 10139, N'01 - Imagens/01 - Antes/8118.jpeg', N'O motorista e os lavadores de equipamentos estavam com dificuldade em visualizar a quantidade de água no tanque do caminhão pipa, comprometendo a rotina operacional e a troca de turno.
INSERT INTO #PVC VALUES (8119, 81030117, 81057321, N'RELE BOMBA ESCORVA (PZ23)', NULL, N'Others/Outros', N'Anteriormente, a bomba operava apenas de forma manual. Foi instalado um circuito em paralelo, onde a bomba é acionada automaticamente por aproximadamente 10 segundos sempre que o primeiro estágio do equipamento é ligado.', N'Proporcionar uma partida mais suave, além de reduzir esforços no sistema de alimentação e aumentar a confiabilidade operacional.', 10324, N'01 - Imagens/01 - Antes/8119.jpeg', N'nteriormente, a bomba operava apenas de forma manual. Foi instalado um circuito em paralelo, onde a bomba é acionada automaticamente por aproximadamente 10 segundos sempre que o primeiro estágio do equipamento é ligado.', N'01 - Imagens/02 - Depois/8119.jpeg', N'Na última manutenção preventiva da PZ-23, foi implementada uma melhoria no sistema da bomba de escorva. Anteriormente, a bomba operava apenas de forma manual. Foi instalado um circuito em paralelo, onde a bomba é acionada automaticamente por aproximadamente 10 segundos sempre que o primeiro estágio do equipamento é ligado.
INSERT INTO #PVC VALUES (8120, 81030117, 81057321, N'CHAPA DE LEITURA DO SENSOR (PZ20)', NULL, N'Others/Outros', N'Diminuição  de falhas na leitura do sensor do griper, evitando paradas não programadas do equipamento.', N'Diminuiação de falhas na leitura do sensor do griper. ', 10324, N'01 - Imagens/01 - Antes/8120.jpeg', N'Diminuição  de falhas na leitura do sensor do griper, evitando paradas não programadas do equipamento.', N'01 - Imagens/02 - Depois/8120.jpeg', N'Foi modificada a posição da chapa de leitura do sensor de posição do griper da PZ-20, com aumento do raio de leitura do sensor.
INSERT INTO #PVC VALUES (8121, 81030117, 81057321, N'MANGUEIRA PARA ENCHIMENTO DAS GRRAFAS TÉRMICAS', NULL, N'Others/Outros', N'
INSERT INTO #PVC VALUES (8122, 81030117, 81002626, N'SUPORTE PARA CILINDRO DA PATOLA', NULL, N'Others/Outros', N'A apoiar a máquina no chão com o cilindro causava avarias no piso.', N'EVITAR DESGASTE DO CILINDRO E DO PISO.', 10324, N'01 - Imagens/01 - Antes/8122.jpeg', N'A apoiar a máquina no chão com o cilindro causava avarias no piso.', N'01 - Imagens/02 - Depois/8122.jpeg', N'Foi feito suporte de apoio do cilindro da patola evitando desgaste prematuro no piso.', NULL, N'Foi feito suporte de apoio do cilindro da patola evitando desgaste prematuro no piso.', N'ATENÇÃO AS ATIVIDADES PARA EVITAR DESGASTE DAS AREAS DE MANUTENÇÃO', 0, NULL, NULL, '2026-02-07T00:00:00.000', '2026-02-14T17:15:47.000', 81030117, NULL, 1);
INSERT INTO #PVC VALUES (8123, 81045248, 81023782, N'glove dispenser', NULL, N'No Replication/Sem replicação', N'we need appropriate places to put extra gloves in case we are in the field and one of the ones we are wearing breaks. 
INSERT INTO #PVC VALUES (8124, 81045248, 81023782, N'wharf water line air fitting ', NULL, N'No Replication/Sem replicação', N'water line for wharf water continues to build up and freeze making it difficult for us to pump wharf water into the repulp tank ', N'allow water flow', 0, N'01 - Imagens/01 - Antes/8124.jpeg', N'wharf water line frozen making it difficult to pump wharf water into the repulp tank ', N'01 - Imagens/02 - Depois/8124.jpeg', N'air line installed to flush water so it does not build up and freeze. Can be used after each time we pump water into the tank - preparing us for the next time we pump', NULL, N'we no longer need to waste time trying to unfreeze the wharf water line to pump water ', N'flush line preventing freezing ', 0, NULL, N'Proper signage for bathroom to allow workers to know where bathroom is located', '2026-02-13T00:00:00.000', '2026-02-14T18:48:28.000', 81045248, NULL, 1);
INSERT INTO #PVC VALUES (8125, 550315, 550315, N'GESTÂO DE REQUISIÇÂO DE COMPRAS MENSAIS', NULL, N'No Replication/Sem replicação', N'desvios e inconsistências na rastreabilidade do pedido → aprovação → compra → entrega', N'Padronizar e organizar o fluxo de requisições', 10023, N'01 - Imagens/01 - Antes/8125.jpeg', N'Orçamento mensal se descontrola
INSERT INTO #PVC VALUES (8126, 81039464, 81010117, N'Coletor de Amostras  ', NULL, N'Others/Outros', N'Durante a descarga de cobre, o colaborador realiza a coleta das amostras apoiando o saco de amostras no chão, em posição ergonomicamente inadequada. Esse método aumenta o esforço físico, gera risco de lesões  e torna o processo mais lento e menos eficiente.
INSERT INTO #PVC VALUES (8127, 460346, 1005247, N'Cd Circuit Stability PI Vision', NULL, N'Projects/Projetos', N'The flowmeter is reading incorrectly and we need a means to clearly identify if we are operating at the correct flows.', N'Create a Chart', 0, N'01 - Imagens/01 - Antes/8127.jpeg', N'The flowmeter on reactor 3 is reading incorrectly and we need a means to clearly identify if we are operating at the correct flows while we wait for a maintenance resolution to the problem.', N'01 - Imagens/02 - Depois/8127.jpeg', N'Added a chart to the stability page just for temporary use, its calculating what we should be at if we assume the flowmeter to PR1 is what we are actually at in #3 and using the scale consumption as well.', NULL, N'Yes, temporarily until the proper fix can be implimented.', N'Visual representations improve clarity', 0, NULL, N'O tempo de levantamento dos dados sai de 30 min para 3.', '2026-02-14T00:00:00.000', '2026-02-15T04:51:02.000', 460346, NULL, 1);
INSERT INTO #PVC VALUES (8128, 81035620, 539582, N'Manômetro de monitoramento de pressão do óleo do redutor de elevação', NULL, N'Open Pit/Poço aberto', N'Dificuldade no diagnóstico de falhas no sistema de elevação.', N'Melhorar a rapidez do diagnóstico de falhas no sistema hidráulico do redutor de elevação.', 10324, N'01 - Imagens/01 - Antes/8128.jpeg', N'  Devido a não ter dois monitoramentos de pressão independentes entre si, havia uma demora no diagnóstico, devido a falta de isolação do problema, se era ele hidráulico ou elétrico.', N'01 - Imagens/02 - Depois/8128.jpeg', N'Melhorado o diagnóstico no sistema devido ter duas referências de pressão independentes entre si, facilitando o diagnóstico, já que o manômetro funciona sem eletrônica sem alimentação e sem sinal, caso as pressões estejam muito divergentes entre si, o problema será direcionado ao transdutor de pressão.', NULL, N'  Devido a não ter dois monitoramentos de pressão independentes entre si, havia uma demora no diagnóstico, devido a falta de isolação do problema, se era ele hidráulico ou elétrico.', N'Sempre procurar formas de melhorar o diagnóstico de sistemas que podem ser isolados, facilitando a compreensão.', 0, NULL, N'We improved defect.', '2026-01-22T00:00:00.000', '2026-02-15T08:17:51.000', 81035620, NULL, 1);
INSERT INTO #PVC VALUES (8129, 81049934, 81049934, N'Steel form bumper block forms ', NULL, N'Underground/Subterrâneo', N'we were making them out of wood and also wasting cement/shotcrete and plywood, now we can have close to work site when pouring anything and put it in 
INSERT INTO #PVC VALUES (8130, 81006946, 81034722, N'SUPORTE ENROLADOR DE MANGUEIRAS', NULL, N'No Replication/Sem replicação', N'Primeiramente, a mangueira costuma ficar espalhada pelo chão, ocupando espaço de circulação. Em uma oficina, onde já há movimentação constante de pessoas, ferramentas e veículos, isso aumenta significativamente o risco de tropeços, quedas e acidentes de trabalho e também o risco de danos a mangueira.', N'FACILITA NA HORA DE USAR E GUARDAR', 10139, N'01 - Imagens/01 - Antes/8130.jpeg', N'Ficava exposta ao sol, óleo, graxa e resíduos químicos, acelerando o desgaste do material.
INSERT INTO #PVC VALUES (8131, 81049937, 81049937, N'150 kVA Transformer Substitution - Lead Time Reduction ', NULL, N'Projects/Projetos', N'A 150 kVA transformer was scheduled to arrive after completion of the remainder of the project causing the critical path to be stretched out. ', N'Reduce Lead Time', 10338, N'01 - Imagens/01 - Antes/8131.jpeg', N'A 150 kVA transformer was scheduled to arrive after completion of the remainder of the project causing the critical path to be stretched out. ', N'01 - Imagens/02 - Depois/8131.jpeg', N'Project Execution team worked with their contractor and Engineering to specify an alternate transformer with a shorter lead time. This removed 9 weeks from the project''s critical path. ', NULL, N'Yes. As a result of this kaizen, the project will now be completed 9 weeks earlier. ', N'Lead times for equipment may be able to be reduced by adjusting procurement specifications', 0, NULL, NULL, '2026-02-14T00:00:00.000', '2026-02-15T17:41:14.000', 81049937, NULL, 1);
INSERT INTO #PVC VALUES (8132, 81061537, 81061537, N'Melhoria no ponto de amostragem do Concentrado.', NULL, N'No Replication/Sem replicação', N'Dificuldades na coleta e ergonomia, material caia fora sujando o piso.', N'Melhoria da  ergonia e 5S', 10054, N'01 - Imagens/01 - Antes/8132.jpeg', N'Antes da intervenção, o ponto de amostragem apresentava um fluxo direcionado para a frente, o que resultava em respingos constantes durante a coleta. Essa condição gerava sujeira no operador e na área ao redor, aumentando o risco de escorregamentos e a necessidade de limpezas frequentes. Além disso, a posição do ponto era ergonomicamente desfavorável, exigindo que o colaborador se inclinasse excessivamente ou realizasse movimentos desconfortáveis para acessar o fluxo, elevando o risco de fadiga muscular e potenciais lesões.', N'01 - Imagens/02 - Depois/8132.jpeg', N'A melhoria implementada reposicionou o sistema de amostragem e redirecionou o fluxo, garantindo que o material agora seja conduzido de forma segura, controlada e direcionada para baixo que ira cair diretamente dentro da 2351 CX 05. Com isso, eliminam-se respingos, melhorando a limpeza, aumentando a segurança e reduzindo o esforço físico necessário. A nova configuração oferece melhor ergonomia, permitindo que o operador realize a coleta em postura adequada, com menor alcance e maior estabilidade.
INSERT INTO #PVC VALUES (8133, 537635, 537635, N'Eficiência Luminosa 360', NULL, N'Others/Outros', N'Iluminação insuficiente na área de filtragem, causando baixa visibilidade e aumentando o risco de acidentes durante as atividades operacionais e de manutenção.', N'Eliminar a condição Insegura ', 10245, N'01 - Imagens/01 - Antes/8133.jpeg', N'A ILUMINAÇÃO ENTRE OS DOIS FILTROS ESTAVA INSUFICIENTE, DEIXANDO A AREÁ ESCURA E COM BAIXA VISIBILIDADE. ESSA CONDIÇÃO DIFICULTA INSPEÇÕES, ALÉM DE AUMENTAR O RISCO DE ACIDENTES.', N'01 - Imagens/02 - Depois/8133.jpeg', N'APÓS A IMPLEMENTAÇÃO DE DOIS REFLETORES DE 100WATTS DE POTENCIA, A ILUMINAÇÃO DA ARÉA FOI ADEQUADA E PADRONIZADA, ELIMINANDO PONTOS DE BAIXA VISIBILIDADE. COMO RESULTADO, HOUVE AUMENTO DA SEGURANÇA, REDUÇÃO DE RISCOS DE ACIDENTES E MELHORIA NA EXECUÇÃO DAS ATIVIDADES.', NULL, N'SIM, COM OS REFLETORES INSTALADOS FOI ALCANÇADOS OS OBJETIVOS DA ILUMINAÇÃO.', N'VER E AGIR.', 0, NULL, N'OPERAÇÃO DO EQUIPAMENTO SEM PROBLEMAS COM O OLHAL.', '2026-02-15T00:00:00.000', '2026-02-16T00:57:55.000', 537635, NULL, 2);
INSERT INTO #PVC VALUES (8134, 81050085, 81050085, N'Melhoria Iluminação', NULL, N'Others/Outros', N'Ausência de iluminação na rua do sag, comprometendo a visibilidade e a circulação de pessoas e veículos resultando em riscos: Queda, tropeço, colisões e dificuldades em identificar . Gerando insegurança e dificuldade para o time que executa atividades em torno do local.', N'Eliminação de risco', 10044, N'01 - Imagens/01 - Antes/8134.jpeg', N'Ausência de iluminação na rua do sag, comprometendo a visibilidade e a circulação de pessoas e veículos resultando em riscos: Queda, tropeço, colisões e dificuldades em identificar . Gerando insegurança e dificuldade para o time que executa atividades em torno do local.', N'01 - Imagens/02 - Depois/8134.jpeg', N'Foi realizado a melhoria na iluminação reduzindo os riscos: Queda, tropeço, colisões. Proporcionando maior segurança operacional, melhorando a visibilidade para os operadores e suporte adequado as atividades de limpeza, deixando assim de usar refletores portáteis que muita das vezes descarregava durante as atividades e era necessario parar para realizar substituição. ', NULL, N'sim! eliminamos os riscos e adequamos o cenário.', N'adequação e melhorias', 2, 1, N'Aumento significativo da iluminação da área
INSERT INTO #PVC VALUES (8135, 81034398, 81048340, N'RECUPERAÇÃO DO ESTRIBO', NULL, N'Others/Outros', N'O ESTRIBO DA EC34 ESTAVA AMASSADO', N'RECUPERAR O ESTRIBO', 10139, N'01 - Imagens/01 - Antes/8135.jpeg', N'O ESTRIBO DA ESCAVADEIRA ESTAVA AMASSADO O QUE ESTAVA DIFICULTANDO O ACESSO AO EQUIPAMENTO, A SUPERFÍCIE ESTAVA IRREGULAR O QUE  CONTRIBUIA PARA QUE O PÉ FICASSE ESCORREGANDO DURANTE O ACESSO AO EQUIPAMENTO O QUE PODERIA OCASIONAR A QUEDA E A ATÉ MESMO TORÇÃO NO PÉ.', N'01 - Imagens/02 - Depois/8135.jpeg', N'A EQUIPE DE SOLDADORES REALIZOU A RECUPERAÇÃO DO ESTRIBO, O ESTRIBO FOI DESSAMADO E FOI RECONSTITUIO AO FORMATO ORIGINAL E FOI APLICADO NOVAMENTE NO EQUIPAMENTO, ASSIM GARANTINDO O ACESSO AO EQUIPAMENTO DE FORMA SEGURA, E REDUÇÃO DE  CUSTO AO RECUPERAR O ESTRIBO EVITANDO A COMPRA DE UMA NOVA PEÇA. ', NULL, N'SIM, COM A RECUPERAÇÃO DO ESTRIBO A DIFICULDADE PARA AESSAR O EQUIPAMENTO FOI CORRIGIDA.', N'TRATAR ANOMALIAS PEQUENAS IMEDIATAMENTE EVITA ACIDENTES, CUSTOS E PARADAS FUTURAS', 682, 1, N'IMPRESSORA REALIZARÁ SEU TRABALHO SEM SOFRER VIBRAÇÕES.', '2026-02-12T00:00:00.000', '2026-02-16T10:24:33.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (8136, 81034398, 81048340, N'RECUPERAÇÃO DO ESTRIBO', NULL, N'Others/Outros', N'ESTRIBO DA ESCAVADEIRA EC34 ESCONTRAVA - SE AMASSADO', N'RECUPERAR O ESTRIBO', 10139, N'01 - Imagens/01 - Antes/8136.jpeg', N'O ESTRIBO DA ESVADEIRA ESTAVA AMASSADO O QUE ESTAVA DIFICULTANDO O ACESSO AO EQUIPAMENTO DEVIDO NÃO TER UM APOIO COMPLETO , AO SUBIR NO EQUIPAMENTO COM O ESTRIBO AMASSADO PODIA OCASIONAR TORÇÃO NO PÉ E ATÉ MESMO QUEDA DOS COLABORDORES.', N'01 - Imagens/02 - Depois/8136.jpeg', N'A EQUIPE DE SOLDADORES REALIZOU A RECUPERAÇÃO DO ESTRIBO DESAMASSANDO E RECONSTITUINDO A FORMA ORIGINAL DA PEÇA, O ESTRIBO FOI RELOCADO NO EQUIPAMENTO, O QUE GARANTIU ACESSO SEGURO AO EQUIPAMENTO E CONTRIBUIU PARA REDUÇÃO DE CUSTO, EVITANDO A COMPRA DE UMA NOVA PEÇA PARA O EQUIPAMENTO', NULL, N'SIM, COMA RECUPERAÇÃO DO ESTRIBO GARANTIU O ACESSO SEGURO AO EQUIPAMENTO, GARANTINDO A SEGURANÇA DE QUEM ACESSA O EQUIPAMENTO', N'Tratar anomalias pequenas imediatamente evita acidentes, custos e paradas futuras.', 1812, 1, N'Padronizar e manter a gestão visual do LAIA nas frentes de serviço, garantindo maior conscientização ambiental, melhor aplicação dos controles operacionais e fortalecimento da conformidade com a ISO 14001.', '2026-02-12T00:00:00.000', '2026-02-16T10:56:15.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (8137, 1015684, 1015684, N'Washroom Signage', NULL, N'Refining/Refino', N'The washrooms upstairs in the 212 Annex had no signage.', N'To have proper signage in place', 0, N'01 - Imagens/01 - Antes/8137.jpeg', N'There was signage on the 2 washrooms in the upstairs annex in 212. ', N'01 - Imagens/02 - Depois/8137.jpeg', N'Added signage to the washrooms. They are now properly labelled.', NULL, N'Yes, signage now in place, workers can see that doors are for bathrooms.', N'Proper signage now in place, people know where the bathrooms are.', 0, NULL, N'Df do equipamento', '2026-02-15T00:00:00.000', '2026-02-16T12:47:32.000', 1015684, NULL, 1);
INSERT INTO #PVC VALUES (8138, 471868, 471868, N'Economia de álcool', NULL, N'Others/Outros', N'Foi observado que durante a limpeza das identificações das amostras nas vidrarias com auxilio de álcool havia um gasto excessivo com uso de uma pisseta.', N'Redução no consumo de álcool', 10235, N'01 - Imagens/01 - Antes/8138.jpeg', N'Antes era utilizado uma pisseta com álcool e foi observado durante o uso um gasto excessivo de álcool durante a limpeza das vidrarias.  ', N'01 - Imagens/02 - Depois/8138.jpeg', N'Houve a substituição da pisseta por um borrifador gerando uma diminuição no consumo de álcool durante o processo de limpeza das vidrarias.', NULL, N'Sim, foi gerado uma economia no consumo de álcool.', N'Economia', 0, NULL, N'Improved user experience
INSERT INTO #PVC VALUES (8139, 532872, 532872, N'Padrão de Reports Gestão  de Ativos', NULL, N'Others/Outros', N'O envio de comunicado era feito via e-mail não padronizado. ', N'Padronizar envio de Informação', 10081, N'01 - Imagens/01 - Antes/8139.jpeg', N'O envio de comunicados era feito de forma não padronizada.', N'01 - Imagens/02 - Depois/8139.jpeg', N'Criado mascara para envio de Reports padronizado da Gestão de Ativos, criando identidade da área, e reforçando o compromisso com a padronização de processo.', NULL, N'Sim, o modelo implantado ficou simples e único.', N'Padronizar cria identidade da marca', 0, NULL, N'Work area is now easier to keep clean then before', '2026-02-06T00:00:00.000', '2026-02-17T06:25:37.000', 532872, NULL, 3);
INSERT INTO #PVC VALUES (8140, 532872, 532872, N'Dashboard de Workflow- Escalation Notice', NULL, N'Others/Outros', N'Falta de visão do  Escalation Notice com forco no perfil de perdas', N'Integrar Perfil de perdas ao Escalation Notice', 10081, N'01 - Imagens/01 - Antes/8140.jpeg', N'Antes o time precisava olhar para o BI com as ordens escalonadas e ir até o SAP para mapear onde o processo estava parado, e sinalizar no  .ppt do FMDS o status.', N'01 - Imagens/02 - Depois/8140.jpeg', N'Foi desenvolvido um dashboard integrado para acompanhar as as demandas escalonadas e com prazo próximo de escalonamento, garantindo a correta priorização e o tratamento das pendências críticas.', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/b3e4e13a-7754-49dd-af39-3c0425029c14/c732fa703603ba829063?experience=power-bi', N'sim, integração realizada e aprovada', N'Integração como solução ', 0, NULL, N'Perda evitada de 180 mil reais dia.', '2026-02-02T00:00:00.000', '2026-02-17T06:44:09.000', 532872, NULL, 3);
INSERT INTO #PVC VALUES (8141, 87000312, 87000335, N'Introducing rubber covers to protect wire ropes', NULL, N'Refining/Refino', N'Defect', N'To prevent problem with wire rope', 0, N'01 - Imagens/01 - Antes/8141.jpeg', N'When using wire ropes to lift heavy objects or lumber, they can easy to kink or collapse, making them unusable for safety reasons.', N'01 - Imagens/02 - Depois/8141.jpeg', N'When using wire rope, a rubber cover is wrapped around the wire to prevent kinking.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset', 0, NULL, N'Multiplicar conhecimento.', '2026-02-15T00:00:00.000', '2026-02-17T07:53:30.000', 87000312, NULL, 1);
INSERT INTO #PVC VALUES (8142, 87000312, 87000312, N'Wi-Fi installation in the previous production office', NULL, N'Refining/Refino', N'Defect', N'To improve internet environment in the previous production office', 0, N'01 - Imagens/01 - Antes/8142.jpeg', N'The old production office did not have an internet connection, which was inconvenient when using the room for training etc. as it was not possible to provide materials online.', N'01 - Imagens/02 - Depois/8142.jpeg', N'The mobile Wi-Fi (Global Wi-Fi) that was kept for overseas business trips and was not used except for business trips was moved to the previous production office so that it can be used for regular training and meetings. This improved the internet environment in the room without any cost.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Eliminado fatores de riscos a segurança do colaborador, e agilidade no processo de rotina.', '2026-02-16T00:00:00.000', '2026-02-17T07:59:36.000', 87000312, NULL, 1);
INSERT INTO #PVC VALUES (8143, 81034398, 81004817, N'INSTALAÇÃO DO FAROL', NULL, N'Others/Outros', N'EQUIPAMENTO EC 31 ENCOTRAVA SEM FAROL NA PARTE DA FRENTE DO EQUIPAMENTO', N'AUMENTO DA VISIBILIDADE DURANTE A OPERAÇÃO A NOITE', 10139, N'01 - Imagens/01 - Antes/8143.jpeg', N'O EQUIPAMENTO DURANTE A OPERAÇÃO A NOITE ESTAVA COM BAIXA VISIBILIDADE, O QUE ESTAVA DIFICULTANDO A OPERAÇÃO A NOITE.', N'01 - Imagens/02 - Depois/8143.jpeg', N'FOI INSTALADO UM FAROL NO STICK DA MAQUINA, ASSIM MELHORANDO A VISIBILADE DURANTE A OPERAÇÃO A NOITE. ', NULL, N'SIM , COM A INSTALAÇÃO DO FAROL A BAIXA VISIBILIDADE NOTURNA FOI CORRIGIDA', N'PEQUENAS MUDANÇAS TRAZEM GRANDES RESULTADOS', 0, NULL, N'Monitorar continuamente a temperatura e mantê‑la dentro dos parâmetros operacionais recomendados é fundamental para garantir a estabilidade do processo de moagem. Esse controle permite: Apoiar a tomada de decisão operacional; Evitar paradas por nível alto de carvão na moagem e Prevenir alarmes e paradas por alta temperatura na tremonha do filtro de mangas', '2026-02-16T00:00:00.000', '2026-02-17T10:25:23.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (8144, 1010597, 1010597, N'Backcharging Small Tools and Consumables for Contractors', NULL, N'Others/Outros', N'Embedded contractors have access to Vale''s Fastenal vending machines on site in Long Harbour. These costs are intended to be back-charged to contractors due to the small tools and consumables clauses within our agreements.', N'Recoup cost of items taken by contractor from Fastenal vending machines and track monthly utilization and credits for contractor usage', 0, N'01 - Imagens/01 - Antes/8144.jpeg', N'Embedded maintenance contractor has access to Vale''s Fastenal vending machines on site in Long Harbour. Costs are being incurred by Vale without process in place to recuperate these charges.', N'01 - Imagens/02 - Depois/8144.jpeg', N'Automated report being generated by Fastenal and sent to contract analyst for review and application of credits for small tools and consumables each month.', NULL, N'YES - having automate report supplied by Fastenal enables contract analyst to apply accurate monthly credits to contractors'' invoice submissions and back-charge contractors for items included in the small tools and consumables clauses.', N'Review access to vending machines to validate contractor utilization and recuperate credits', 186000, 3, N'Com a instalação da tela de proteção, eliminamos riscos com possíveis eventos que podem acontecer com essa atividade rotineira,', '2026-02-16T00:00:00.000', '2026-02-17T10:34:17.000', 1010597, NULL, 1);
INSERT INTO #PVC VALUES (8145, 81050795, 81038871, N'Sistema de Escoramento Provisório para Substituição de Longarinas', NULL, N'Projects/Projetos', N'Durante a substituição das longarinas do transportador, o método convencional exigia a desmontagem individual de cavaletes e roletes para retirada da estrutura comprometida.
INSERT INTO #PVC VALUES (8146, 81034398, 81048340, N'RECUPERAÇÃO DO OLHAL DO CILINDRO', NULL, N'Others/Outros', N'O OLHAL DO CILINDRO ESTAVA COM TRINCA', N'RECUPERAR OLHAL', 10139, N'01 - Imagens/01 - Antes/8146.jpeg', N'OLHAL DO CILINDRO DA MA 83 ENCONTRAVA SE COM UM TRINCA , O QUE ESTAVA CAUSANDO DESGASTE DO CILINDRO E RISCO DE PERDA COMPLETA DO OLHAL, O QUE SERIA NECESSÁRIO A COMPRA DE OUTRO. ', N'01 - Imagens/02 - Depois/8146.jpeg', N'FOI REALIZADO RECUPERAÇÃO DO OLHAL PELA A EQUIPE DE SOLDADORES, FOI PREENCHIDA A TRINCA COM SOLDA , REALIZADO LIXAMENTO NA PEÇA E REECONTITUIDO A SUA FORMA ORIGINAL, FOI REALIZADO PINTURA , ASSIM REDUZIU CUSTO POR NÃO SER NECESSÁRIO COMPRAR UMA PEÇA NOVA', NULL, N'SIM, COM A REALIZAÇÃO DA SOLDA O OLHAL VOLTOU A SUA FORMA ORIGINAL E O EQUIPAMENTO VOLTOU A OPERAR', N'A IMPORTÂNCIA DE TER CUIDADO COM OS ATIVOS COM O QUAL TRABALHAMOS', 0, NULL, N'Potential for dropped objects was eliminated.', '2026-02-11T00:00:00.000', '2026-02-17T10:57:23.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (8147, 525172, 81054503, N'Instalação de Iluminação Scarvegen SLB no CF‑2017‑23', NULL, N'Projects/Projetos', N'A área do CF‑2017‑23 apresentava baixa luminosidade, especialmente durante atividades de manutenção e inspeção em altura. A insuficiência de iluminação aumentava o risco de incidentes, dificultava a visibilidade de componentes mecânicos e comprometia a qualidade dos serviços realizados.', N'Melhorar a iluminação da área, garantindo maior segurança operacional. Eliminar pontos de sombra que dificultavam manobras e inspeções técnicas.', 10229, N'01 - Imagens/01 - Antes/8147.jpeg', N'a área apresentava iluminação insuficiente, principalmente nos pontos elevados da estrutura. A baixa luminosidade dificultava a realização de inspeções e manutenções, criando pontos de sombra que comprometiam a visibilidade dos operadores. Essa condição aumentava o risco de incidentes, tornava mais difícil identificar anomalias e gerava insegurança durante atividades noturnas ou em dias de baixa claridade.', N'01 - Imagens/02 - Depois/8147.jpeg', N'Foi instalada uma luminária modelo Scarvegen SLB, posicionada em poste metálico, proporcionando iluminação direcionada e abrangente para toda a área de operação do CF‑2017‑23. benefícios obtidos: Aumento significativo da iluminação da área, redução do risco de acidentes por baixa visibilidade, maior segurança para operações de manutenção e inspeção.', NULL, N'A meta inicial era corrigir a baixa iluminação no CF‑2017‑23, que gerava dificuldade para inspeções, aumentava o risco de acidentes e comprometia a segurança das atividades. Com a instalação da luminária Scarvegen SLB, o local passou a ter iluminação adequada, eliminando pontos de sombra e melhorando significativamente a visibilidade e a segurança operacional. Assim, o problema declarado foi totalmente resolvido e a meta foi plenamente alcançada', N'Planejamento prévio evita retrabalhos e garante melhor definição do ponto de instalação, Segurança foi essencial, especialmente em trabalho em altura e manuseio elétrico.', 0, NULL, N'Removed tools that are not required in the area.', '2026-02-10T00:00:00.000', '2026-02-17T11:44:26.000', 525172, NULL, 3);
INSERT INTO #PVC VALUES (8148, 81034398, 530396, N'SUPORTE PARA A IMPRESSORA', NULL, N'Others/Outros', N'IMPRESSORA ESTAVA SEM SUPORTE ', N'FAZER UM SUPORTE PARA A IMPRESSORA', 10139, N'01 - Imagens/01 - Antes/8148.jpeg', N'A IMPRESSORA ESTAVA SEM SUPORTE PARA ARMAZENAR  A MESMA E FICAR DISPONÍVEL PARA USO NA SALA DE INFRA', N'01 - Imagens/02 - Depois/8148.jpeg', N'FOI FABRICADO UM SUPORTE PARA ARMAZENAR A IMPRESSORA , ASSIM A IMPRESSORA FICOU DISPONÍVEL PARA SER UTILIZADA', NULL, N'SIM , COM A FABRICAÇÃO DO SUPORTE A IMPRESSORA AGPRA TEM UM LOCAL EXATO PARA ARMAZENA LA.', N'UM SUPORTE ADEQUADO EVITA QUEDA E AUMENTA A VIDA UTIL.', 0, NULL, N'Foi reduzido em até 50% a dependência dos comboios de lubrificação. Melhorando o abastecimento dos equipamentos em preventiva ', '2026-02-10T00:00:00.000', '2026-02-17T12:27:30.000', 81034398, NULL, 1);
INSERT INTO #PVC VALUES (8149, 81050795, 81038871, N'LAIA Lúdico em Campo', NULL, N'Others/Outros', N'A divulgação do Levantamento de Aspectos e Impactos Ambientais (LAIA) era realizada de forma pontual e descentralizada, principalmente por meio de DSS e lâminas informativas avulsas.
INSERT INTO #PVC VALUES (8150, 81045945, 483385, N'PLACA DE ALIMENTAÇÃO', NULL, N'Others/Outros', N'Placa de alimentação digital 24 volts,estava dando curto na alimentação da placa danificando os periféricos eletrônicos, ocasionando várias paradas em corretiva.', N'PRODUTIVIDADE', 10324, N'01 - Imagens/01 - Antes/8150.jpeg', N'Placa de alimentação digital 24 volts,estava dando curto na alimentação da placa danificando os periféricos eletrônicos, ocasionando várias paradas em corretiva.', N'01 - Imagens/02 - Depois/8150.jpeg', N'Foi instalado um fusível de 5 A na linha de alimentação da placa digital, eliminando risco de curto na placa digital, e consequentemente paradas em corretiva.', NULL, N'Sim, agora diminuiu as paradas', N'PLANEJAMENTO E INSPEÇÃO', 0, NULL, N'Otimização de tempo para atualização.', '2026-02-16T00:00:00.000', '2026-02-17T14:18:13.000', 81045945, NULL, 1);
INSERT INTO #PVC VALUES (8151, 201675, 201675, N'Transform OT Remote Access', NULL, N'Others/Outros', N'Current OT remote access issues:
INSERT INTO #PVC VALUES (8152, 1015684, 1015684, N'Floor Mat for 211 sample shed', NULL, N'Crusher/Britadeira', N'There was no mat in the 211 con sample shed, this would lead to workers entering with wet boots and leaving a mess on the floor.', N'To ensure there was somewhere for workers to wipe muddy boots and have a clean floor/work area', 0, N'01 - Imagens/01 - Antes/8152.jpeg', N'There was no mat in the 211 con sample shed, this would lead to workers entering with wet boots and leaving a mess on the floor.', N'01 - Imagens/02 - Depois/8152.jpeg', N'Purchased and put in place a floor mat to give workers somewhere to wipe off wet boots when entering the sample shed, the rest of the workspace now stays clean.', NULL, N'Yes, problem was solved, mat allows workers to clean boots.', N'Proper materials in place are key to keeping clean work environment', 0, NULL, N'Outcome was as expected, signage is now much more visible.  ', '2026-02-16T00:00:00.000', '2026-02-17T16:07:17.000', 1015684, NULL, 1);
INSERT INTO #PVC VALUES (8153, 505203, 505203, N' Prevenção de Paradas por Sobrecarga nos Alimentadores da Prensagem de SLB III', NULL, N'Projects/Projetos', N' Parada do alimentador AL2303SA-01 ocorrida em 11/02/2026, devido à sobrecarga.
INSERT INTO #PVC VALUES (8154, 92000158, 92000158, N'Passo a passo ', NULL, N'Others/Outros', N'Não havia uma instrução detalhada do processo, o que dificultava muito o aprendizado da atividade . Tanto para os novos contratados quanto para caso houvesse algum necessidade de outra pessoa atuar na demanda.', N'Handover', 10142, N'01 - Imagens/01 - Antes/8154.jpeg', N'Antes as transferências só uma pessoa tinha acesso a demanda,  muitos erros na emissão de notas, gerava remessa errada, nota não tinha como cancelar. o que ocorria um gap no processo.  ', N'01 - Imagens/02 - Depois/8154.jpeg', N'Detalhamento no processo /demanda. Mais pessoas tem acesso ao passo a passo, erros e acertos, orientação e padronização.
INSERT INTO #PVC VALUES (8155, 81032668, 81032668, N'Tubulação para auxílio de desobstrução ', NULL, N'Others/Outros', N'Antes não havia tubulação dificultando o processo de desobstrução, com mais lentidão e exposição a riscos ', N'Acelerar e tornar mais seguro a atividade de desobstrução do equipamento', 10031, N'01 - Imagens/01 - Antes/8155.jpeg', N'Antes não havia tubulação, sendo um processo mais lento e mais perigoso ao colaborador, podendo causar danos físicos. ', N'01 - Imagens/02 - Depois/8155.jpeg', N'Agilizou processo de atividade evitando a necessidade de desacoplar tubulação, expondo colaborador a risco de projeção de material, eliminando possíveis eventos com colaborador em área.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'Antes não havia tubulação, sendo um processo mais lento e mais perigoso ao colaborador, podendo causar danos físicos, com a implantação da tubulação foi eliminado fatores de riscos a segurança do colaborador', N'Segurança em atividade de rotina ', 0, NULL, N'aumento satisfatório de vazão e resolução de problema.', '2026-02-17T00:00:00.000', '2026-02-18T02:47:47.000', 81032668, NULL, 2);
INSERT INTO #PVC VALUES (8156, 494528, 472367, N'Template tela geral da moagem ', NULL, N'Others/Outros', N'Durante operação da moagem de carvão há a necessidade de mudanças de tela no supervisório para o acompanhamento da temperatura do filtro de mangas.', N'visualizar a indicação de temperatura sem mudar de tela', 10160, N'01 - Imagens/01 - Antes/8156.jpeg', N'Para verificar a indicação de temperatura da tremonha do filtro de mangas, o operador precisava alternar de tela no supervisório, o que tornava o acompanhamento menos ágil e aumentava o tempo de resposta em situações de desvio.', N'01 - Imagens/02 - Depois/8156.jpeg', N'Foi realizada uma atualização na tela geral da moagem de carvão, incluindo agora a indicação de temperatura da tremonha do filtro de mangas diretamente na interface principal.
INSERT INTO #PVC VALUES (8157, 81022580, 81022580, N'Tela de proteção ', NULL, N'Others/Outros', N'Base da bomba suspensa sobre dormentes de madeiras com risco de tombamento e constantes obstruções na linha de sucção e recalque da bomba, devido quedas de materiais no foço da bomba.', N'Eliminar riscos ', 10031, N'01 - Imagens/01 - Antes/8157.jpeg', N'Base da bomba suspensa sobre dormentes de madeiras com risco de tombamento e constantes obstruções na linha de sucção e recalque da bomba, devido quedas de materiais no foço da bomba.', N'01 - Imagens/02 - Depois/8157.jpeg', N'Fabricado e instalado pé de fixação e tela de proteção na base da bomba de poço do espessador.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Com a fabricação e instalação da tela de proteção foi resolvido, eliminando riscos em relação a saúde do colaborador ', N'REDUÇÃO DE RISCOS EM ATIVIDADE DE ROTINA', 0, NULL, N'A instalação do guarda-corpo com rodapé eliminou o risco de queda na escada.', '2026-02-17T00:00:00.000', '2026-02-18T03:47:09.000', 81022580, NULL, 1);
INSERT INTO #PVC VALUES (8158, 81056513, 483385, N'Placa de alimentação', NULL, N'Others/Outros', N'Placa de alimentação digital 24 volts,estava dando curto na alimentação da placa danificando os periféricos eletrônicos, ocasionando várias paradas em corretiva.', N'PRODUTIVIDADE', 10324, N'01 - Imagens/01 - Antes/8158.jpeg', N'Placa de alimentação digital 24 volts, estava dando curto na alimentação da placa danificando os periféricos eletrônicos, ocasionando várias paradas em corretiva.', N'01 - Imagens/02 - Depois/8158.jpeg', N'Foi instalado um fusível de 5 A na linha de alimentação da placa digital, eliminando risco de curto na placa digital, e consequentemente paradas em corretiva.', NULL, N'Sim, maquina aumentou sua produtividade', N'Inspeção e identificação de falhas', 0, NULL, N'custo evitado/produtividade', '2026-02-16T00:00:00.000', '2026-02-18T08:53:24.000', 81056513, NULL, 1);
INSERT INTO #PVC VALUES (8159, 1008697, 81062445, N'Securement of tools', NULL, N'Others/Outros', N'Tools being stored in a bucket on the mezzanine, they go missing, potential to fall over the toe board.', N'Secure tools in the area and eliminate tools that are not required.', 0, N'01 - Imagens/01 - Antes/8159.jpeg', N'Tools for maintenance activities and pre-ops were being stored in a bucket.  Potential for dropped objects.', N'01 - Imagens/02 - Depois/8159.jpeg', N'Secured tape to the handrail using a tool lanyard.', NULL, N'Yes, the problem was resolved.', N'Need to plan this task better as the risk was overlooked.', 0, NULL, N'Com a implementação da nova forma de resfriamento, espera-se que o processo passe a ocorrer de maneira mais rápida, estável e segura para com todos os colegas.', '2026-02-17T00:00:00.000', '2026-02-18T09:50:25.000', 1008697, NULL, 1);
INSERT INTO #PVC VALUES (8160, 1008697, 81062445, N'Securing tools around the classifier', NULL, N'Others/Outros', N'Tools for pre-ops and maintenance activities were being stored in a bucket which have the potential for dropped objects.', N'Secure tools to prevent dropped objects.', 0, N'01 - Imagens/01 - Antes/8160.jpeg', N'Tools for pre-ops and maintenance activities were being stored in a bucket which have the potential for dropped objects.', N'01 - Imagens/02 - Depois/8160.jpeg', N'Secured a crescent wrench and scissors to the hand rail to prevent dropped object potential.', NULL, N'Yes, the problem was solved, the hazard was eliminated.', N'Need to be aware of the potential for dropped objects.', 0, NULL, N'COM A PLACA DE INDENTIFICAÇÃO DO FLUXO, FICA MELHOR PRO COLOBORADOR SABER QUAL FLUXO ESTA SENDO PREPARADO', '2026-02-17T00:00:00.000', '2026-02-18T10:06:59.000', 1008697, NULL, 1);
INSERT INTO #PVC VALUES (8161, 81056513, 81016955, N'BOMBA DE SUCÇÃO DE ÓLEO', NULL, N'Others/Outros', N'Logo após a instalação da ilha de lubrificação, havia uma lacunda no abastecimento dos reservatórios devido a alta demanda do comboio de lubrificação na Mina', N'Redução de tempo/produtividade', 10324, N'01 - Imagens/01 - Antes/8161.jpeg', N'Abastecimento dos reservatórios era realizado 100% pelos comboios de lubrificação. Onde havia demora e atraso devido alta demanda da Mina, gerando impactos na liberação dos equipamentos em preventiva', N'01 - Imagens/02 - Depois/8161.jpeg', N'Feito instalação da bomba para abastecimento dos reservatórios de óleo GEAR 150 e 220 para melhor atender os equipamentos em preventiva.', NULL, N'Redução da dependência dos comboios de lubrificação em ate 50%', N'produtividade', 0, NULL, N'Less time is spent by the crews to look for equipment. ', '2026-02-17T00:00:00.000', '2026-02-18T10:16:08.000', 81056513, NULL, 1);
INSERT INTO #PVC VALUES (8162, 81031229, 81031229, N'Band Saw Entry Roller Upgrade', NULL, N'Refining/Refino', N'Pipe stands with roller tops had been accepted as a sufficient means of supporting steel materials as they were fed into the horizontal band saw. this 3 point contact that the stands had on the floor were not ideal. We needed a more secure way of supporting material, something that was able to be fastened to the ground to prevent a tipping hazard.', N'To create a safer means of supporting material', 10193, N'01 - Imagens/01 - Antes/8162.jpeg', N'As you can see, these stands worked. They served their purpose. It was time for an upgrade to ensure that we move forward with implementing best practices on site which not only improves safety, but also supports a more effective means of completing tasks with the use of proper tools.', N'01 - Imagens/02 - Depois/8162.jpeg', N'Cobalt operations funded the entry roller improvement. Now, as you can see, we have the proper roller conveyors in place. The stands are fastened to the ground to prevent toppling of material. Material can be lowered onto the conveyors safely with the use of the shop crane. These rollers are completely removeable. There are flip down wheels to aid with moving these conveyors. I have updated the training package for the shear that you see in the picture to reflect the removeable conveyors stating user shall remove conveyors when using shear frequently or for large material drops. We made guide pins to prevent material from rolling off of the conveyor.', NULL, N'Problem solved.', N'Little by little we strive to improve safety.', 0, NULL, N'Maintaining safety shower system cleanliness and operating performance.', '2026-02-02T00:00:00.000', '2026-02-18T12:47:53.000', 81031229, NULL, 1);
INSERT INTO #PVC VALUES (8163, 81006667, 81006667, N'Painel Power BI – Ações da Operação de Usina', NULL, N'No Replication/Sem replicação', N'Os relatórios de ações eram copilados de modo manual, no qual tinha que extrair 4 planilhas do sistema, realizar os tratamento das planilhas e copiar as informações para uma planilha Base.', N'Automação de acompanhamento de ações', 10054, N'01 - Imagens/01 - Antes/8163.jpeg', N'Antes para poder copilar as ações da gerência tinha extrair 4 relatórios diferentes, entrar na base de cada um deles copiar e colar as colunas que precisava das informações e colocar essas informações em um Excel, identificando de qual relatório aquela ação pertence, colocando qual turma é responsável pela ação, nos relatório que são extraído não tem a informação de qual turma é o responsável pela ação, também era feita uma tabela para saber a quantidade de ações por turma.', N'01 - Imagens/02 - Depois/8163.jpeg', N'As ações passaram a ser consolidadas automaticamente em um único painel em Power BI, alimentado por uma base padronizada.  Redução significativa de tempo para preparar o status da gerência, padronização das informações e melhor visibilidade das ações no prazo vs. vencidas.', NULL, N'Ter uma visão única e interna de todas as ações, com filtros por responsável, mês, tipo e status.', N'Importância de padronização da base', 0, NULL, N'Effective searching', '2026-02-17T00:00:00.000', '2026-02-18T13:04:36.000', 81006667, NULL, 1);
INSERT INTO #PVC VALUES (8164, 1008697, 81013112, N'Strapping loading ramp', NULL, N'Others/Outros', N'During winter operation the loading ramp sometimes slips out of the container when you are backing out.', N'Make the task more safe', 0, N'01 - Imagens/01 - Antes/8164.jpeg', N'While loading sea cans in the winter the loading ramp sometimes falls out of the container due to icy conditions.', N'01 - Imagens/02 - Depois/8164.jpeg', N'Attached a strap on the inside of the sea can to the ramp to prevent if from slipping out.', NULL, N'Problem has been resolved.', N'Requirement to fasten the ramp to prevent potential for injury', 0, NULL, N'Safety enhancement', '2026-02-17T00:00:00.000', '2026-02-18T13:42:17.000', 1008697, NULL, 1);
INSERT INTO #PVC VALUES (8165, 1008697, 81013112, N'Signage modification for the kiln discharge chute', NULL, N'No Replication/Sem replicação', N'The access point for the discharge chute is mainly from one direction, as you approach you could potentially miss the caution signage for the temperature of the rounds.', N'Have signage properly orientated for the hazard.', 0, N'01 - Imagens/01 - Antes/8165.jpeg', N'The access point for the discharge chute is mainly from one direction, as you approach you could potentially miss the caution signage for the temperature of the rounds.', N'01 - Imagens/02 - Depois/8165.jpeg', N'Changed the orientation of the sign to make it visible for individuals working in that area. ', NULL, N'Problem has been resolved and the goal has been achieved.', N'Need better hazard awareness and situational awareness.', 0, NULL, N'Proporcionou maior segurança, melhor ergonomia e reduzindo o risco de quedas durante a atividade.', '2026-02-17T00:00:00.000', '2026-02-18T13:51:58.000', 1008697, NULL, 1);
INSERT INTO #PVC VALUES (8166, 81006667, 81006667, N'Painel Power BI – Treinamentos da Gerência', NULL, N'No Replication/Sem replicação', N'O controle de treinamentos era feito em uma planilha  extraída do sistema formato csv. Para saber quais colaboradores estavam com treinamentos vencidos ou a vencer, era necessário filtrar manualmente e cruzar informações.', N'Realizar Gestão de Treinamentos', 10054, N'01 - Imagens/01 - Antes/8166.jpeg', N'O controle de treinamentos era feito em uma planilha  extraída do sistema formato csv. Para saber quais colaboradores estavam com treinamentos vencidos ou a vencer, era necessário filtrar manualmente e cruzar informações. Não existia uma visão consolidada por turma, tipo de treinamento ou status. Faltava um indicador claro e automático de adesão aos treinamentos por turma, dificultando o acompanhamento e a priorização.', N'01 - Imagens/02 - Depois/8166.jpeg', N'Com a criação do Painel de Treinamentos, todo o processo passou a ser automatizado e visual. A extração do CSV deixou de ser tratada manualmente e passou a alimentar um modelo de dados estruturado, que gera automaticamente todos os indicadores necessários para o acompanhamento da gerência.
INSERT INTO #PVC VALUES (8167, 1008697, 81013112, N'Co slab picture identification by lot and crate', NULL, N'Others/Outros', N'Previously, we would put tops on the crates and not clearly identify which crate was which.  Then when a customer would want pictures, we would have to take the cover off and send out pictures.', N'Properly identify crates with associated pictures to prevent having to remove the cover at a later time.', 0, N'01 - Imagens/01 - Antes/8167.jpeg', N'Previously there was no naming convention for each crate of cobalt slab that was produced.  When a customer would want pictures, we would have to remove the cover, take a picture and send it to the customer.', N'01 - Imagens/02 - Depois/8167.jpeg', N'Implemented a proper way to name each crate associated with letters and lot numbers.  Pictures are associated the same way and stored to make it easier to send customers pictures when requested.', NULL, N'Goal has been achieved as pictures of each crate along with proper identification are now stored online.  There is no longer a need to go take pictures at the time a customer requests them.', N'Labeling crates at the time of production and associating that label reduces work in the future.', 0, NULL, N' ACIDENTES EVITADOS', '2026-02-17T00:00:00.000', '2026-02-18T14:07:57.000', 1008697, NULL, 1);
INSERT INTO #PVC VALUES (8168, 81033365, 81048572, N'suporte do filtro', NULL, N'Others/Outros', N'ausência de suporte', N'melhoria de processo', 10139, N'01 - Imagens/01 - Antes/8168.jpeg', N'Foi identificado que o filtro de óleo apresentava implosão é o colapso estrutural devido ausência do elemento de fixação, com isso gerando impacto na vazão do bico leve. ', N'01 - Imagens/02 - Depois/8168.jpeg', N'Foi realizado a confecção de um suporte de fixação para o filtro, com isso garantindo o posicionamento correto e eliminando o impacto na vazão do bico leve.', NULL, N'aumento satisfatório de vazão e resolução de problema.', N'comprometimento com processo', 0, NULL, N'Reduzir o desperdício de papel.', '2026-02-16T00:00:00.000', '2026-02-18T14:24:13.000', 81033365, NULL, 1);
INSERT INTO #PVC VALUES (8169, 81006670, 81013460, N'QR CODE Registro de Ideias de Kaizen.', NULL, N'Others/Outros', N'Colaboradores sem domínio do link principal de registro de kaizen', N'Acesso rápido e fácil do ponto focal para registrar kaizens', 10144, N'01 - Imagens/01 - Antes/8169.jpeg', N'Antes não tínhamos uma ferramenta para cadastrar as ideias de Kaizen da Supervisão. Pois tem a ideia, mais ainda falta alguns pontos pra finalizar o mesmo. Então foi criado um FORMS para apoia os colaboradores com suas ideias e posterior registro oficial na plataforma do KAIZEN.', N'01 - Imagens/02 - Depois/8169.jpeg', N'Foi criado um FORMS aonde o colaborador irá inserir sua ideia de KAIZEN e no decorrer o do tempo caso não tenha terminado, o colaborador irá fazendo seu KAIZEN e assim que finalizar, o mesmo poderá ser registrado na plataforma oficial do KAIZEN.
INSERT INTO #PVC VALUES (8170, 486474, 515035, N'GUARDA-CORPO', NULL, N'Open Pit/Poço aberto', N'Escada de acesso à copa sem instalação de guarda-corpo, apresentando risco potencial de queda de pessoas durante o uso.', N'AUMENTAR A SEGURANÇA DOS USUARIOS DA ESCADA.', 10140, N'01 - Imagens/01 - Antes/8170.jpeg', N'Escada de acesso à copa sem instalação de guarda-corpo, apresentando risco potencial de queda de pessoas durante o uso.', N'01 - Imagens/02 - Depois/8170.jpeg', N'Foi confeccionado e instalado um guarda-corpo conforme as normas de segurança vigentes, incluindo rodapé de proteção, visando aumentar a segurança dos usuários durante o acesso à copa.', NULL, N'A instalação do guarda-corpo com rodapé eliminou o risco de queda na escada, reforçando a importância das inspeções preventivas e do cumprimento das normas de segurança.', N'A instalação do guarda-corpo com rodapé eliminou o risco de queda na escada.', 0, NULL, N'A implementação de um arquivo único e consolidado para registro das etapas da parada eliminou a necessidade de criação de diversas apresentações ao longo do tempo. Todos os avanços passaram a ser atualizados diretamente no mesmo arquivo, de forma contínua e padronizada.
INSERT INTO #PVC VALUES (8171, 81033365, 81048572, N'suporte da sirene de ré', NULL, N'Projects/Projetos', N'retrabalho e custo ', N'melhoria continua', 10139, N'01 - Imagens/01 - Antes/8171.jpeg', N'Foi identificado um alto índice de desgaste estrutural na sirene de ré, ocasionado pela projeção blocos.', N'01 - Imagens/02 - Depois/8171.jpeg', N'Foi realizado a confecção de uma proteção da sirene de ré, garantido a integridade física do componente. ', NULL, N'custo evitado/produtividade', N'custo evitado', 0, NULL, N'Better awareness that throwing the disconnect can affect other operating systems & allow time to prepare.', '2026-02-17T00:00:00.000', '2026-02-18T14:53:12.000', 81033365, NULL, 1);
INSERT INTO #PVC VALUES (8172, 81007797, 81007797, N'RESFRIAMENTE DE ÁGUA PARA A CONFECÇÃO DE SOLUÇÕES', NULL, N'Others/Outros', N'TINHAMOS QUE ESPERAR UM LONGO PERÍODO DE TEMPO PARA QUE A SOLUÇÃO PODESSE ESFRIAR A CADA VOLUME DE ÁCIDO COLOCADO DENTRO DO BALÃO COM ÁGUA.', N'FAZER AS SOLUÇÕES COM MENOS TEMPO, E MAIS SEGURANÇA.', 10235, N'01 - Imagens/01 - Antes/8172.jpeg', N'O PROCESSO ERA DEMORADO POIS A SOLUÇÃO DEMORAVA MUITO PARA SE ESFRIAR, MESMO COM O BALÃO ENVOLVIDO COM ÁGUA PARA O RESFRIAMENTO, E NOS TOMAVA BASTANTE TEMPO EM ESPERA, E NÃO ERA TOTALMENTE SEGURO.', N'01 - Imagens/02 - Depois/8172.jpeg', N'Após a mudança, o processo tornou-se significativamente mais rápido e seguro. A solução passou a atingir a temperatura adequada em um tempo muito menor, eliminando longos períodos de espera e aumentando a produtividade da rotina, o novo método proporcionou maior controle térmico, reduzindo riscos de manuseio e evitando exposição desnecessária dos colaboradores a recipientes quentes, padronização do método,  mais eficiente, garantindo mais segurança operacional no laboratório.', NULL, N'Agilidade no processo e segurança na confecção de soluções que podem esquentar no processo. Foi resolvido com  muita praticidade e responsabilidade.', N'Melhoria contínua e agilidade de segurança no método.', 0, NULL, N'SIM CONCLUINDO INSTALADO DUAS TRAVAS', '2026-02-10T00:00:00.000', '2026-02-18T15:40:33.000', 81007797, NULL, 3);
INSERT INTO #PVC VALUES (8173, 81057862, 81057862, N'MELHORIA NA INDENTIFICAÇÃO DO FLUXO', NULL, N'Others/Outros', N'Dificuldade para identificar rapidamente o reagente correto durante a operação.', N'MELHORIA NA VISUALIZAÇÃO DA INDENTIFICAÇÃO', 10235, N'01 - Imagens/01 - Antes/8173.jpeg', N'Dificuldade para identificar rapidamente o reagente correto durante a operação.', N'01 - Imagens/02 - Depois/8173.jpeg', N'COM A PLACA DE INDENTIFICAÇÃO DO FLUXO, FICA MELHOR PRO COLOBORADOR SABER QUAL FLUXO ESTA SENDO PREPARADO', NULL, N'SIM', N'MELHOR VISUALIZAÇÃO', 0, NULL, NULL, '2026-02-17T00:00:00.000', '2026-02-18T16:11:36.000', 81057862, NULL, 3);
INSERT INTO #PVC VALUES (8174, 300837, 300837, N'Equipment Location Automated Emails', NULL, N'Underground/Subterrâneo', N'Supervisors do not always know the location of every piece of equipment underground, especially when making the plan for their day. ', N'Auto-Email Supervisors Underground Equipment Locations', 10287, N'01 - Imagens/01 - Antes/8174.jpeg', N'Locations for equipment are displayed on PI Vision in the Warm room at Creighton Mine. ', N'01 - Imagens/02 - Depois/8174.jpeg', N'An email is sent out automatically to all supervisors at Creighton Mine 3 times daily. A supervisor can use this information to plan their day. They can print this report and carry it with them for easy access during the shift or look at their email and reference the sent out .pdf. ', NULL, N'Yes, the supervisors now have a quick reference to show underground equipment location. ', N'Simple is better. Digital solutions are sometimes not ideal for underground applications. ', 0, NULL, N'Safer work envrionment.', '2026-02-06T00:00:00.000', '2026-02-18T16:55:42.000', 300837, NULL, 1);
INSERT INTO #PVC VALUES (8175, 608046, 81062199, N'PMR-Safety Shower System Upgrades', NULL, N'Others/Outros', N'Old Safety Shower System Hot Water Storage tank was dated, required maintenance and repairs to maintain safety standards and ongoing demands of system performance.', N'New Hot Water Storage Tanks/Piping/Pump Upgrades', 10193, N'01 - Imagens/01 - Antes/8175.jpeg', N'Old Safety shower tank/components dated and required ongoing upgrades to maintain-safety standards.', N'01 - Imagens/02 - Depois/8175.jpeg', N'New Safety Shower System Plan was designed w/Engineering Department, system upgrade was implemented and transitioned over a period of time-components were tested and verified-system was commissioned and transferred over. To include 4-new 120gal hot water tanks/piping/recirculating pumps to maintain required system pressures/temperatures.', NULL, N'Planned, designed, and Implemented asset management-required maintenance system upgrades.', N'System Assets, maintaining level of safety standards.', 0, NULL, N'New unit is much more efficient and effective for what is required.', '2026-02-17T00:00:00.000', '2026-02-18T17:03:48.000', 608046, NULL, 1);
INSERT INTO #PVC VALUES (8176, 81009995, 81009995, N'Search Engine Inventory System', NULL, N'Others/Outros', N'There is no way to search for individual products within the new NIPPS inventory system', N'Add a search engine within the new inventory system', 10255, N'01 - Imagens/01 - Antes/8176.jpeg', N'No heading to search for inventory ', N'01 - Imagens/02 - Depois/8176.jpeg', N'Added a new header to allow for inventory lookup', NULL, N'Effective search engine built into the webpage', N'New items still coming up from our rollout of our inventory system', 0, NULL, N'Increase in Team Efficiency, Team Members are more satisfied as they are ''working'' their plan, Improvement in Work Quality.', '2026-02-17T00:00:00.000', '2026-02-18T20:20:46.000', 81009995, NULL, 1);
INSERT INTO #PVC VALUES (8177, 81009995, 81009995, N'Updated Pipping Systems on Sink', NULL, N'Others/Outros', N'Leaky pipes causing safety concern within the plant from running water', N'Improve Safety', 10255, N'01 - Imagens/01 - Antes/8177.jpeg', N'There was a leaking pipe that was causing a slipping hazard running into the plant', N'01 - Imagens/02 - Depois/8177.jpeg', N'Changed the pipe to stop leaking onto plant floor', NULL, N'No more leaking water onto the floor', N'Fixed leaking pipes', 0, NULL, N'O sensor deixe de travar durante a operação', '2026-02-17T00:00:00.000', '2026-02-18T20:33:52.000', 81009995, NULL, 1);
INSERT INTO #PVC VALUES (8178, 123307, 81043245, N'Acesso Fácil ', NULL, N'Others/Outros', N'Durante a inspeção no refugo do moinho de bolas 2251 MO 02, foi identificado que o operador precisava subir na estrutura do equipamento para realizar a atividade( corrimão), ficando exposto a risco de quedas, tropeços e condições ergonômicas inadequadas.', N'Eliminar riscos de quedas e ergonômicos. ', 10054, N'01 - Imagens/01 - Antes/8178.jpeg', N'Durante a inspeção no refugo do moinho de bolas 2251 MO 02, foi identificado que o operador precisava subir na estrutura do equipamento para realizar a atividade( corrimão), ficando exposto a risco de quedas, tropeços e condições ergonômicas inadequadas.', N'01 - Imagens/02 - Depois/8178.jpeg', N'Foi confeccionada uma escada móvel para facilitar a visualização e inspeção do refugo do Moinho de Bolas 2251 MO 02, proporcionando maior segurança, melhor ergonomia e reduzindo o risco de quedas durante a atividade', NULL, N'Sim, confeccionado acesso seguro para visualização do refugo do moinho.', N'Ver e Agir', 0, NULL, N'A solução pode ser aplicada em:
INSERT INTO #PVC VALUES (8179, 81057525, 81057515, N'MELHORIA NA INDENTIFICAÇAO DE  DESCARTES NAS AMOSTRAS DE MINA', NULL, N'Others/Outros', N'DIFICULTAVA BASTANTE NA HORA DE INDENTIFICAR AS AMOSTRAS QUE JA ESTAVAM NO PERIODO DO DESCARTES.', N'NOSSA META E REDUZIR O MAXIMO DE TEMPO  NA HORA DE DESCARTAR AS AMOSTRAS', 10235, N'01 - Imagens/01 - Antes/8179.jpeg', N'DIFICULTAVA BASTANTE NA HORA DE INDENTIFICAR AS AMOSTRAS QUE JA ESTAVAM NO PERIODO DO DESCARTES.', N'01 - Imagens/02 - Depois/8179.jpeg', N'FOI COLOCADO PLACAS DE INDENTIFICAÇOES, COM NUMERAÇAO DAS AMOSTRAS, DATA QUE FOI ARQUIVADAS E DATA DO DESCARTES, PARA FACILITAR A INDENTIFICAÇAO NA HORA DO DESCARTES.', NULL, N'SIM,FOI COLOCADO PLACAS DE INDENTIFICAÇOES, COM NUMERAÇAO DAS AMOSTRAS, DATA QUE FOI ARQUIVADAS E DATA DO DESCARTES, PARA FACILITAR A INDENTIFICAÇAO NA HORA DO DESCARTES.', N'SIM', 0, NULL, N'MELHORIA EM SEGURANÇA FISICA E AMBIENTAL', '2026-02-18T00:00:00.000', '2026-02-19T04:53:37.000', 81057525, NULL, 3);
INSERT INTO #PVC VALUES (8180, 537728, 537728, N'PORTÃO DE ACESSO AO PISO INTERMEDIÁRIO', NULL, N'Others/Outros', N'ACESSO INDEVIDO DE PESSOAS AO PISO INTERMEDIARIO EMQUANTO O EQUIPAMENTO ESTA EM OPERAÇÃO O PODE CAUSAR RISCOS AOS TRANSEUNTES.', N'REDUÇÃO DE RISCOS', 10362, N'01 - Imagens/01 - Antes/8180.jpeg', N'ÁREA ABERTA, O QUE POSSSIBILITAVA AS PESSOAS NÃO AUTORIZADAS ACESSAREM O PISO INTERMEDIÁRIO EMQUANTO O EQUIPAMENTO ESTAVA EM OPERAÇÃO,VINDO A TRAZER UM RISCO EMINENTE VISTO QUE A ÁREA É COMPOSTA DE VARIAS ENERGIAS, ENTRE ELAS MECÂNICA, HIDRÁULICA E PNEUMÁTICA ', N'01 - Imagens/02 - Depois/8180.jpeg', N'FOI CONFECCIONADO UM PORTÃO DE ACESSO AO PISO INTERMEDIÁRIO, O MESMO IMPEDIRÁ O ACESSO DE PESSOAS NÃO AUTORIZADAS A ÁREA DE OPERÇÃO DE AMBOS OS FILTROS DA FILTRAGEM.', NULL, N'SIM. FOI CONFECCIONADO UM PORTÃO DE ACESSO AO PISO INTERMEDIÁRIO, O MESMO IMPEDIRAR O ACESSO DE PESSOAS NÃO AUTORIZADAS A ÁREA DE OPERÇÃO DE AMBOS OS FILTROS DA FILTRAGEM.', N'ÁREA COM GRANDE POTENCIAL DE RISCOS DEVEM TER CONTROLE DE ACESSOS', 0, NULL, N'Seguimos com sentimento de dono, promovendo melhorias continuidades do nosso processo.', '2026-01-21T00:00:00.000', '2026-02-19T06:09:49.000', 537728, NULL, 1);
INSERT INTO #PVC VALUES (8181, 81059060, 506314, N'Checklist de Neutralização dos LG´s', NULL, N'No Replication/Sem replicação', N'Para realizar o checklist de neutralização dos LGs, as informações eram anotadas em folhas soltas como rascunho. Isso gerava desperdício de papel, risco de perda de dados.', N'reduzir o desperdício de papel', 10366, N'01 - Imagens/01 - Antes/8181.jpeg', N'Para realizar o checklist de neutralização dos LGs, as informações eram anotadas em folhas soltas como rascunho. Isso gerava desperdício de papel e risco de perda de dados.', N'01 - Imagens/02 - Depois/8181.jpeg', N'Foi criado um anexo plastificado para registrar as informações diretamente no local da atividade. Com isso, as anotações ficaram mais organizadas, reduziu o risco de perder dados e eliminou o uso de folhas descartáveis. A melhoria trouxe mais agilidade no processo e menos desperdício de papel. Após as informações serem coletadas, é passado para o relatório e o anexo usado novamente.', NULL, N'O problema foi solucionado com a criação do anexo plastificado.', N'Pequenas melhorias podem gerar impactos positivos para melhorar a sustentabilidade.', 0, NULL, N'SEGURANÇA', '2026-02-18T00:00:00.000', '2026-02-19T06:40:39.000', 81059060, NULL, 2);
INSERT INTO #PVC VALUES (8182, 211441, 211441, N'Otimização de Custos e Performance dos Caminhões 830E e 930E por Meio da Diálise de Óleo na Roda Motorizada', NULL, N'No Replication/Sem replicação', N'As rodas motorizadas (Motor Wheel) dos caminhões 830E e 930E apresentam degradação prematura do óleo lubrificante, causada principalmente por contaminação por partículas metálicas, umidade e degradação térmica.
INSERT INTO #PVC VALUES (8183, 520046, 81038977, N'Criação de Timeline em PowerPoint para Consolidação e Acompanhamento das Etapas da Parada Geral do Sossego', NULL, N'Others/Outros', N'As informações relacionadas às etapas da parada geral do Sossego estavam distribuídas em diferentes documentos, apresentações e controles, sem uma visão cronológica única que demonstrasse claramente tudo o que já foi executado até o momento.
INSERT INTO #PVC VALUES (8184, 81013119, 81013119, N'Print room E-Stop Label', NULL, N'Refining/Refino', N'Local disconnect in print room has no warning that when switched to off position it causes an emergency stop in all system 200.   ', N'To clearly identify disconnect switch as an E stop', 0, N'01 - Imagens/01 - Antes/8184.jpeg', N'Local disconnect in print room has no warning that when switched to off position it causes an emergency stop in all system 200.  This causes the system to abruptly stop without warning which makes it difficult when trying to restart resulting in unnecessary down time.', N'01 - Imagens/02 - Depois/8184.jpeg', N'Installed Label to identify disconnect switch as an E-stop.', NULL, N'Yes', N'Proper labelling is important for E-stops. ', 0, NULL, N'segurança, agilidade e conforto durante as atividades.', '2026-02-18T00:00:00.000', '2026-02-19T11:20:20.000', 81013119, NULL, 1);
INSERT INTO #PVC VALUES (8185, 81020607, 81013310, N'TRAVA DO PORTICO ', NULL, N'Others/Outros', N'AUSENCIA DE UMAS DAS TRAVAS OUTRA QUEBRADA', N'SEGURANÇA', 10139, N'01 - Imagens/01 - Antes/8185.jpeg', N'AUSENCIA DE UMAS DAS TRAVAS OUTRA QUEBRADA', N'01 - Imagens/02 - Depois/8185.jpeg', N'APLICADOS DUAS TRAVAS', NULL, N'SIM CONCLUINDO INSTALADO DUAS TRAVAS', N'MELHORIA', 0, NULL, N'padronização, eliminação de risco', '2026-02-15T00:00:00.000', '2026-02-19T13:28:08.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8186, 81043460, 81043460, N'Centering Comb Upgrades', NULL, N'Others/Outros', N'Edge growth has been an issue and causing damage to the centering combs, mandrels and other crane components.', N'Eliminate damage', 0, N'01 - Imagens/01 - Antes/8186.jpeg', N'The old centering combs had much less of a distinctive gap, causing even smaller amounts of edge growth to get caught up, damaging the cranes components as well as damaging the ink on the mandrels and sometimes ultimately folding mandrels in half due to the hydraulic pressure.', N'01 - Imagens/02 - Depois/8186.jpeg', N'New centering combs have a much deeper gap, allowing a considerable amount of edge growth pass through without causing any damage to the crane or the mandrels.', NULL, N'Yes', N'Wider gaps helped to reduce damage. ', 20000, 3, N'5S SATISFATORIA PARA A AREA LIMPA ORGANIZADA E COM SEGURANÇA.', '2026-01-02T00:00:00.000', '2026-02-19T14:30:57.000', 81043460, NULL, 1);
INSERT INTO #PVC VALUES (8187, 81043460, 81043460, N'Maintenance crane wheels need to be covered', NULL, N'Others/Outros', N'Both maintenance cranes have their trolley wheels opened which poses a threat to safety of the operators as well as potential for equipment and materials to be damaged.', N'Cover the wheels', 0, N'01 - Imagens/01 - Antes/8187.jpeg', N'Old wheel is open and unprotected. The leaves it open for materials to be ran over causing damage to them or stalling the wheels. There is also potential an operator could become in the line of fire or inadvertently position their hands in harms way.', N'01 - Imagens/02 - Depois/8187.jpeg', N'New wheel cover eliminates the chance for materials falling in between the wheel and the track, as well as providing a line of defense for operators working on the trolley.', NULL, N'Yes', N'Still improvements being found after 12+ years.', 0, NULL, N'* Economia de material (operação do sistema com apenas 02 bombas)
INSERT INTO #PVC VALUES (8188, 81043460, 81043460, N'Harvesting Crane 2 HVAC Upgrade', NULL, N'Projects/Projetos', N'Old HVAC system on the east harvesting crane was unreliable and had multiple parts failing. These units only lasted a couple of years and are quite costly to replace as a whole. We needed to find a more suitable solution.', N'Increase reliability and reduce cost', 0, N'01 - Imagens/01 - Antes/8188.jpeg', N'Old HVAC unit had many moving parts that ultimatley fail, as well as unreilable condensers, motors etc. The unit as a whole has been replaced a number of times of the years and is quite costly and hard to work on.', N'01 - Imagens/02 - Depois/8188.jpeg', N'New HVAC system utilizes a commercial ducted mini split, reusing the cranes existing ductwork. There are much less moving parts that would require maintenance and in the event of a failure it is much more accessible to work on and the parts are cheaper and readily available.', NULL, N'Yes, the old units cost 160Kusd, our newly installed system cost less than 10k. We have the system coated to prevent corrosion, as well as updated handrails in the area. This unit doesnt require and AWP to be worked on which will save time and resources maintaining this equipment.', N'Better options out there, we dont always need to rely on OEM', 200000, 3, N'Melhoria de segurança, eficiência operacional, redução do esforço físico, aumento de produção e melhoria de processo.', '2026-02-05T00:00:00.000', '2026-02-19T14:51:07.000', 81043460, NULL, 1);
INSERT INTO #PVC VALUES (8189, 200936, 200936, N'Implement Scaled Agile Methodology', NULL, N'Projects/Projetos', N'Unorganized Action Item List featuring over 205 items needed to be prioritized by a group of over 30 Project Stakeholders.', N'Team to Agree and Prioritize Work for next 3 months.', 10238, N'01 - Imagens/01 - Antes/8189.jpeg', N'Original Plan
INSERT INTO #PVC VALUES (8190, 81044534, 964502, N'Melhoria na portinhola de LSH 0021 do AL-2303SA-01', NULL, N'Others/Outros', N'Antes, havia travamento e não atuava  o LSH.', N'Evitar travamento e quebra do sensor.', 10229, N'01 - Imagens/01 - Antes/8190.jpeg', N'Anteriormente, o AL‑2303SA‑01 apresentava travamento na portinhola, impedindo o acionamento do sensor LSH. Essa falha ocasionava elevação excessiva do chute de descarga do AL‑2303SA‑01 durante o processo.', N'01 - Imagens/02 - Depois/8190.jpeg', N'Foi realizada uma melhoria na portinhola do LSH, adicionando-se uma abertura lateral. Essa modificação garante que, ao abrir a portinhola, o sensor não permaneça travado, eliminando falhas de atuação e melhorando a confiabilidade do processo.', NULL, N'sim', N'modificações mecânicas podem eliminar falhas recorrentes', 0, NULL, N'A solução pode ser aplicada em:
INSERT INTO #PVC VALUES (8191, 81026611, 547627, N'Carregador Solar Portátil para Reutilização de Baterias', NULL, N'No Replication/Sem replicação', N'As baterias descarregadas eram descartadas sem teste ou tentativa de recuperação, pois não havia sistema de recarga ou infraestrutura elétrica em campo. Isso gerava alto custo com novas baterias, desperdício ambiental, acúmulo de resíduos perigosos e aumento da logística interna.
INSERT INTO #PVC VALUES (8192, 81016188, 81049527, N'Instalação da conexão macho ISO A', NULL, N'No Replication/Sem replicação', N'DEFEITO', N'Com essa melhoria podemos abastecer o caminhão com maio agilidade é evitando contaminação do óleo graças a conexão ISO A  .', 10031, N'01 - Imagens/01 - Antes/8192.jpeg', N'Antes as conexões ISO A de sucção do caminhão comboio estavam  incompletas ,tendo apenas a parte fêmea da conexão, ausência de mangueiras, impossibilitado o abastecimento dos reservatórios de óleo do caminhão comboio', N'01 - Imagens/02 - Depois/8192.jpeg', N'Feita a instalação da conexão macho ISO A , e instalação da mangueira na sucção do reservatório de óleo , assim possibilitando o abastecimento de óleo dos reservatórios.
INSERT INTO #PVC VALUES (8193, 81016188, 81058747, N'sistema de transferência composto por tubo, conexões e ponto com filtro', NULL, N'No Replication/Sem replicação', N'Antes:
INSERT INTO #PVC VALUES (8194, 81016188, 518840, N' adaptação e instalação de um trocador de calor ', NULL, N'No Replication/Sem replicação', N'O trocador de calor da unidade hidráulica apresentava rompimento das colmeias
INSERT INTO #PVC VALUES (8195, 81016188, 81036019, N'protetor de pino graxeiro', NULL, N'No Replication/Sem replicação', N'podendo causar contaminação por particulas de poeira e água.', N'SEGURANÇA', 10031, N'01 - Imagens/01 - Antes/8195.jpeg', N'Antes mangueiras de lubrificação do AL2305SA-04 encontrava-se sem protetor de pino graxeiro podendo causar contaminação por partículas de poeira e água.', N'01 - Imagens/02 - Depois/8195.jpeg', N'Depois foi aplicado protetor de pino graxeiro das mangueiras de lubrificação do tambor do  AL2305SA-04 evitando a contaminação da graxa por particulas de poeira e água', NULL, N'MELHORIA NO PROCESSO', N'MELHORIA NO PROCESSO', 0, NULL, N'Consistency in data and visibility of Key Performance Indicators. ', '2026-02-13T00:00:00.000', '2026-02-19T20:57:19.000', 81016188, NULL, 2);
INSERT INTO #PVC VALUES (8196, 81029922, 81047727, N'MELHORIA NOS ESTRIBOS', NULL, N'Others/Outros', N'INPACTO NA ESTRUTURA FAZENDO OS ESTRIBOS AMASSAR', N'EVITAR DANOS A ESTRUTURA', 10139, N'01 - Imagens/01 - Antes/8196.jpeg', N' “O componente está sendo danificado devido ao impacto na estrutura, fazendo com que os estribos sejam amassados e, consequentemente, impedindo o acesso à cabine.”', N'01 - Imagens/02 - Depois/8196.jpeg', N'“Foram desamassados e instalado o suporte central nos estribos, corrigindo o problema para evitar que o dano ocorra novamente.”', NULL, N'“Foram desamassados e instalado o suporte central nos estribos, corrigindo o problema para evitar que o dano ocorra novamente.”', N'MELHORIA CONTINUA ', 0, NULL, N'Redução significativa do tempo de remoção do filtro secador.', '2026-02-15T00:00:00.000', '2026-02-20T00:02:54.000', 81029922, NULL, 1);
INSERT INTO #PVC VALUES (8197, 81050085, 81050085, N'Iluminação adequada', NULL, N'No Replication/Sem replicação', N'Foi constatado deficiência na iluminação da filtragem F01,dificultando a visibilidade dos operadores e ocasionando risco causados pela deficiência da iluminação:
INSERT INTO #PVC VALUES (8198, 81050085, 81050085, N'Acesso Seguro', NULL, N'Others/Outros', N'Acesso com desnível, ausência de sinalização adequada na transição entre níveis, com risco de queda, tropeço, risco ergonômico(devido esforço inadequado ao subir/descer sem apoio)dificuldade de percepção do degrau, principalmente a noite. ', N'adequação e padronização', 10044, N'01 - Imagens/01 - Antes/8198.jpeg', N'Acesso com desnível, ausência de sinalização adequada na transição entre níveis, com risco de queda, tropeço, risco ergonômico(devido esforço inadequado ao subir/descer sem apoio)dificuldade de percepção do degrau, principalmente a noite. ', N'01 - Imagens/02 - Depois/8198.jpeg', N'Foi confeccionado uma escada trazendo ganhos importantes para segurança e organização da área. Proporcionando uma transição segura e estável, eliminando os risco de torção e queda de mesmo nível facilitando a visualização mesmo em períodos noturno. E fortalece nossa cultura prevencionista.', NULL, N'sim! Melhoria eliminou os risco ', N'Eliminação de riscos', 2, 1, N'Agilidade na analise e prevenção de falhas  ', '2026-02-19T00:00:00.000', '2026-02-20T06:11:49.000', 81050085, NULL, 3);
INSERT INTO #PVC VALUES (8199, 81044760, 472988, N'5s baia de gás', NULL, N'Others/Outros', N'vizualmente sem organização.', N'organização vizual', 10031, N'01 - Imagens/01 - Antes/8199.jpeg', N'ANTES VIZULMENTE SEM ORGANIZAÇÃO E AUSENCIA DE ALGUMAS IDENTIFICAÇÕES.', N'01 - Imagens/02 - Depois/8199.jpeg', N'5S ORGANIZAÇÃO VIZUAL E AS PLACAS DE IDENTIFICAÇÃO CORRETAS.', NULL, N'UMA MELHOR VIZUALIZAÇÃO E IDENTIFICAÇÃO E RECONHECIMENTO DE MATERIAL DEVIDAMENTE SEGUROS.', N'5S DE ORGANIZAÇÃO DEVIDAMENTE CORRETO.', 0, NULL, NULL, '2026-01-21T00:00:00.000', '2026-02-20T08:45:34.000', 81044760, NULL, 2);
INSERT INTO #PVC VALUES (8200, 839373, 839373, N'Layout tubulação castelinho', NULL, N'Others/Outros', N'Transbordo de material da caixa 1 (castelinho) ', N'Eliminar o transbordo de água na caixa 1 (castelinho)', 10362, N'01 - Imagens/01 - Antes/8200.jpeg', N'Tubulação das bombas da caixa 1 (castelinho) com várias curvas (07 total), gerando perda de carga e como consequência o transbordo de material devido a ineficiência das bombas (2451 BP 2 / 2451 BP 2R / 2451 BP 04). ', N'01 - Imagens/02 - Depois/8200.jpeg', N'Foi alterado o layout das tubulações das bombas (2451 BP 2 / 2451 BP 2R / 2451 BP 04), eliminando 06 curvas (passando de 07 para apenas 1). Gerando menos perda de carga e maior eficiência das bombas. Com a melhoria estamos operando com apenas 02 bombas e sem sinal de transbordo na caixa.', NULL, N'Sim, problema resolvido', N'Avaliar as perdas de carga antes de condenar a eficiência das bombas', 0, NULL, N'A implantação do controle da vida útil das básculas por ciclos operacionais trouxe ganhos significativos relacionados ao tempo, como a redução de paradas inesperadas, diminuição do tempo gasto em manutenções corretivas e maior disponibilidade do equipamento. Com a previsibilidade proporcionada pelos ciclos e inspeções qualitativas, o planejamento tornou‑se mais ágil e preciso, reduzindo o tempo de resposta e evitando atrasos na execução. Além disso, o tempo de vida útil das básculas passou a ser melhor aproveitado, eliminando trocas antecipadas e diminuindo o tempo perdido com reformas profundas decorrentes de desgaste avançado.', '2026-02-12T00:00:00.000', '2026-02-20T09:29:07.000', 839373, NULL, 1);
INSERT INTO #PVC VALUES (8201, 81047909, 81048226, N'Melhora do método executivo para remover e instalar tambor de freio de rodas dos caminhões rodoviários. ', NULL, N'No Replication/Sem replicação', N'O método atual de remoção e instalação dos tambores de freio é realizado manualmente, apresentando riscos de segurança e ineficiência no processo.', N'Implementar sistema de apoio, Melhorar a segurança e a eficiência do processo, reduzindo o número de executantes necessários e minimizando o risco de acidentes, além de facilitar a execução da tarefa com menos esforço físico.', 10145, N'01 - Imagens/01 - Antes/8201.jpeg', N'A falta de carrinho de apoio e de pontos de pega adequados exige dois executantes e gera condições inseguras, com maior risco de acidentes, esforço excessivo e possível prensamento.', N'01 - Imagens/02 - Depois/8201.jpeg', N'SESMT e Manutenção de Leves criaram um carrinho elevador para facilitar a remoção e instalação dos tambores de freio, aumentando a segurança e a eficiência da atividade.', NULL, N'A implementação do carrinho elevador atende diretamente à meta estabelecida, abordando a declaração do problema e promovendo um ambiente de trabalho mais seguro e eficiente. As ações realizadas demonstram um progresso significativo em direção à segurança e à eficácia no processo de manutenção.', N'A integração entre SESMT e Manutenção gera soluções mais eficazes; pequenas modificações podem gerar grandes ganhos de segurança.', 0, NULL, N'A permanência da chave no equipamento.', '2026-01-13T00:00:00.000', '2026-02-20T09:56:19.000', 81047909, NULL, 3);
INSERT INTO #PVC VALUES (8202, 839373, 839373, N'Dispositivo troca bocal do moinhos de bolas', NULL, N'Concentration/Concentração', N'Impossibilidade de realizar a troca do bocal do moinho de bolas 2 com apenas a empilhadeira', N'Troca do bocal do bolas 2', 10362, N'01 - Imagens/01 - Antes/8202.jpeg', N'Empilhadeira com dificuldade de posicionando o bocal do moinho de bolas 2.', N'01 - Imagens/02 - Depois/8202.jpeg', N'Fabricação e instalação do dispositivo para troca do bocal do moinho de bolas 2. Permitindo a centralização e não só a instalação do novo bocal mas também a retirada do bocal "velho".', NULL, N'Sim, com o dispositivo foi possível executar a remoção do bocal "velho" e a instalação do novo bocal. Atividade executada com qualidade, prazo e segurança.', N'Avaliar as interferências das atividades na fase de planejamento', 0, NULL, N'Melhor performace do Equipamento.', '2025-12-16T00:00:00.000', '2026-02-20T09:59:25.000', 839373, NULL, 1);
INSERT INTO #PVC VALUES (8203, 81026611, 547627, N'Carregador Solar Portátil para Reutilização de Baterias', NULL, N'Projects/Projetos', N'As baterias descarregadas eram descartadas sem teste ou tentativa de recuperação, pois não havia sistema de recarga ou infraestrutura elétrica em campo. Isso gerava alto custo com novas baterias, desperdício ambiental, acúmulo de resíduos perigosos e aumento da logística interna.
INSERT INTO #PVC VALUES (8204, 1010730, 1010730, N'Digitized SLAM Card', NULL, N'Others/Outros', N'SLAM card has been updated for 2026 - easier to complete for permit office purposes as PDF ', N'Most efficient/easier way to complete SLAMs for Operations tasks', 0, N'01 - Imagens/01 - Antes/8204.jpeg', N'Previously SLAMs were filled out for Operations tasks by hand. Sometimes illegible, often outdated forms, and contamination of paperwork that would become a problem for the printers', N'01 - Imagens/02 - Depois/8204.jpeg', N'Digitized the new 2026 SLAM form with check and text boxes to ensure it is legible, can be filled out on any computer and review by all parties involved. Digital signature available for Coach review. Removes possibility of contamination.', N'https://globalvale.sharepoint.com/:b:/r/sites/POLLEADERSHIPTEAM/Shared%20Documents/POL%20Permit%20Office/VNL%20SLAM%20Card%202026%20-%20Fillable.pdf?csf=1&web=1&e=LU8IRa', N'Yes - much more efficient and consistent SLAMs with opportunities to improve/update', N'Digitizing documents is overall more efficient ', 0, NULL, N'Can reduce unnecessary fuel/boiler usage during winter months while heating', '2026-02-19T00:00:00.000', '2026-02-20T10:23:56.000', 1010730, NULL, 1);
INSERT INTO #PVC VALUES (8205, 839373, 839373, N'Anel de fixação do contra fluxo', NULL, N'Concentration/Concentração', N'Vazamento de material pela contra fluxo do moinho de bolas 2', N'Eliminar vazamento pelo contra fluxo', 10362, N'01 - Imagens/01 - Antes/8205.jpeg', N'Contra fluxo do moinho de bolas 2 não possuía flange de vedação, o que gerava o retorno de material para fora do moinho de bolas. ', N'01 - Imagens/02 - Depois/8205.jpeg', N'Confecção e instalação de um anel de borracha para vedação no contra fluxo do moinho de bolas 2', NULL, N'Sim, após a instalação do anel de borracha no contra fluxo não houve mais o vazamento de material no moinho de bolas 2', N'Focar na fontes geradoras de sujeira para eliminação das mesmas', 0, NULL, N'Faz mais rápido, mais Simples, com qualidade superior e facilita os demais processos após abertura.', '2025-12-17T00:00:00.000', '2026-02-20T10:24:36.000', 839373, NULL, 1);
INSERT INTO #PVC VALUES (8206, 839373, 839373, N'Anel para fixação do contra fluxo do moinho de bolas 2', NULL, N'Concentration/Concentração', N'Dificuldade de instalação do contra fluxo no bocal do moinho de bolas 2', N'Eliminar os batentes de fixação do bocal', 10362, N'01 - Imagens/01 - Antes/8206.jpeg', N'O conta fluxo era fixado no bocal do moinho de bolas 2 através de batentes (vide foto ao lado), gerando dificuldade para centralização e montagem do spout feeder.', N'01 - Imagens/02 - Depois/8206.jpeg', N'Foi elaborado um anel centralizador para fixação do contra fluxo no bocal do moinho de bolas 2', NULL, N'Sim, resolvido. O contrafluxo foi fixado de forma ágil e a centralização do spoud feeder foi realizada de forma segura', N'Reavaliar as atividade e identificar oportunidades de melhoria', 0, NULL, N'Avaliações inconsistentes ou subjetivas
INSERT INTO #PVC VALUES (8207, 839373, 839373, N'Instalação de talas nas vigas de sustentação do desviador das penerias', NULL, N'Concentration/Concentração', N'Para remoção do desviador das peneiras era necessário o corte das vigas de sustentação', N'Permitir a retirada do desviador sem a necessidade de corte das vigas', 10362, N'01 - Imagens/01 - Antes/8207.jpeg', N'As vigas de sustentação do desviador eram inteiriças, para a remoção do desviador era necessário o corte e a remoção das vigas.', N'01 - Imagens/02 - Depois/8207.jpeg', N'Instalação de talas nas vigas das estruturas do desviador. Permitindo a remoção do desviador sem a necessidade de corte nas viga da estrutura', NULL, N'Sim, para remoção do desviador não será mais necessário o corte das vigas', N'Avaliar os cenário e propor soluções', 0, NULL, NULL, '2025-12-17T00:00:00.000', '2026-02-20T11:03:26.000', 839373, NULL, 1);
INSERT INTO #PVC VALUES (8208, 81003828, 200415, N'HR Metrics coordinated and aligned', NULL, N'Others/Outros', N'Inconsistent metrics were cascaded across client groups. ', N'Consistency and Visibility of KPI''s', 10239, N'01 - Imagens/01 - Antes/8208.jpeg', N'Inconsistent or lack of HR Metrics across various client groups. ', N'01 - Imagens/02 - Depois/8208.jpeg', N'HR Coordinators are now creating monthly slide decks for all HRBP''s to ensure this data is visible and allows for HRBP''s to spend time analyzing instead of compiling data to address concerns regarding Headcount, Overtime, and Absenteeism. ', NULL, N'Yes', N'Consistency in monthly routines across all sites in Sudbury and PCR is key.', 0, NULL, N'Melhor controle das avaliações por fase, histórico automático, maior confiabilidade dos dados e suporte mais ágil à análise da maturidade.', '2026-01-30T00:00:00.000', '2026-02-20T11:10:34.000', 81003828, NULL, 1);
INSERT INTO #PVC VALUES (8209, 81006946, 81048624, N'SACA FILTRO SECADOR', NULL, N'Others/Outros', N'A remoção do filtro secador do caminhão é difícil porque ele geralmente fica instalado em um ponto de acesso limitado, próximo ao chassi ou atrás de outros componentes do sistema de ar comprimido. Essa posição reduz o espaço para manuseio de ferramentas, dificulta a visualização correta do encaixe e exige, muitas vezes, a remoção prévia de outras peças. Além disso, o acúmulo de sujeira e a fixação apertada podem aumentar o esforço necessário, tornando o procedimento mais demorado e trabalhoso.', N'Reduzir o tempo e o esforço necessário para a remoção do filtro secador, aumentando a segurança e a eficiência da atividade. Objetivos: Diminuir o tempo médio de remoção do componente. Reduzir riscos de acidentes e esforço físico excessivo do mecânico. Minimizar a necessidade de desmontagem de outras peças para acesso. Padronizar o procedimento com ferramentas adequadas e orientação técnica. Melhorar a ergonomia da atividade, facilitando o acesso ao local de instalação. Essas ações contribuem para maior produtividade, menor desgaste da equipe e redução de retrabalhos.', 10139, N'01 - Imagens/01 - Antes/8209.jpeg', N'A remoção do filtro secador do caminhão era realizada em um ponto de difícil acesso, com espaço reduzido para manuseio e pouca visibilidade. O procedimento não possuía padronização clara e dependia, muitas vezes, da experiência individual do mecânico.
INSERT INTO #PVC VALUES (8210, 839373, 839373, N'Movimentação spoutfeeder bolas 3', NULL, N'Concentration/Concentração', N'A movimentação do spoutfeeder do moinho de bolas 3 era realizada de forma manual através de catraca/tiffor', N'Automatizar a movimentação do spoutfeeder do moinho de bolas 3', 10307, N'01 - Imagens/01 - Antes/8210.jpeg', N'A movimentação do spoutfeeder era realizada com o auxilio de talha, tifor e empilhadeira. Exigindo um tempo elevado de movimentação.', N'01 - Imagens/02 - Depois/8210.jpeg', N'Foi instalado um motor hidráulico para movimentação do spoutfeeder do moinho de bolas 3. Facilitando a movimentação, diminuindo o tempo e o esforço necessário.', NULL, N'Sim, a movimentação do spoutfeeder foi realizada de forma eficaz e segura, passando de 360 min para 2min a remoção/instalação do spout', N'Avaliar os mecanismos e as possibilidades de solução', 0, NULL, N'Organização e Controle
INSERT INTO #PVC VALUES (8211, 134296, 134296, N'Monitoramento em tempo real  PM3501', NULL, N'Others/Outros', N'Ausência de um sistema de monitoramento remoto.  Riscos de exposição aos colaboradores.
INSERT INTO #PVC VALUES (8212, 537383, 537383, N'nível de óleo mancal soprador', NULL, N'Others/Outros', N'
INSERT INTO #PVC VALUES (8213, 125930, 81048243, N'CICLO DE BASDCULAMENTO - MCC', NULL, N'No Replication/Sem replicação', N'O método atual de monitoramento da vida útil das básculas é realizado exclusivamente por meio do horímetro, desconsiderando o real esforço operacional aplicado ao componente. Como o desgaste das básculas está diretamente associado ao número de ciclos de operação (abertura e fechamento) e ao modo de uso, o controle baseado somente em horas de funcionamento não representa fielmente o comportamento de degradação da estrutura.', N'Aplicação de técnicas de Manutenção Centrada na Confiabilidade (MCC) para controle da vida útil de básculas utilizando ciclos operacionais e indicador qualitativo de desgaste.', 10144, N'01 - Imagens/01 - Antes/8213.jpeg', N'O método atual de monitoramento da vida útil das básculas é realizado exclusivamente por meio do horímetro, desconsiderando o real esforço operacional aplicado ao componente. Como o desgaste das básculas está diretamente associado ao número de ciclos de operação (abertura e fechamento) e ao modo de uso, o controle baseado somente em horas de funcionamento não representa fielmente o comportamento de degradação da estrutura.
INSERT INTO #PVC VALUES (8214, 81022761, 81013738, N'Melhoria na chave de bloqueio ', NULL, N'Open Pit/Poço aberto', N'perca da chave de bloqueio por falta de fixação.', N'Não perder mais a chave de bloqueio ', 10144, N'01 - Imagens/01 - Antes/8214.jpeg', N'Antes como a chave não ficava em local fixo acabava perdendo com frequência.', N'01 - Imagens/02 - Depois/8214.jpeg', N'Antes a chave perdia e tinha que comprar outra. Agora a chave tá presa no equipamento evitando de perder, assim podemos reduzir o custo de tá comprando outra. ', NULL, N'Foi resolvido. Agora a chave não saí mais do equipamento 
INSERT INTO #PVC VALUES (8215, 471876, 471876, N'CONTROLE DE CAPELA', NULL, N'Others/Outros', N'Ausência de Monitoramento e performance', N'Melhorar monitoramento e performance', 10366, N'01 - Imagens/01 - Antes/8215.jpeg', N'Nas capelas antigas tínhamos diversos problemas devido a ausência de controlador, os parâmetros eram ajustados de fabrica através de placa eletrônica e portanto não tinha um padrão de monitoramento visível, que pudéssemos alterar com controles, isso impactava na rotina e tivemos diversos problemas de desvios nestes equipamentos.', N'01 - Imagens/02 - Depois/8215.jpeg', N'Com a nova troca de capelas, sugerimos ao novo fabricante, nosso problema com estes controles, temos um Laboratório acreditado e capelas sem controles de configuração, as novas vieram com controladores novos e moderno e com todas as indicações e alarmes de não conformidades, onde podemos ver os problemas ali existente.', NULL, N'resolvido', N'que observando e sugestões a gente consegue', 0, NULL, N'Garantir fechamento automático da porta, promovendo melhoria contínua em higiene, privacidade, organização e conservação do banheiro coletivo.', '2026-02-03T00:00:00.000', '2026-02-20T14:28:24.000', 471876, NULL, 1);
INSERT INTO #PVC VALUES (8216, 81030465, 81030465, N'Fita antiderrapante para becker de teflon', NULL, N'No Replication/Sem replicação', N'O béquer de Teflon, por possuir superfície externa lisa, apresentava risco de deslizamento durante o manuseio, ocasionando possibilidade de acidentes e perda de amostras.', N'Eliminar o risco de acidentes pelo deslizamento do béquer de Teflon', 10366, N'01 - Imagens/01 - Antes/8216.jpeg', N'O béquer de Teflon, por possuir superfície externa lisa, apresentava risco de deslizamento durante o manuseio, ocasionando possibilidade de acidentes e perda de amostras.', N'01 - Imagens/02 - Depois/8216.jpeg', N'Com a aplicação da fita antiderrapante nos béqueres de Teflon, eliminamos de forma eficaz o risco de deslizamento, prevenindo acidentes e perdas de amostras, além de aumentar a segurança durante as atividades laboratoriais.', NULL, N'Antes: O béquer de Teflon, por possuir superfície externa lisa, apresentava risco de deslizamento durante o manuseio, ocasionando possibilidade de acidentes e perda de amostras.
INSERT INTO #PVC VALUES (8217, 1015400, 1015400, N'Air Temperature DCS', NULL, N'Others/Outros', N'Previous ambient air temperature sensor utilized by the Utilities department was decommissioned ', N'To utilize another sensor on site ', 0, N'01 - Imagens/01 - Antes/8217.jpeg', N'Previous ambient air temperature sensor utilized by the Utilities department was decommissioned and IOF', N'01 - Imagens/02 - Depois/8217.jpeg', N'With the help of DCS we were able to find another outdoor air temperature sensor linked to DCS on site and add it back to the Utilities page. This helps control room operators monitor outdoor temperature trends to adjust the glycol temperature and steam booster during winter months. This allows for better overall sitewide temperature control which in turn can reduce fuel & boiler usage due to unnecessary heating', NULL, N'Yes', N'Importance of DCS trends', 0, NULL, NULL, '2026-02-04T00:00:00.000', '2026-02-20T14:47:01.000', 1015400, NULL, 1);
INSERT INTO #PVC VALUES (8218, 81020500, 81020500, N'Gerenciador de Notas', NULL, N'Open Pit/Poço aberto', N'Atualmente a abertura de notas é diretamente no SAP, sendo uma interface mais robusta e menos intuitiva, o preenchimento das notas como diagnostico/ problema e solução ficam apenas textuais com informações soltas a questão do usuário, o anexo de fotos embora seja possível não é habitual por ser necessário abrir nota novamente para anexar, e a inexistência de um Laudo padrão anexado, tempo de aproximadamente 10 min por nota.', N'Facilitar preenchimento, Padronizar Laudos  e otimizar tempo de abertura de notas', 10293, N'01 - Imagens/01 - Antes/8218.jpeg', N'Abertura diretamente no SAP, menos intuitivo, nota textual com informações a questão do usuário, o anexar fotos necessário reabrir SAP para anexar, e inexistência de um Laudo padrão.', N'01 - Imagens/02 - Depois/8218.jpeg', N'Interface intuitiva, agilidade (menos de 4min /nota), anexar fotos e laudos automático e padronizado.', NULL, N'ganho de 4 min por nota, foram 1252 notas abertas em 2025, 208 horas, 104 horas economizadas só de abertura de notas, fora horas de notas que são retrabalhadas por não identificarem local, ou ter que ir em campo verificar loca, e para planejar nota. 
INSERT INTO #PVC VALUES (8219, 81046238, 81046238, N'Kaizen - Ferramenta de Autoavaliação de Pit Stops', NULL, N'Others/Outros', N'Antes da implantação do aplicativo, a autoavaliação de maturidade dos pit stops no Complexo Salobo (usinas e britagens) era realizada por meio de planilhas em Excel. Esse método exigia preenchimento manual, consolidação posterior das informações e apresentava limitações de padronização, rastreabilidade e acompanhamento da evolução das avaliações ao longo do tempo.
INSERT INTO #PVC VALUES (8220, 81050431, 81058947, N'Pino de fixação e articulação do implemento GD53', NULL, N'Others/Outros', N'Diante da necessidade de compra um pino novo foi confeccionado um novo  ', N' economia', 10139, N'01 - Imagens/01 - Antes/8220.jpeg', N'sem a melhoria', N'01 - Imagens/02 - Depois/8220.jpeg', N'fabricado trava para o pino nao sacar', NULL, N'resolvido', N'economia', 2000, 1, N'MELHORES CONDIÇÕES DE TRABALHO', '2026-02-09T00:00:00.000', '2026-02-20T15:47:58.000', 81050431, NULL, 1);
INSERT INTO #PVC VALUES (8221, 81046238, 81046238, N'Ferramenta de Avaliação de Maturidade do Planejamento de Projetos', NULL, N'Others/Outros', N'Antes da implantação do aplicativo, a avaliação de maturidade no Complexo Salobo (usinas e britagens) era realizada por meio de planilhas em Excel. Esse método exigia preenchimento manual, consolidação posterior das informações e apresentava limitações de padronização, rastreabilidade e acompanhamento da evolução das avaliações ao longo do tempo.
INSERT INTO #PVC VALUES (8222, 530384, 530384, N'Confecção de adaptador para extensão da trava do macaco hidráulico', NULL, N'Others/Outros', N'processo de travamento, o operador precisava permanecer sob o equipamento, expondo‑se a risco. ', N'MACACO HIDRAULICO', 10139, N'01 - Imagens/01 - Antes/8222.jpeg', N'No processo de travamento, o operador precisava permanecer sob o equipamento, expondo‑se a risco. 
INSERT INTO #PVC VALUES (8223, 81046238, 81046238, N'Avaliação das Reuniões de Médio e Curto Prazo (Mapa de Paradas)', NULL, N'Others/Outros', N'Anteriormente a implantação do aplicativo, a avaliação de maturidade das reuniões eram conduzidas nas planilhas em excel com os anexos 04 e 05 do PGS-006053 Rev.3, sem possibilidade de arquivar evidências e com preenchimento manual, sendo feita a consolidação posterior das informações e apresentava limitações de padronização.', N'Meta acima de 95%', 10293, N'01 - Imagens/01 - Antes/8223.jpeg', N'Anteriormente a implantação do aplicativo, a avaliação de maturidade das reuniões eram conduzidas nas planilhas em excel com os anexos 04 e 05 do PGS-006053 Rev.3, sem possibilidade de arquivar evidências e com preenchimento manual, sendo feita a consolidação posterior das informações.', N'01 - Imagens/02 - Depois/8223.jpeg', N'Com a implantação do APP, o processo passou a ser digital, padronizado e centralizado, permitindo melhor controle das avaliações, histórico automático, maior confiabilidade e visibilidade dos dados avaliados, além de suporte mais ágil à análise da maturidade.', NULL, N'Sim.
INSERT INTO #PVC VALUES (8224, 81058081, 81058081, N'Horímetro das bombas', NULL, N'No Replication/Sem replicação', N'A partir do Gerenciamento da Rotina, identificou-se que o disparo automático dos Planos de Manutenção Preventiva por horímetro não funcionava desde sua criação. As horas registradas não coincidiam com o real, impedindo a geração das OMs preventivas e comprometendo a confiabilidade operacional.', N'Reestabelecer a integridade e aderência dos dados de horímetro das bombas para disparo de planos de manutenção', 10293, N'01 - Imagens/01 - Antes/8224.jpeg', N'A partir do Gerenciamento da Rotina, identificou-se que o disparo automático dos Planos de Manutenção Preventiva por horímetro não funcionava desde sua criação. As horas registradas não coincidiam com o real, impedindo a geração das OMs preventivas e comprometendo a confiabilidade operacional.
INSERT INTO #PVC VALUES (8225, 520044, 520044, N'Cesta para transporte de coleta', NULL, N'No Replication/Sem replicação', N'Para realizar a coleta de amostras hídricas dos lavadores, os recipientes eram transportados em uma bandeja, dificultando a locomoção na escada e trajeto, devido não ter uma alça, gerando risco de acidente.', N'Reduzir o risco de derramamento e queda das amostras', 10366, N'01 - Imagens/01 - Antes/8225.jpeg', N'Para realizar a coleta de amostras hídricas dos lavadores, os recipientes eram transportados em uma bandeja, dificultando a locomoção na escada e trajeto, devido não ter uma alça, gerando risco de acidente.', N'01 - Imagens/02 - Depois/8225.jpeg', N'Foi disponibilizado uma cesta com alças para realizar a coleta de amostras hídricas dos lavadores, tornando a atividade mais segura e eliminando o risco.', NULL, N'sim, foi substituído o recipiente de transporte das amostras e  reduzido o risco de derramamento e queda das amostras.', N'Através das melhorias podemos reduzir risco nas atividades', 0, NULL, N'This nuisance alarm was eliminated.', '2026-02-20T00:00:00.000', '2026-02-21T09:23:24.000', 520044, NULL, 2);
INSERT INTO #PVC VALUES (8226, 496890, 496890, N'PROTEÇÃO DE PAINEL ELETRONICO', NULL, N'Others/Outros', N'Os painéis das balança SCHENCK da área 700, estavam danificando os componentes devido água da chuva adentrar para dentro dos painéis eletrônicos.', N'ELIMINAR FALHA E QUEIMA DE COMPONENTES DEVIDO ÁGUA DA CHUVA', 10184, N'01 - Imagens/01 - Antes/8226.jpeg', N'Os painéis das balanças SCHENCK da área 700, estavam danificando, devido água da chuva.', N'01 - Imagens/02 - Depois/8226.jpeg', N'Foi fabricado uma proteção tipo cabana para evitar água da chuva adentrar ao painel e queimar os componentes eletrônicos', NULL, N'Problema resolvido, foi verificado que os painéis não estão acumulando água no seu interior', N'Os painéis eletrônicos precisam de uma conservação melhor, onde são instalados em área sem cobertura devido a agressividade do nosso minério.', 0, NULL, N'Reduced Risk', '2026-02-13T00:00:00.000', '2026-02-21T12:00:38.000', 496890, NULL, 1);
INSERT INTO #PVC VALUES (8227, 496890, 496890, N'Proteção sistema de lubrificação ET', NULL, N'Others/Outros', N'Falha no painel de lubrificação da extrusora devido contaminação por lama e água.', N'Eliminar falhas e queima do painel eletrônico devido contaminação', 10184, N'01 - Imagens/01 - Antes/8227.jpeg', N'Ocorrência de falha no sistema de lubrificação da extrusora, devido contaminação com água da chuva, e lama do prédio.
INSERT INTO #PVC VALUES (8228, 431296, 431296, N'Melhoria de Segurança e Privacidade: Porta com Fechamento Automático', NULL, N'Others/Outros', N'A porta do banheiro coletivo permanecia aberta por falta de mola de fechamento automático, afetando higiene, privacidade, organização e o conforto dos usuários.', N'Meta e objetivo: Garantir o fechamento automático da porta do banheiro coletivo, elevando higiene, privacidade e organização do ambiente com a instalação de mola adequada.', 10184, N'01 - Imagens/01 - Antes/8228.jpeg', N'A porta do banheiro coletivo permanecia aberta por falta de mola, causando falta de privacidade, exposição do ambiente e prejudicando higiene e organização.', N'01 - Imagens/02 - Depois/8228.jpeg', N'Instalada mola de fechamento automático e padronizado o uso em áreas comuns, garantindo mais higiene, privacidade, organização e melhor conservação do ambiente.', NULL, N'A solução atendeu à meta de garantir fechamento automático da porta, eliminando o problema de higiene, privacidade e organização causado pela falta da mola.', N'A importância de manter itens simples da infraestrutura em bom estado, evitando problemas recorrentes e garantindo ambientes funcionais e padronizados.', 0, NULL, N'porque a ação foi confeccionado suporte para coloca o sabão no contêiner 320 na mina, para equipe realiza higienização das mãos', '2026-02-19T00:00:00.000', '2026-02-21T13:48:24.000', 431296, NULL, 1);
INSERT INTO #PVC VALUES (8229, 81050085, 81040359, N'Rota Segura Operacional', NULL, N'Others/Outros', N'durante a atividades de inspeção e manutenção se tinha muita dificuldade em acessar o local devido devido acumulo de agua, gerando risco de escorregão, tropeço.', N'Eliminação de risco', 10362, N'01 - Imagens/01 - Antes/8229.jpeg', N'durante a atividades de inspeção e manutenção se tinha muita dificuldade em acessar o local devido devido acumulo de agua, gerando risco de escorregão, tropeço.', N'01 - Imagens/02 - Depois/8229.jpeg', N'Segurança operacional. reduzindo a exposição e riscos de queda tropeço e escorregões, trazendo segurança para as pessoas que transitam no local.', NULL, N'sim! ', N'segurança para as pessoas', 2, 1, N'otimização  de produção ', '2026-02-20T00:00:00.000', '2026-02-21T21:54:45.000', 81050085, NULL, 1);
INSERT INTO #PVC VALUES (8230, 81046149, 81046149, N'Portinhola de inspeção segura ', NULL, N'Others/Outros', N'Proteção do equipamento danificada do  tambor de retorno exposto , com risco  eminente  podendo causar esmagamento corte ou amputação de membros.
INSERT INTO #PVC VALUES (8231, 81013780, 81006979, N'DISPOSITIVO DE BLOQUEIO PARA CABINE', NULL, N'Others/Outros', N'Problema: Energia gravitacional não controlada durante manutenção na parte inferior da cabine, devido à falta de um controle de acesso adequado no cilindro de elevação. Impacto: Risco significativo de esmagamento ou aprisionamento de operadores e técnicos, podendo resultar em lesões graves ou fatalidades.Detecção: O problema foi identificado durante uma análise de risco e inspeção de segurança no local de trabalho, destacando a necessidade de implementação de medidas corretivas para atender aos requisitos do procedimento PRO 047734.', N'Garantir a segurança dos operadores e técnicos durante as atividades de manutenção na cabine, prevenindo a queda ou movimentação inesperada da mesma.', 10144, N'01 - Imagens/01 - Antes/8231.jpeg', N'Durante as atividades de manutenção na parte inferior da cabine, foi constatado que o sistema de elevação apresentava energia gravitacional não controlada, representando um risco significativo para os operadores e técnicos envolvidos. O cilindro responsável pela elevação da cabine possuía apenas uma trava mecânica simples, sem um controle de acesso adequado, o que não atende aos requisitos estabelecidos pelo procedimento PRO 047734 - Bloqueio, Desbloqueio, Identificação e Zero Energia – Equipamentos Móveis.Essa configuração inadequada permite que a cabine seja inadvertidamente acionada ou sofra queda, expondo os trabalhadores a graves riscos de esmagamento ou aprisionamento. A falta de um sistema eficaz de controle de energia e de bloqueio seguro pode resultar em acidentes sérios, comprometendo a segurança e a integridade física dos colaboradores.
INSERT INTO #PVC VALUES (8232, 81013780, 81006566, N'DISPOSITIVO DE BLOQUEIO PARA TAMPA DE  PROTEÇÃO DO MOTOR', NULL, N'Others/Outros', N'Problema: Risco de fechamento acidental da tampa de proteção do motor durante manutenção, podendo causar lesões graves ou amputações.Impacto: O problema é significativo pois pode resultar em acidentes graves, afetando a integridade física dos operadores e técnicos, além de impactar a produtividade e aumentar os custos de saúde e segurança.Detecção: O problema foi detectado durante uma análise de risco e inspeção de segurança no local de trabalho, identificando a necessidade de um dispositivo de bloqueio para a tampa de proteção do motor.', N'Garantir a segurança dos operadores e técnicos durante a manutenção do motor, impedindo o fechamento acidental da tampa de proteção e evitando lesões ou acidentes.', 10144, N'01 - Imagens/01 - Antes/8232.jpeg', N'Anteriormente, a tampa de proteção do motor do equipamento era sustentada por apenas dois cilindros, o que representava um risco significativo de segurança. Em caso de falha desses cilindros, havia um perigo iminente de esmagamento de membros, especialmente durante as atividades de manutenção do equipamento. Essa configuração aumentava a vulnerabilidade dos operadores e técnicos de manutenção, expondo-os a condições de trabalho inseguras. A possibilidade de falha dos cilindros e o subsequente colapso da tampa de proteção poderiam resultar em lesões graves, comprometendo a integridade física dos envolvidos.
INSERT INTO #PVC VALUES (8233, 81029922, 81029922, N'ESCADA DO FMDS', NULL, N'Others/Outros', N'DIFICULDADE DE ALCANSAR PARTES PARA PREENCHIMENTO.', N'FACILITAR PREENCHIMENTO DO FMDS', 10139, N'01 - Imagens/01 - Antes/8233.jpeg', N'Antes a realização do preenchimento do quadro de FMDS, foram identificadas dificuldades que impediram o acesso completo às partes do quadro do FMDS  necessárias para  colocar as informações devido as condições de ergonomia .', N'01 - Imagens/02 - Depois/8233.jpeg', N'Depois foi fabricado uma escada com apoio de mão com dois degraus para facilitar o preenchimento do FMDS , assim melhorando as condições de ergonomia e facilitando do preenchimento das informações.', NULL, N'ANTES NÃO TINHA BOAS CONDIÇÕES DE ERGONOMIA DURANTE O PREENCHIMENTO DO FMDS', N'MELHORAR CONDIÇÕES DE TRABALHO', 0, NULL, N'faster more effective way to clean floors, saves time. positive ergonomic effect from no longer needing to remove covers to clean trough', '2026-02-02T00:00:00.000', '2026-02-22T01:02:53.000', 81029922, NULL, 1);
INSERT INTO #PVC VALUES (8234, 123307, 81037838, N'Acesso Fácil', NULL, N'Others/Outros', N'O piso da área da flotação possui uma escada de acesso (dos moinhos para as caixas da flotação). Porém, quando ocorre transbordo das caixas, o local fica inacessível, com acúmulo de polpa no piso, tornando-o escorregadio. Nessas condições, operadores e equipe de manutenção precisam transitar pela área com risco de quedas e acidentes.', N'Eliminar quedas', 10054, N'01 - Imagens/01 - Antes/8234.jpeg', N'O piso da área da flotação possui uma escada de acesso (dos moinhos para as caixas da flotação). Porém, quando ocorre transbordo das caixas, o local fica inacessível, com acúmulo de polpa no piso, tornando-o escorregadio. Nessas condições, operadores e equipe de manutenção precisam transitar pela área com risco de quedas e acidentes.', N'01 - Imagens/02 - Depois/8234.jpeg', N'Foi confeccionada um segundo acesso( uma escada ), onde não se aproxima do material do transbordo, e de melhor acessibilidade para os operadores e mantenedores transitar. ', NULL, N'Sim, eliminou risco de quedas e fácil acessibilidade das pessoas que transitam na área, principalmente da manutenção com suas ferramentas.', N'VER E AGIR', 0, NULL, N'Confiabilidade das Frotas
INSERT INTO #PVC VALUES (8235, 81033365, 81048451, N'cadeado com única chave', NULL, N'Others/Outros', N'havia varias chaves e vários cadeados', N'diminuir excesso de chave', 10139, N'01 - Imagens/01 - Antes/8235.jpeg', N'Antes da mudança, o sistema de segurança utilizava vários cadeados. Isso gerava diversos inconvenientes: Excesso de chaves para carregar, Dificuldade para identificar a chave correta, Perda de tempo ao abrir ou fechar acessos.', N'01 - Imagens/02 - Depois/8235.jpeg', N'Após a substituição por apenas um cadeado com uma única chave, o cenário mudou significativamente: Maior praticidade no acesso, Simplicidade na organização, Economia de tempo, Redução de custos com cópias e reposições. ', NULL, N'Redução de custos com cópias e reposições. ', N'Economia de tempo', 0, NULL, N'REDUÇÃO DO RISCO NAS PARTES ROTATIVAS DA BOMBA, COM A IMPLEMETAÇÃO DA PROTEÇÃO DE GAXETAS', '2026-02-18T00:00:00.000', '2026-02-22T09:36:47.000', 81033365, NULL, 1);
INSERT INTO #PVC VALUES (8236, 498554, 498554, N'MAPA DE BOMBA DAS CACAMBA  PC2000/374D/318D/352D/988K/966L', NULL, N'Others/Outros', N'Ausência de Controle de Rastreabilidade e Histórico 
INSERT INTO #PVC VALUES (8237, 607148, 81036983, N'Reduce line plugging issues at NiCO3 FFT', NULL, N'Refining/Refino', N'The NiCO3 Thickener Underflow line in the CHP is an on-demand section of the plant, flowing to the NiCO3 Filter Feed Tank, that only flows when needed. It is common best practice for operators to flush this section of pipework/valving when we know it may be down for extended periods. Unfortunately due to varying tank levels and fluctuating Level indicators the Feed forward valve (FCV161) would open when the reset set point was reached (87%) allowing material to flow into the line for a brief second and then shutting immediately when the LI returned to normal.', N' Productivity Improvement', 10275, N'01 - Imagens/01 - Antes/8237.jpeg', N'FCV161 would interlock and close when the tank level reached 90%, then reset the interlock at 87%. This gap is too small and allowed short “blips” under 87% that would open FCV161 and flood the line with material.', N'01 - Imagens/02 - Depois/8237.jpeg', N'The reset point for the interlock was reduced from 87% to 80%. See PSRA Request #2993
INSERT INTO #PVC VALUES (8238, 607148, 81023580, N'CHP Ni Solution Tanks high level Nuisance Alarm', NULL, N'Refining/Refino', N'60 high level nuisance alarms per day', N'Reduce Risk', 10275, N'01 - Imagens/01 - Antes/8238.jpeg', N'60 high level nuisance alarms per day.', N'01 - Imagens/02 - Depois/8238.jpeg', N'Alarm changes as per PSRA #2997 so the alarm latches in and doesn''t reset until levels <80%.', NULL, N'This nuisance alarm was eliminated.', N'Nuisance alarms create unsafe environment', 0, NULL, N'FORAM CONFECCIONADAS CAIXAS PARA CONCENTRAR E ARMAZENAR AS CAPAS DE RÁDIOS. ASSIM O AMBIENTE FICA ORGANIZADO E FÁCILITA O ACESSO AOS RECURSOS. ', '2026-02-19T00:00:00.000', '2026-02-22T15:33:30.000', 607148, NULL, 1);
INSERT INTO #PVC VALUES (8239, 607148, 81024727, N'Installing sample port on newly fitted drain line on Zinc IX North Column', NULL, N'Refining/Refino', N'Ops reported that a newly installed sample collection line by MTCE is difficult to use due to the existing line spraying out horizontally across the Precip Lab test bench area and difficulty in sample collection due to wide mouth of line', N'Safety', 10275, N'01 - Imagens/01 - Antes/8239.jpeg', N'Ops reported that a newly installed sample collection line by MTCE is difficult to use due to the existing line spraying out horizontally across the Precip Lab test bench area and difficulty in sample collection due to wide mouth of line', N'01 - Imagens/02 - Depois/8239.jpeg', N' After raising issue with MTCE – they provided us with a downward elbow restrictor piece that allows for ease-of-use when collecting samples, reducing spray out of process material', NULL, N'Reduced Risk', N'Reduced Risk', 0, NULL, N'O Kaizen aumenta a confiabilidade da manutenção ao garantir a disponibilidade dos materiais no prazo correto, reduzindo paradas não programadas, evitando atrasos nas OMs e contribuindo para maior disponibilidade dos ativos e estabilidade da produção.', '2026-02-17T00:00:00.000', '2026-02-22T15:40:14.000', 607148, NULL, 1);
INSERT INTO #PVC VALUES (8240, 607148, 607939, N'Bleach Line Leak Detection Nuisance Alarm/Interlock', NULL, N'Refining/Refino', N'The leak detection currently activates when the pump speed output is 102.5% of a fixed "typical output" required to achieve 20 lpm. To make the system respond more accurately to the variation of tank level head pressure, a dynamic "typical output" calculation is implemented based on a formula. ', N'Reduce Nuisance Interlock/Alarm', 10275, N'01 - Imagens/01 - Antes/8240.jpeg', N'Bleach operation disruption due to nuisance alarm/interlock.', N'01 - Imagens/02 - Depois/8240.jpeg', N'PSRA #3000 raised to change formula to address issue.', NULL, N'Corrected design flaw', N'Design Flaw', 0, NULL, N'Disponibilidade física', '2026-02-11T00:00:00.000', '2026-02-22T15:47:34.000', 607148, NULL, 1);
INSERT INTO #PVC VALUES (8241, 81026444, 81026444, N'limpeza das mãos', NULL, N'Others/Outros', N'equipe de corretiva de campo de mina, sem sabão para lava as mãos, porque não tinha sabão .', N'limpeza e organização', 10140, N'01 - Imagens/01 - Antes/8241.jpeg', N'antes não tinha sabão no container da equipe corretiva na mina porque não tinha suporte.', N'01 - Imagens/02 - Depois/8241.jpeg', N'Foi confeccionado um suporte no container para  o sabão para todos os colaboradores da corretiva de todas as letras A,B,C,D. para melhora a higienização das mãos das equipe em campo na mina.', NULL, N'melhoria que não tinha sabão para equipe de corretiva realiza higienização das mãos, porque não tinha suporte no container para o sabão.', N'organização e padronização de intens. de segurança', 0, NULL, N'sim', '2026-02-17T00:00:00.000', '2026-02-22T16:24:51.000', 81026444, NULL, 1);
INSERT INTO #PVC VALUES (8242, 81016776, 81016776, N'Instalação e adaptação de roda fônica', NULL, N'No Replication/Sem replicação', N'No equipamento AL-720_04 foi identificado pela sala de controle que o equipamento estava com leitura errada e lendo a quantidade de giro a 3% havendo desbalanceamento de material e desligamento do mesmo , devido ao distanciamento da roda fônica 
INSERT INTO #PVC VALUES (8243, 81016776, 81040876, N'melhoria do estator ', NULL, N'Projects/Projetos', N'rompimento de cabos por oxidação e difícil nivelamento.', N'otimização para nivelamento e manutenção  ', 0, N'01 - Imagens/01 - Antes/8243.jpeg', N'rompimentos de cabo por oxidação e difícil manutenção', N'01 - Imagens/02 - Depois/8243.jpeg', N'fácil nivelamento melhorando capitação de objetos indevido (peças metálicas) e facilitando ajuste de altura do estator.', NULL, N'Na TR-730_04 
INSERT INTO #PVC VALUES (8244, 81022747, 475430, N'Bujão de abastecimento do tanque separador', NULL, N'Others/Outros', N'utilização de chaves inadequada', N'Reduzir o risco de acidente', 10166, N'01 - Imagens/01 - Antes/8244.jpeg', N'Antes o bujão tinha a cabeça sextavada.
INSERT INTO #PVC VALUES (8245, 81062511, 81062511, N'Better way to pick up Nickle of cell deck ', NULL, N'Refining/Refino', N'The tool that is provided is in efficient and takes more time.', N'pick up Nickle better way ', 0, N'01 - Imagens/01 - Antes/8245.jpeg', N'Picking up Nickle is slow and takes more time and effort and is not efficient.', N'01 - Imagens/02 - Depois/8245.jpeg', N'Using a roofing metal magnet for better performance ', NULL, N'YES', N'better ergonomic tools', 0, NULL, NULL, '2026-02-21T00:00:00.000', '2026-02-22T18:49:54.000', 81062511, NULL, 1);
INSERT INTO #PVC VALUES (8246, 387677, 387677, N'Replace floor drains with grating', NULL, N'Underground/Subterrâneo', N'old style floor trough covers were rusted, damaged, bent and broken. also very hard to lift cause they had to be removed for trough cleaning', N'crate a more effective way to drain and clean floors and direct feed to clean up pump', 10058, N'01 - Imagens/01 - Antes/8246.jpeg', N'floor trough covers are bent, damaged, rusted and heavy. must be removed to clean out troughs. hard to clean up feed in area.', N'01 - Imagens/02 - Depois/8246.jpeg', N'replaced with grating, creating an easier move efficient way to clean floors of feed and direct it to the cleanup pump. no need to remove to clean trough. lighter to move if needed.', NULL, N'eliminating overburden of time and effort. ', N'grating creates a easier way to clean troughs', 0, NULL, N'assertividade na programação de grande parada em automação ', '2026-02-21T00:00:00.000', '2026-02-22T19:18:36.000', 387677, NULL, 1);
INSERT INTO #PVC VALUES (8247, 81033938, 81033938, N'Painel de Reforma de componentes periféricos - Frota perfuração/Leves', NULL, N'Others/Outros', N'Até o momento, não existia um painel estruturado para acompanhamento das reformas de componentes periféricos das frotas de Perfuração e equipamentos Leves.', N'Monitorar o status das reformas junto aos fornecedores', 10023, N'01 - Imagens/01 - Antes/8247.jpeg', N'Até o momento, não existia um painel com os determinados status estruturado para acompanhamento das reformas de componentes periféricos das frotas de Perfuração e equipamentos Leves.', N'01 - Imagens/02 - Depois/8247.jpeg', N'Criar painel com os determinados status estruturado para acompanhamento das reformas de componentes periféricos das frotas de Perfuração e equipamentos Leves.
INSERT INTO #PVC VALUES (8248, 537728, 537728, N'DISPOSITIVO DE PROTEÇÃO DAS GAXETAS E PARTES MÓVEIS', NULL, N'Others/Outros', N'PARTE ROTATIVA DO TORPEDO DA BOMBA E  CAIXA DE GAXETA EXPOSTA , OFERECENDO RISCO, POIS A MESMA NÃO TEM PROTEÇÃO.', N'ELIMINAR O RISCO ASSOCIADO A ESSE EQUIPAMENTO OU ATIVIDADE', 10362, N'01 - Imagens/01 - Antes/8248.jpeg', N'PARTE ROTATIVA DA BOMBA ESTA EXPOSTA OFERECENDO RISCO AOS EXECUTORES DA ATIVIDADE EM QUESTÃO, TANTO A GAXETA COMO O EIXO DO TORPEDO ESTÃO VISIVEIS SEM PROTEÇÃO NO MOMENTO.', N'01 - Imagens/02 - Depois/8248.jpeg', N'FOI REALIZADO A FABRICAÇÃO DE UMA PROTEÇÃO TANTO PARA A PARTE ROTATIVA QUANTO PARA A PROTEÇÃO DAS GAXETAS E DO MOTOR, VISTO QUE SEM A PROTEÇÃO A ÁGUA DAS GAXETAS FICAVA SENDO PROJETADA ENCIMA DO MOTOR VINDO A OXIDAR A PARTE DE CIMA DO MESMO.', NULL, N'PROTEÇÃO JA MONTADA NO LOCAL REDUZINDO A POSIBILIDADE DE ACIDENTES ENVOLVENDO PARTES MÓVEIS', N'NENHUMA PARTE ROTATIVA PODE FICAR SEM PROTEÇÃO ', 0, NULL, N'manter o ambiente de trabalho organizado ', '2025-12-10T00:00:00.000', '2026-02-22T23:08:02.000', 537728, NULL, 1);
INSERT INTO #PVC VALUES (8249, 547924, 547924, N'BERÇO PARA MOITÃO DA PONTE ROLANTE', NULL, N'Others/Outros', N'PONTE ROLANTE SEM O BERÇO DE DESCANÇO DO MOITÃO COM RISCO DE TROPEÇO, BATIDA CONTRA.', N'ELIMINAR ACIDENTE', 10051, N'01 - Imagens/01 - Antes/8249.jpeg', N'PONTE ROLANTE SEM O BERÇO DE DESCANÇO PARA O MOITÃO', N'01 - Imagens/02 - Depois/8249.jpeg', N'CONFECCIONADO UM BERÇO DE DESCANÇO, E ASSIM ELIMINANDO RISCO DE ACIDENTE ', NULL, N'SIM, POIS ANTES NÃO HAVIA BERÇO PARA DESCANÇO DO MOITÃO.', N'NÃO PODEMOS ACEITAR MOITÃO FORA DO BERÇO', 0, NULL, N'Restabelecimento do sistema de refrigeração
INSERT INTO #PVC VALUES (8250, 543555, 543555, N'SUPORTE PARA TRANPORTE E CONTENÇÃO PARA O GALÃO DE HIDRÓXIDO DE SÓDIO 50%', NULL, N'Others/Outros', N'NÃO HAVIA CONTENÇÃO E TAMBÉM NÃO HAVIA FORMA SEGURA DE TRANPORTAR O GALÃO DE HIDRÓXIDO DE SÓDIO 50%', N'ELIMINAR RISCOS', 10198, N'01 - Imagens/01 - Antes/8250.jpeg', N'NÃO HAVIA CONTENÇÃO E TAMBÉM NÃO HAVIA FORMA SEGURA DE TRANPORTAR O GALÃO DE HIDRÓXIDO DE SÓDIO 50%', N'01 - Imagens/02 - Depois/8250.jpeg', N'DISPONIBILIZAMOS UMA CESTA COM CONTENÇÃO PARA TRANPORTE SEGURO DO GALÃO DE HIDRÓXIDO DE SÓDIO 50%, MINIMIZANDO RISCOS COM QUEDA E DERRAMAMENTO DE PRODUTO QUÍMICO. ', NULL, N'SIM, ELIMINAMOS O RISCO DE QUEDA E DERRAMAMENTO DE PRODUTO QUÍMICO.', N'CUIDADO ATIVO GENUINO', 0, NULL, N'Manter ambiente organizado.', '2026-02-22T00:00:00.000', '2026-02-23T06:39:53.000', 543555, NULL, 1);
INSERT INTO #PVC VALUES (8251, 553135, 553135, N'SUPORTE PARA CAPA DE RÁDIO ', NULL, N'Others/Outros', N'NÃO EXISTIA UM LOCAL DESTINADO AO ARMAZENAMENTO DAS CAPAS DE RÁDIO. GERANDO UM AMBIENTE BAGUNÇADO, DIFICULDADE DE ENCONTRAR AS MESMAS. ', N'TORNAR O AMBIENTE MAIS ORGANIZADO ', 10139, N'01 - Imagens/01 - Antes/8251.jpeg', N'NÃO EXISTIA UM LOCAL DESTINADO AO ARMAZENAMENTO DAS CAPAS DE RÁDIO. GERANDO UM AMBIENTE BAGUNÇADO, DIFICULDADE DE ENCONTRAR AS MESMAS. ', N'01 - Imagens/02 - Depois/8251.jpeg', N'FORAM CONFECCIONADAS CAIXAS PARA CONCENTRAR E ARMAZENAR AS CAPAS DE RÁDIOS. ASSIM O AMBIENTE FICA ORGANIZADO E FÁCILITA O ACESSO AOS RECURSOS. ', NULL, N'FORAM CONFECCIONADAS CAIXAS PARA CONCENTRAR E ARMAZENAR AS CAPAS DE RÁDIOS. ASSIM O AMBIENTE FICA ORGANIZADO E FÁCILITA O ACESSO AOS RECURSOS. ', N'ORGANIZAÇÃO SEMPRE', 0, NULL, N'Reducing risk for MSI for baggage handlers', '2026-02-20T00:00:00.000', '2026-02-23T10:48:58.000', 553135, NULL, 1);
INSERT INTO #PVC VALUES (8252, 81002116, 81002116, N'Padronização do Diligenciamento de Compras de Manutenção Fora da OM', NULL, N'Others/Outros', N'A realização de compras de materiais de manutenção por Requisições fora da OM impede o diligenciamento adequado, pois os materiais não ficam vinculados à ordem no sistema. Isso gera falta de visibilidade, atrasos na execução das OMs, perda de controle pelo PCM e impacto negativo na confiabilidade do planejamento de manutenção.', N'Estabelecer um processo padronizado de diligenciamento para compras de materiais de manutenção realizadas fora da Ordem de Manutenção (OM), garantindo visibilidade, rastreabilidade e controle dessas aquisições pelo PCM até a chegada do material, de forma a assegurar o cumprimento dos prazos das OMs e aumentar a confiabilidade do planejamento de manutenção.', 10184, N'01 - Imagens/01 - Antes/8252.jpeg', N'O processo padrão de compras de materiais de manutenção previa que todas as aquisições fossem realizadas diretamente por meio da Ordem de Manutenção (OM), garantindo o correto vínculo do material à ordem, ao centro de custo e permitindo o diligenciamento eficaz das compras.
INSERT INTO #PVC VALUES (8253, 541850, 541850, N'Chassi seguro', NULL, N'Open Pit/Poço aberto', N'O chassi do implemento do caminhão comboio Diesel_CV58 estava apresentando pontos de trinca na estrutura. A análise indicou que o dano foi provocado por esforço de torção recorrente, causado pela falta de travamento correto do implemento, o que gerou sobrecarga estrutural durante a operação.', N'Evitar  Trinca  no Chassi do Implemento', 10081, N'01 - Imagens/01 - Antes/8253.jpeg', N'Durante inspeção visual no implemento, foram identificados pontos de trinca na estrutura do chassi, localizados nas regiões destacadas na imagem. As trincas apresentam características típicas de fadiga estrutural, concentradas em áreas sujeitas a esforço mecânico elevado.', N'01 - Imagens/02 - Depois/8253.jpeg', N'Foi executada correção estrutural no chassi do implemento, com foco na eliminação do esforço de torção e no restabelecimento do travamento adequado, conforme descrito abaixo:
INSERT INTO #PVC VALUES (8254, 81020607, 509686, N'DIRECIONADO DE ESTEIRA', NULL, N'Others/Outros', N'Durante a remoção da esteira, a mesma apresenta um movimento involuntário, vindo a prender na parte inferior do comando final. O desprendimento é realizado de forma manual, expondo os empregados ao risco de prensamento.', N'melhoria', 10139, N'01 - Imagens/01 - Antes/8254.jpeg', N'Durante a remoção da esteira, a mesma apresenta um movimento involuntário, vindo a prender na parte inferior do comando final. O desprendimento é realizado de forma manual, expondo os empregados ao risco de prensamento.', N'01 - Imagens/02 - Depois/8254.jpeg', N'Confeccionado direcionador de esteira, posicionado de forma a impedir o movimento involuntário da mesma. Esse dispositivo elimina o risco de a esteira se prender na parte inferior do comando final.', NULL, N'sim', N'Eliminar exposição da equipe ao risco de prensamento.', 0, NULL, N'Increase of ITH drilling achieved in between shifts.', '2026-02-14T00:00:00.000', '2026-02-23T12:37:44.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8255, 81020607, 81013310, N'Fixação do protetor inferior', NULL, N'Others/Outros', N'Antes a proteção do protetor inferior era soldada, havendo a necessidade de corte e solda para realização de manutenção.', N'Otimização de tempo', 10139, N'01 - Imagens/01 - Antes/8255.jpeg', N'Antes a proteção do protetor inferior era soldada, havendo a necessidade de corte e solda para realização de manutenção.', N'01 - Imagens/02 - Depois/8255.jpeg', N'Instalado porcas, reestabelecendo a condição operacional do equipamento.', NULL, N'Sim', N'Eliminação da exposição ao risco de trabalho a quente.', 0, NULL, N'No more repacking of gold barrels required.', '2026-02-08T00:00:00.000', '2026-02-23T13:10:51.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8256, 538451, 538451, N' Iluminação Solar nos Banheiros Portáteis da mina (Salobo).', NULL, N'Others/Outros', N'Ausência de sistema de iluminação nos banheiros portáteis utilizados na área da mina, comprometendo condições de segurança, funcionalidade e conforto durante o uso, especialmente em períodos noturnos ou de baixa luminosidade.', N'🔹 Segurança e visibilidade A iluminação solar proporcionou visibilidade adequada durante o período noturno, contribuindo para a prevenção de incidentes e garantindo maior segurança para todos que utilizam as instalações. 🔹 Conforto e bem-estar Com iluminação eficiente, os banheiros tornam-se mais funcionais, melhorando a experiência dos colaboradores e favorecendo condições de higiene mais adequadas. 🔹 Eficiência e redução de custos O uso de energia solar diminui a dependência de fontes externas, reduz gastos com manutenção de sistemas elétricos tradicionais e gera economia a médio e longo prazo. 🔹 Sustentabilidade A iniciativa reforça práticas alinhadas às diretrizes socioambientais, promovendo o uso de energia limpa e contribuindo para a redução da nossa pegada energética.', 10017, N'01 - Imagens/01 - Antes/8256.jpeg', N'Ausência de sistema de iluminação nos banheiros portáteis utilizados na área da mina.
INSERT INTO #PVC VALUES (8257, 81020607, 81013310, N'Restauração de escada', NULL, N'Others/Outros', N'Durante a operação do equipamento a escada veio a danificar', N'melhoria', 10139, N'01 - Imagens/01 - Antes/8257.jpeg', N'Durante a operação do equipamento a escada veio a danificar', N'01 - Imagens/02 - Depois/8257.jpeg', N'Restauração de escada de acesso ao equipamento.', NULL, N'sim', N'Redução de custos com a compra de uma nova escada', 10000, 1, N'REALIZAR ATIVIDADE SEM O RISCO DE PROJEÇÃO DE ÓLEO.', '2026-02-13T00:00:00.000', '2026-02-23T13:40:25.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8258, 81020607, 81013310, N'Base do escarificador', NULL, N'Others/Outros', N'Durante a operação o escarificador veio a danificar.', N'Melhoria', 10139, N'01 - Imagens/01 - Antes/8258.jpeg', N'Durante a operação o escarificador veio a danificar.', N'01 - Imagens/02 - Depois/8258.jpeg', N'Confeccionado base reforçada do escarificador, garantindo uma maior vida útil ao ativo.', NULL, N'sim', N'Redução de custos ', 700000, 1, N'problema foi resolvido na causa raiz será replicado em toda frota como boa pratica, resultado obtidos equipamento com mais disponibilidade de operação eliminação de exposição ao risco das equipes de manutenção  ', '2026-02-15T00:00:00.000', '2026-02-23T14:01:32.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8259, 545887, 545887, N'Projeção de demandas automação ', NULL, N'Others/Outros', N'Ao passar as demandas de automação não tínhamos a comunicação de passar as necessidades para executar as atividades devido precisar de 1 estagio da maquina, ligada sem ser no gerador, soldador e outros, devido os programadores e planejadores não saberem dos pontos da atividades de automação foi criado essa melhoria, assertividade na comunicação e informação.', N'assertividade na execução na grande parada das EC''s ', 10023, N'01 - Imagens/01 - Antes/8259.jpeg', N'Ao passar as demandas de automação não tínhamos a comunicação de passar as necessidades para executar as atividades devido precisar de 1 estagio da maquina, ligada sem ser no gerador, soldador e outros, devido os programadores e planejadores não saberem dos pontos da atividades de automação foi criado essa melhoria, assertividade na comunicação e informação.', N'01 - Imagens/02 - Depois/8259.jpeg', N'Com essa melhoria os demais responsáveis pela grande parada do equipamento ficarão informados das necessidades que a automação precisa para executar as atividades na grande parada, melhorando a comunicação e a assertividade na programação de automação.', NULL, N'sim, pois agora estamos acompanhando o processo com respaldo e assim podendo cobrar a execução de automação com aderência na programação ', N'comunicação ', 0, NULL, N'Menos tempo de manutenção e zero desperdício de óleo.', '2026-02-17T00:00:00.000', '2026-02-23T15:24:00.000', 545887, NULL, 3);
INSERT INTO #PVC VALUES (8260, 81006571, 516988, N'GUARDA CORPO RUA DO SAG', NULL, N'Others/Outros', N'Antes  a barreira de isolamento para evitar queda de material na parte inferior da moagem era feita de andaimes', N'ELIMINAR USO DE ANDAIMES', 10362, N'01 - Imagens/01 - Antes/8260.jpeg', N'
INSERT INTO #PVC VALUES (8261, 81020607, 486330, N'Suporte para cadeados', NULL, N'Others/Outros', N'Nao tinha local adequado para guarda os cadeados.', N'Organizaçao ', 10139, N'01 - Imagens/01 - Antes/8261.jpeg', N'Nao tinha local adequado para guarda os cadeados', N'01 - Imagens/02 - Depois/8261.jpeg', N'Confeccionado suporte para organização dos cadeados', NULL, N'sim', N'Organizaçao, facil acesso', 0, NULL, NULL, '2026-02-13T00:00:00.000', '2026-02-23T15:39:36.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8262, 549736, 549736, N'Adaptação do ventilador ', NULL, N'Others/Outros', N'O Drive apresentou falha de fan cooler, ocasionada por defeito no ventilador interno, resultando em risco de sobreaquecimento e parada do equipamento.
INSERT INTO #PVC VALUES (8263, 81020607, 486330, N'Coletor para frasco spray', NULL, N'Others/Outros', N'Antes na tinha local adequado para armazenamento das lata de spray e lata de tintas.', N'segregação', 10139, N'01 - Imagens/01 - Antes/8263.jpeg', N'Antes na tinha local adequado para armazenamento das lata de spray e lata de tintas.', N'01 - Imagens/02 - Depois/8263.jpeg', N'Disponbilizado tambor para segregação de frascos de limpa contato e desengripante ', NULL, N'sim', N'Segregação correta ', 0, NULL, NULL, '2026-02-15T00:00:00.000', '2026-02-23T16:00:55.000', 81020607, NULL, 1);
INSERT INTO #PVC VALUES (8264, 81009414, 460285, N'Dorm 13 conversion to dry space', NULL, N'Underground/Subterrâneo', N'Currently there is a lack of locker space for rotational employees working UG on the site.  Current practice pack all items into bags when employees leave site, store away during time offsite.', N'Have required locker space for all personnel working UG to no require the packing of gear into bags, and reduce MSI risk to personnel handling bags', 10311, N'01 - Imagens/01 - Antes/8264.jpeg', N'UG workers would pack gear into bags when departing site to be transported and stored into sea containers by a dedicated crew.', N'01 - Imagens/02 - Depois/8264.jpeg', N'Dorm 13 was converted to a dry space. Furniture was removed, lockers ordered and installed using site resources to provide permanent locker space for 112 personnel. Eliminating over handling of bags reducing risk for MSI.', NULL, N'locker space in use and work to convert dorm 14 ongoing', N'Reduced handling of material', 0, NULL, N'Easier training new techs.', '2026-02-16T00:00:00.000', '2026-02-23T16:01:13.000', 81009414, NULL, 1);
INSERT INTO #PVC VALUES (8265, 81040073, 81047042, N'DISPOSITIVO DE FIXAÇÃO BOCAL', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE TINHA MUITOS DISPOSITIVOS DE TRAVAMENTO DO BOCAL DOS MOINHOS DE BOLAS, AUMENTANDO O TEMPO DE MANUTENÇÃO NA DESMONTAGEM E MONTAGEM DO BOCAL', N'REDUZIR TEMPO DE MONTAGEM', 10362, N'01 - Imagens/01 - Antes/8265.jpeg', N'ANTERIORMENTE TINHA MUITOS DISPOSITIVOS DE TRAVAMENTO DO BOCAL DOS MOINHOS DE BOLAS, AUMENTANDO O TEMPO DE MANUTENÇÃO NA DESMONTAGEM E MONTAGEM DO BOCAL', N'01 - Imagens/02 - Depois/8265.jpeg', N'FABRICADO NOVOS DISPOSITIVOS DE FIXAÇÃO DOS BOCAIS DO MOINHO. SENDO ELES MAIS RESISTENTES PRECISANDO APENAS DE 04 PEÇAS PARA FIXAÇÃO ! REDUZINDO TEMPO NAS MONTAGENS E DESMONTAGEM DO MESMO.', NULL, N'SIM, REDUÇÃO EM 60% DE TEMPO PARA DESMONTAR E MONTAR A FIXAÇÃO DOS BOCAIS.', N'SEMPRE PODEMOS MELHORAR', 0, NULL, NULL, '2026-02-10T00:00:00.000', '2026-02-23T16:14:06.000', 81040073, NULL, 1);
INSERT INTO #PVC VALUES (8266, 81038943, 81038943, N'Redução de transbordo caixa de overflow', NULL, N'Others/Outros', N'Caixas de overflow dos espessadores da usina 1 e 2 não suportam o fluxo de água e transbordam continuamente, enchendo a baia de contenção e impactando nas manutenções das bombas de polpa.', N'Redução de transbordo', 10293, N'01 - Imagens/01 - Antes/8266.jpeg', N'Baia de contenção com excesso de polpa devido transbordo das caixas de overflow dos espessadores', N'01 - Imagens/02 - Depois/8266.jpeg', N'Realizado projeto de conexão entre as caixas para serem vasos comunicantes, reduzindo o risco de transbordo e aumentando a performance de bombeamento.', NULL, N'Avaliando a performance, houve a redução de transbordo das caixas.
INSERT INTO #PVC VALUES (8267, 607870, 607870, N'Autonomous Drilling Tracking', NULL, N'Underground/Subterrâneo', N'Differentiate between autonomous ITH drilling  and regular autonomous drilling footage to keep track of the progress achieved in the program.', N'Monitor the Autonomous drilling to validate constant progression of the program.', 10238, N'01 - Imagens/01 - Antes/8267.jpeg', N'Operation logbook didn''t differentiate the different types of ITH drilling.', N'01 - Imagens/02 - Depois/8267.jpeg', N'A section was added in the superintendent report tab of the logbook to record autonomous drilling footage.', NULL, N'Autonomous drilling footage is now tracked. ', N'Data', 10000, 3, N'garantia de confiabilidade e disponibilidade do equipamento', '2026-02-19T00:00:00.000', '2026-02-23T18:02:51.000', 607870, NULL, 1);
INSERT INTO #PVC VALUES (8268, 81022870, 81022870, N'Packing gold sand into 3 or 4 barrels', NULL, N'Others/Outros', N'No gold packing procedures established to address higher weights of gold batches', N'To create procedures for packing gold sand into 3 or more barrels', 10114, N'01 - Imagens/01 - Antes/8268.jpeg', N'The old gold packing procedure dictates that a gold lot is to be packed into two drums. In those two drums, the operator is also required to take a sample for each drum. Each lot has always 2 gold samples taken.
INSERT INTO #PVC VALUES (8269, 92000157, 81007807, N'Controle de Condição de Básculas', NULL, N'Others/Outros', N'A condição das básculas não possui um controle estruturado e padronizado de inspeção. As avaliações de desgaste e condições estruturais são realizadas de forma reativa, normalmente quando o problema já está avançado. Como consequência: As demandas aparecem concentradas em um curto período, gerando sobrecarga; Dificuldade em priorizar com base na severidade real; Baixa previsibilidade de consumo de recursos.
INSERT INTO #PVC VALUES (8270, 81022743, 81008490, N'FERRAMENTA DE DRENAR ENERGIA RESIDUAL', NULL, N'Open Pit/Poço aberto', N'EXPOSIÇÃO AO RISCO DE ENERGIA RESIDUAL', N'ELIMINAR RISCO DE ACIDENTE', 10144, N'01 - Imagens/01 - Antes/8270.jpeg', N'AO REALIZAR TROCA DE MANGUEIRAS E O''RING DAS TOMADAS DE PRESSÃO DO CILINDRO DE ELEVAÇÃO, O COLABORADOR FICAVA EXPOSTO AO RISCO DE ENERGIA RESIDUAL QUE PODERIA CAUSAR PROJEÇÃO DE ÓLEO, E QUEIMADURAS E CORTES.', N'01 - Imagens/02 - Depois/8270.jpeg', N'CONFECCIONADO FERRAMENTA PARA DRENAR A ENERGIA RESIDUAL ACUMULADA NOS CILINDROS DE ELEVAÇÃO, EVITANDO EXPOSIÇÃO DE POSSÍVEIS EVENTOS AO COLABORADOR, ATIVIDADE REALIZADA COM MAIS SEGURANÇA E EFICIÊNCIA.', NULL, N'SIM, POIS O RISCO DE PROJEÇÃO DE ÓLEO FOI ELIMINADO.', N'EVITAR EXPOSIÇÃO A TIPOS DE ENERGIAS CONTIDAS EM ATIVIDADES ROTINEIRAS', 0, NULL, N'Potential hazards from an operator moving the wrong crane bridge, trolley or hoist.', '2026-02-21T00:00:00.000', '2026-02-23T21:08:07.000', 81022743, NULL, 1);
INSERT INTO #PVC VALUES (8271, 81047450, 81048611, N'PROTEÇÃO PARA TAMPA DE ACESSO AO TENSOR DE ESTEIRA NA FROTA DE TRATOR DE ESTEIRAS D10 E D11 CAT ', NULL, N'Others/Outros', N'durante a operação com trator de esteiras D10T E D11T CAT, a tampa de acesso a válvula tensora da esteira ficavam expostas a impacto por blocos ocasionando a quebra da fixação da mesma, gerando corretivas constantes, e contaminando o componente internamente com agua e lama gerando alto custo e exposição ao risco das equipes de manutenção EX; esmagamento Prensamento movimentação de cargas.', N'SEGURANÇA E PRODUTIVIDADE ', 10318, N'01 - Imagens/01 - Antes/8271.jpeg', N'durante a operação com trator de esteiras D10T E D11T CAT, a tampa de acesso a válvula tensora da esteira ficavam expostas a impacto por blocos ocasionando a quebra da fixação da mesma, gerando corretivas constantes, e contaminando o componente internamente com agua e lama gerando alto custo e exposição ao risco das equipes de manutenção EX; esmagamento Prensamento movimentação de cargas.  ', N'01 - Imagens/02 - Depois/8271.jpeg', N'Foi confeccionado uma proteção para tampa do truck que da acesso a válvula tensora  utilizando uma borracha de correia transportadora fixa e de fácil acesso a válvula para manutenções preservando a integridade do componente e evitando quebras prematuras.', NULL, N'problema foi resolvido na causa raiz será replicado em toda frota como boa pratica ', N'problema foi resolvido na causa raiz será replicado em toda frota como boa pratica ', 200, 1, NULL, '2026-02-21T00:00:00.000', '2026-02-23T22:22:27.000', 81047450, NULL, 1);
INSERT INTO #PVC VALUES (8272, 502383, 502383, N'Acesso para completar óleo', NULL, N'Open Pit/Poço aberto', N'Difícil acesso para completar óleo na maioria das vezes com derramamento de óleo.', N'Eliminar derramamento de óleo e difícil acesso ao completar', 10362, N'01 - Imagens/01 - Antes/8272.jpeg', N'Difícil acesso ao completar nível de óleo não tendo nem como posicionar o funil o que ocasiona derramamento de óleo e consequentemente tendo que fazer limpeza na contenção.', N'01 - Imagens/02 - Depois/8272.jpeg', N'Eliminação de derramamento de óleo, eliminação de limpeza pós completar óleo, e menos tempo de trabalho.', NULL, N'não temos mais desperdício de óleo e nem de tempo de mão de obra.', N'podemos eliminar ou minimizar desperdícios', 0, NULL, N'We will save signigficant time troubleshooting the hydraulic valve issues as they arise with all this documentation and schematics. Last failure we lost a full shift troubleshooting the cabinet before we found the valve that was the issue.', '2026-02-20T00:00:00.000', '2026-02-24T00:41:09.000', 502383, NULL, 1);
INSERT INTO #PVC VALUES (8273, 81032668, 81032668, N'SUPORTE PARA ARTE DA BOIA', NULL, N'Others/Outros', N'A GUIA É INTERMITENTE OCASIONANDO EMPENO NA ARTE VINDO A INTEFERIR NA LEITURA DO NITE', N'ELIMINAR A POSSIBILIDADE DO EMPENO DA BOIA', 10031, N'01 - Imagens/01 - Antes/8273.jpeg', N'ANTES A GUIA DA BOIA ERA INTERMINTENTE OCASIONANDO EMPENO DA ARTE, VINDO A INTERFERIR NA LEITURA DO NITE', N'01 - Imagens/02 - Depois/8273.jpeg', N'FOI INSTALADO UM TUBO COM DIMENSÃO MAIOR SERVINDO COMO GUIA PARA ELIMINAR A POSSBILIDADE DE EMPENO DA MESMA', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'ANTES A GUIA DA BOIA ERA INTERMINTENTE OCASIONANDO EMPENO DA ARTE, VINDO A INTERFERIR NA LEITURA DO NITE', N'PEQUENOS AJUSTES TRAZEM GRANDES SOLUÇÕES', 0, NULL, N'Savings on some faulty crimps and hoses will be expected throughout this year, as well as the reduction in downtime as there should be less failures with properly crimped hoses and components.', '2026-02-23T00:00:00.000', '2026-02-24T01:37:28.000', 81032668, NULL, 2);
INSERT INTO #PVC VALUES (8274, 81047450, 81047450, N'CONTROLE DE INSUMO DE BATERIAS E GÁS', NULL, N'Refining/Refino', N'MELHORIA NA ORGANIZAÇÃO, DISPONIBILIZAÇÃO DO RECURSO E ORDENAÇÃO DE CONSUMO DO MESMO.', N'MELHORIA NA ORGANIZAÇÃO, DISPONIBILIZAÇÃO DO RECURSO E ORDENAÇÃO DE CONSUMO DO MESMO.', 10318, N'01 - Imagens/01 - Antes/8274.jpeg', N'CONSUMO DE INSUMOS DESORDENADO QUEBRANDO CICLO ENTRE AS EQUIPES OCASIONANDO IMPACTO NAS ATIVIDADES POR FALTA DE INSUMOS.', N'01 - Imagens/02 - Depois/8274.jpeg', N'CONTROLE DE INSUMO DE BATERIAS E GÁS COM FLUXO DEFINIDO DE MAXIMO E MININO.', NULL, N'MATURIDADE NO PRECESSO DE MANUTENÇÃO ', N'AGILIDADE DE PROCESSOS ENTRE AS EQUIPES ', 20, 1, N'Removal of various hazards by installing this mini split system. Portable ac units are gone - No more leaks. Portable space heaters are gone - No more fire hazards, and doors remain closed and sealed, eliminating atmospheric contaminants from entering the area.', '2026-02-22T00:00:00.000', '2026-02-24T02:54:38.000', 81047450, NULL, 1);
INSERT INTO #PVC VALUES (8275, 502383, 502648, N'Plataforma acesso Válvula', NULL, N'Open Pit/Poço aberto', N'Solicitação de andaime em PGU para fechar válvula de água de serviço da filtragem por ser muita alta.', N'Eliminar uso de andaime', 10362, N'01 - Imagens/01 - Antes/8275.jpeg', N'Dificuldade de acesso a válvula de água de serviço para fechar e dar manutenção na linha, sempre havendo necessidade de solicitação de montagem de andaime.', N'01 - Imagens/02 - Depois/8275.jpeg', N'Foi fabricado e instalado uma plataforma para eliminar condição de montagem de andaime assim reduzindo custo e também tempo de manutenção e espera.', NULL, N'Com a instalação dessa plataforma não á mais a necessidade de montagem de andaime.', N'podemos reduzir custos e tempo de manutenção', 0, NULL, N'Com a nova ferramenta, passamos a cumprir integralmente o prazo de entrega das limpezas do caminho crítico, alcançando ainda uma antecipação média de 1 hora na conclusão das atividades.', '2026-02-10T00:00:00.000', '2026-02-24T03:23:56.000', 502383, NULL, 1);
INSERT INTO #PVC VALUES (8276, 81047450, 81047017, N'TRAVA DO DRAWBAR  DA MOTONIVELADORA 24M ', NULL, N'Open Pit/Poço aberto', N'Durante a operação com a motoniveladora 24M CAT, existe o risco do rompimento do pino bola que fixa a mesa de giro com o chassi quando isso ocorre danifica diversos componentes do equipamento como cilindros de direção barra e exposição ao risco para a equipe de manutenção como içamento e Prensamento de membros.', N'MITIGAR EVITAR EXPOSIÇÃO AO RISCO ', 10318, N'01 - Imagens/01 - Antes/8276.jpeg', N'Durante a operação com a motoniveladora 24M CAT, existe o risco do rompimento do pino bola que fixa a mesa de giro com o chassi quando isso ocorre danifica diversos componentes do equipamento como cilindros de direção barra e exposição ao risco para a equipe de manutenção como içamento e Prensamento de membros. ', N'01 - Imagens/02 - Depois/8276.jpeg', N'Foi confeccionado um dispositivo com corrente fixando o chassi com a mesa caso o pino venha romper a mesa ficará fixa impossibilitando a projeção e quebra dos componentes inferiores.', NULL, N'Foi confeccionado um dispositivo com corrente fixando o chassi com a mesa caso o pino venha romper a mesa ficará fixa impossibilitando a projeção e quebra dos componentes inferiores.', N'REDUÇÃO E EXPOSIÇÃO AO RISCO ', 100, 1, NULL, '2026-02-22T00:00:00.000', '2026-02-24T03:26:39.000', 81047450, NULL, 1);
INSERT INTO #PVC VALUES (8277, 460346, 81045575, N'3 Stage Extraction Settler Update', NULL, N'Refining/Refino', N'Labelling for the circuit configuration in CuSX did not match the actually circuit configuration.', N'Update the labels', 0, N'01 - Imagens/01 - Antes/8277.jpeg', N'Old label removed from settler', N'01 - Imagens/02 - Depois/8277.jpeg', N'New label added to settler.  All extraction settlers were updated.', NULL, N'yes', N'Changes require simple updates', 0, NULL, NULL, '2026-02-23T00:00:00.000', '2026-02-24T05:42:36.000', 460346, NULL, 1);
INSERT INTO #PVC VALUES (8278, 200959, 300829, N'PO Naming Standardization', NULL, N'Others/Outros', N'Superintendents could not track adherence to budget when requisitions for services were entered.', N'Improved budget visibility', 10238, N'01 - Imagens/01 - Antes/8278.jpeg', N'Requisitions were entered with only the vendor name resulting in superintendents having indication regarding their status when compared to budget.', N'01 - Imagens/02 - Depois/8278.jpeg', N'POs now have Vendor name, time period covered which are based on the budget.  Superintendents can clearly see when there is a #2 issued they are exceeding their budgeted amount', NULL, N'The problem was solved as Superintendents now have visibility on what they are approving and whether or not they are within their budgets.', N'Improved visibility for contractor utilization prompts conversations regarding whether contractor work is being used effectively.', 50, 3, N'A facilidade para encontrar o leitor aumentou pois agora ele tem um local especifico, melhorando o processo de recebimento das amostras.', '2026-01-30T00:00:00.000', '2026-02-24T08:42:57.000', 200959, NULL, 1);
INSERT INTO #PVC VALUES (8279, 1009465, 1009465, N'Improved pricing for LH''s blue sheathing tape', NULL, N'No Replication/Sem replicação', N'Current supplier of MM 13095456 was charging prices that felt reflective of the general public. ', N'Improve pricing to reflect LH''s high volume of Tuck Tape brand blue sheathing tape', 10310, N'01 - Imagens/01 - Antes/8279.jpeg', N'Supplier was requesting contract price increases for MM 13095456 (blue sheathing tape) which made the material equal to or more expensive than the general public purchasing from a big box store.', N'01 - Imagens/02 - Depois/8279.jpeg', N'MM 13095456 was competitively sourced, out of process queue, to improve purchase price from CAD$17.65 to 13.81/unit. Long Harbour consumes on average 5900 units annually, netting approximately CAD$22,656.00', NULL, N'Cost increases were not only avoided, but purchase price was significantly reduced.', N'When a vendor is requesting price increases, valid with a market check when possibly', 22656, 3, N'Otimização de tempo na manutenção ', '2026-01-21T00:00:00.000', '2026-02-24T08:54:00.000', 1009465, NULL, 1);
INSERT INTO #PVC VALUES (8280, 499302, 81055394, N'Base Extrator Sucatas', NULL, N'Others/Outros', N'O painel e transformador do Extrator de sucatas do TC11, encontrava-se apoiado no piso, sem nenhuma proteção contra poeiras e umidade (agua), isto poderia causar falhas prematuras nos componentes e comprometer todo o nosso sistema de correias, pois é este equipamento que garante a remoção de sucatas de ferro do material transportador e garante a confiabilidade das nossas correias.', N'Garantir confiabilidade do extrator de sucatas', 10294, N'01 - Imagens/01 - Antes/8280.jpeg', N'Transformador e painel apoiados no piso, sem nenhum tipo de proteção contra umidade (agua) e exposto ao concentrado de cobre que é extremamente corrosivo.', N'01 - Imagens/02 - Depois/8280.jpeg', N'Fabricado e Instalado bases de apoio para o painel e transformador do extrator de sucatas, assim evitar que os componentes possam dar defeitos prematuramente.', NULL, N'problema resolvido', N'fazer o baisco, garante a confiabilidade e disponibilidade dos equipamentos', 0, NULL, N'Expect to continue to see reduced silver (<1% Ag) in CuNiSiO2 reverts.', '2026-02-20T00:00:00.000', '2026-02-24T09:24:02.000', 499302, NULL, 1);
